-- Name: add_related_job(uuid, text, integer, text, text, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_related_job(p_source_job_id uuid, p_division text DEFAULT 'reconstruction'::text, p_priority integer DEFAULT 3, p_type_of_loss text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text, p_project_manager_id uuid DEFAULT NULL::uuid, p_lead_tech_id uuid DEFAULT NULL::uuid, p_invoiced_value numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_source jobs;
  v_claim  claims;
  v_job_id uuid;
  v_job    jsonb;
BEGIN
  SELECT * INTO v_source FROM jobs WHERE id = p_source_job_id;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'Source job not found';
  END IF;
  IF v_source.claim_id IS NULL THEN
    RAISE EXCEPTION 'Source job has no claim — cannot add related job';
  END IF;
  SELECT * INTO v_claim FROM claims WHERE id = v_source.claim_id;

  INSERT INTO jobs (
    division, source, phase, priority, status,
    insured_name, client_phone, client_email,
    address, city, state, zip,
    type_of_loss, date_of_loss,
    insurance_company, claim_number, policy_number,
    adjuster_name, adjuster_phone, adjuster_email, cat_code,
    project_manager_id, lead_tech_id, internal_notes,
    primary_contact_id, claim_id,
    invoiced_value, ar_status,
    created_at, updated_at
  ) VALUES (
    p_division::job_division,
    v_source.source,
    'job_received',
    p_priority,
    'active',
    v_source.insured_name,
    v_source.client_phone,
    v_source.client_email,
    COALESCE(v_claim.loss_address, v_source.address),
    COALESCE(v_claim.loss_city,    v_source.city),
    COALESCE(v_claim.loss_state,   v_source.state),
    COALESCE(v_claim.loss_zip,     v_source.zip),
    COALESCE(NULLIF(p_type_of_loss, ''), v_source.type_of_loss),
    v_source.date_of_loss,
    COALESCE(v_claim.insurance_carrier, v_source.insurance_company),
    COALESCE(v_claim.insurance_claim_number, v_source.claim_number),
    v_claim.policy_number,
    v_source.adjuster_name,
    v_source.adjuster_phone,
    v_source.adjuster_email,
    v_source.cat_code,
    COALESCE(p_project_manager_id, v_source.project_manager_id),
    p_lead_tech_id,
    NULLIF(p_internal_notes, ''),
    v_source.primary_contact_id,
    v_source.claim_id,
    COALESCE(p_invoiced_value, 0),
    CASE WHEN p_invoiced_value > 0 THEN 'invoiced' ELSE 'open' END,
    now(), now()
  )
  RETURNING id INTO v_job_id;

  IF v_source.primary_contact_id IS NOT NULL THEN
    INSERT INTO contact_jobs (contact_id, job_id, role, is_primary)
    VALUES (v_source.primary_contact_id, v_job_id, 'primary_client', true)
    ON CONFLICT DO NOTHING;
  END IF;

  SELECT to_jsonb(j) INTO v_job FROM (SELECT * FROM jobs WHERE id = v_job_id) j;

  RETURN jsonb_build_object(
    'job',          v_job,
    'claim_id',     v_source.claim_id,
    'claim_number', v_claim.claim_number
  );
END;
$$;


