--
-- Name: admin_clock_out_entry(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_clock_out_entry(p_id uuid, p_actor_id uuid, p_clock_out timestamp with time zone DEFAULT now()) RETURNS public.job_time_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_e job_time_entries%ROWTYPE; v_paused numeric; v_hours numeric;
begin
  if not is_time_admin(p_actor_id) then raise exception 'NOT_AUTHORIZED' using errcode='P0001'; end if;
  select * into v_e from job_time_entries where id=p_id;
  if v_e.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
  if v_e.clock_out is not null then raise exception 'ALREADY_CLOSED' using errcode='P0001'; end if;
  if v_e.clock_in is not null then
    v_paused := coalesce(v_e.total_paused_minutes,0);
    if v_e.paused_at is not null then v_paused := v_paused + greatest(0, extract(epoch from (p_clock_out - v_e.paused_at))/60); end if;
    v_hours := least(24, greatest(0, extract(epoch from (p_clock_out - v_e.clock_in))/3600 - v_paused/60));
    update job_time_entries set clock_out=p_clock_out, on_site_end=coalesce(on_site_end,p_clock_out), hours=v_hours, paused_at=null, total_paused_minutes=round(v_paused::numeric,2), updated_at=now() where id=p_id returning * into v_e;
  else
    update job_time_entries set clock_out=p_clock_out, hours=0, travel_minutes=coalesce(travel_minutes, least(1440, greatest(0, round(extract(epoch from (p_clock_out - v_e.travel_start))/60.0,1)))), updated_at=now() where id=p_id returning * into v_e;
  end if;
  insert into system_events (event_type, entity_type, entity_id, actor_id, job_id, payload) values ('time_entry.admin_clocked_out','job_time_entry', v_e.id, p_actor_id, v_e.job_id, jsonb_build_object('clock_out', p_clock_out));
  return v_e;
end; $$;


--
-- Name: admin_upsert_time_entry(uuid, uuid, uuid, uuid, date, numeric, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, numeric, numeric, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_time_entry(p_actor_id uuid, p_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid, p_job_id uuid DEFAULT NULL::uuid, p_work_date date DEFAULT NULL::date, p_hours numeric DEFAULT NULL::numeric, p_clock_in timestamp with time zone DEFAULT NULL::timestamp with time zone, p_clock_out timestamp with time zone DEFAULT NULL::timestamp with time zone, p_travel_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_on_site_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_travel_minutes numeric DEFAULT NULL::numeric, p_total_paused_minutes numeric DEFAULT NULL::numeric, p_work_type text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_override_approved boolean DEFAULT false) RETURNS public.job_time_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_old job_time_entries%ROWTYPE; v_new job_time_entries%ROWTYPE; v_emp uuid; v_ts timestamptz; v_ci timestamptz; v_ose timestamptz; v_co timestamptz;
begin
  if not is_time_admin(p_actor_id) then raise exception 'NOT_AUTHORIZED' using errcode='P0001'; end if;
  if p_id is not null then
    select * into v_old from job_time_entries where id=p_id;
    if v_old.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
    if v_old.approved and not p_override_approved then raise exception 'ENTRY_APPROVED_LOCKED' using errcode='P0001'; end if;
  end if;
  v_emp := coalesce(p_employee_id, v_old.employee_id);
  v_ts := coalesce(p_travel_start, v_old.travel_start); v_ci := coalesce(p_clock_in, v_old.clock_in);
  v_ose := coalesce(p_on_site_end, v_old.on_site_end); v_co := coalesce(p_clock_out, v_old.clock_out);
  if v_ts is not null and v_ci is not null and v_ci < v_ts then raise exception 'BAD_ORDER_clock_in_before_travel' using errcode='P0001'; end if;
  if v_ci is not null and v_ose is not null and v_ose < v_ci then raise exception 'BAD_ORDER_on_site_end_before_clock_in' using errcode='P0001'; end if;
  if v_ose is not null and v_co is not null and v_co < v_ose then raise exception 'BAD_ORDER_clock_out_before_on_site_end' using errcode='P0001'; end if;
  if v_ci is not null and v_co is not null and v_co < v_ci then raise exception 'BAD_ORDER_clock_out_before_clock_in' using errcode='P0001'; end if;
  if v_co is null and v_ts is not null then
    if exists (select 1 from job_time_entries where employee_id=v_emp and clock_out is null and travel_start is not null and id <> coalesce(p_id,'00000000-0000-0000-0000-000000000000')) then
      raise exception 'OPEN_ENTRY_EXISTS' using errcode='P0001'; end if;
  end if;
  if p_id is null then
    if v_emp is null or p_job_id is null then raise exception 'MISSING_REQUIRED_FIELDS' using errcode='P0001'; end if;
    insert into job_time_entries (employee_id, job_id, work_date, hours, work_type, description, notes, travel_start, clock_in, on_site_end, clock_out, travel_minutes, total_paused_minutes, entered_by, auto_continued, source)
    values (v_emp, p_job_id, coalesce(p_work_date,(now() at time zone 'America/Denver')::date), coalesce(p_hours,0), coalesce(p_work_type,'field'), p_description, p_notes, v_ts, v_ci, v_ose, v_co, p_travel_minutes, coalesce(p_total_paused_minutes,0), p_actor_id, false, 'admin')
    returning * into v_new;
  else
    update job_time_entries set employee_id=v_emp, job_id=coalesce(p_job_id,v_old.job_id), work_date=coalesce(p_work_date,v_old.work_date),
      hours=coalesce(p_hours,v_old.hours), work_type=coalesce(p_work_type,v_old.work_type), description=coalesce(p_description,v_old.description),
      notes=coalesce(p_notes,v_old.notes), travel_start=v_ts, clock_in=v_ci, on_site_end=v_ose, clock_out=v_co,
      travel_minutes=coalesce(p_travel_minutes,v_old.travel_minutes), total_paused_minutes=coalesce(p_total_paused_minutes,v_old.total_paused_minutes),
      auto_continued=false, updated_at=now() where id=p_id returning * into v_new;
  end if;
  insert into system_events (event_type, entity_type, entity_id, actor_id, job_id, payload)
  values (case when p_id is null then 'time_entry.admin_created' else 'time_entry.admin_updated' end, 'job_time_entry', v_new.id, p_actor_id, v_new.job_id, jsonb_build_object('override_approved', p_override_approved));
  return v_new;
end; $$;


--
-- Name: apply_midnight_clock_split(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_midnight_clock_split() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_started timestamptz := now();
  v_count   int := 0;
  v_e       record;
  v_cap     timestamptz;
  v_paused  numeric;
  v_hours   numeric;
  v_emp     text;
begin
  for v_e in
    select * from job_time_entries
    where clock_out is null
      and travel_start is not null
      and work_date < (now() at time zone 'America/Denver')::date
    order by work_date asc, created_at asc
  loop
    v_cap := ((v_e.work_date::text || ' 23:59:59')::timestamp at time zone 'America/Denver');

    if v_e.clock_in is not null then
      v_paused := coalesce(v_e.total_paused_minutes, 0);
      if v_e.paused_at is not null then
        v_paused := v_paused + greatest(0, extract(epoch from (v_cap - v_e.paused_at)) / 60);
      end if;
      v_hours := least(24, greatest(0, extract(epoch from (v_cap - v_e.clock_in)) / 3600 - v_paused / 60));
      update job_time_entries
        set clock_out = v_cap, on_site_end = coalesce(on_site_end, v_cap), hours = v_hours,
            paused_at = null, total_paused_minutes = round(v_paused::numeric, 2), updated_at = now()
      where id = v_e.id;
    else
      update job_time_entries
        set clock_out = v_cap, hours = 0,
            travel_minutes = coalesce(travel_minutes,
              least(1440, greatest(0, round(extract(epoch from (v_cap - v_e.travel_start)) / 60.0, 1)))),
            updated_at = now()
      where id = v_e.id;
    end if;

    if v_e.auto_continued = true and coalesce(v_e.auto_split_seq, 0) >= 1 then
      update job_time_entries
        set notes = coalesce(notes, '') || ' [abandoned: needs review]', updated_at = now()
      where id = v_e.id;
      select full_name into v_emp from employees where id = v_e.employee_id;
      perform create_notification(
        'time_entry.abandoned_clock', 'Abandoned clock needs review',
        coalesce(v_emp, 'A tech') || ' had an auto-continued clock that was never touched for a second day; it has been stopped. Please review their hours.',
        '/time-tracking', 'job_time_entry', v_e.id, v_e.job_id,
        jsonb_build_object('employee_id', v_e.employee_id, 'work_date', v_e.work_date, 'auto_split_seq', v_e.auto_split_seq)
      );
    else
      insert into job_time_entries (
        job_id, employee_id, appointment_id, work_date, hours, work_type,
        travel_start, clock_in, entered_by, description,
        auto_continued, continued_from, auto_split_seq, source
      ) values (
        v_e.job_id, v_e.employee_id, v_e.appointment_id, (v_e.work_date + 1), 0, coalesce(v_e.work_type, 'field'),
        (((v_e.work_date + 1)::text || ' 00:00:00')::timestamp at time zone 'America/Denver'),
        (((v_e.work_date + 1)::text || ' 00:00:00')::timestamp at time zone 'America/Denver'),
        v_e.employee_id, coalesce(v_e.description, 'Continued overnight'),
        true, v_e.id, coalesce(v_e.auto_split_seq, 0) + 1, 'auto_split'
      );
    end if;

    v_count := v_count + 1;
  end loop;

  insert into worker_runs (worker_name, status, records_processed, started_at, completed_at)
  values ('apply_midnight_clock_split', 'completed', v_count, v_started, now());
end;
$$;


--
-- Name: apply_schedule_plan(uuid, uuid, date, boolean, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_schedule_plan(p_job_id uuid, p_template_id uuid, p_start_date date, p_skip_weekends boolean DEFAULT true, p_phase_overrides jsonb DEFAULT '[]'::jsonb, p_duration_overrides jsonb DEFAULT '{}'::jsonb, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_schedule_id UUID;
  v_template_name TEXT;
  v_phases RECORD;
  v_task RECORD;
  v_dep RECORD;
  v_current_date DATE;
  v_end_date DATE;
  v_phase_dates JSONB := '{}'::JSONB;
  v_skipped UUID[] := '{}';
  v_tasks_created INT := 0;
  v_phases_created INT := 0;
  v_sort INT := 0;
  v_jsp_id UUID;
  v_duration INT;
  v_override_duration INT;
  v_current_phase TEXT;
BEGIN
  SELECT name INTO v_template_name FROM schedule_templates WHERE id = p_template_id;
  IF v_template_name IS NULL THEN
    RAISE EXCEPTION 'Template not found';
  END IF;

  -- Get current job phase
  SELECT phase INTO v_current_phase FROM jobs WHERE id = p_job_id;

  IF EXISTS (SELECT 1 FROM job_schedules WHERE job_id = p_job_id) THEN
    DELETE FROM job_tasks WHERE job_id = p_job_id AND template_task_id IS NOT NULL;
    DELETE FROM job_schedule_phases WHERE job_schedule_id IN (SELECT id FROM job_schedules WHERE job_id = p_job_id);
    DELETE FROM job_schedules WHERE job_id = p_job_id;
  END IF;

  FOR v_phases IN SELECT * FROM jsonb_array_elements(p_phase_overrides) LOOP
    IF (v_phases.value->>'skip')::BOOLEAN IS TRUE THEN
      v_skipped := v_skipped || (v_phases.value->>'phase_id')::UUID;
    END IF;
  END LOOP;

  INSERT INTO job_schedules (job_id, template_id, start_date, name, created_by)
  VALUES (p_job_id, p_template_id, p_start_date, v_template_name, p_created_by)
  RETURNING id INTO v_schedule_id;

  FOR v_phases IN
    SELECT tp.id, tp.name, tp.color, tp.duration_days, tp.is_milestone, tp.display_order
    FROM template_phases tp
    WHERE tp.template_id = p_template_id
      AND tp.id != ALL(v_skipped)
    ORDER BY tp.display_order
  LOOP
    v_duration := v_phases.duration_days;
    IF p_duration_overrides ? v_phases.id::TEXT THEN
      v_override_duration := (p_duration_overrides->>v_phases.id::TEXT)::INT;
      IF v_override_duration > 0 THEN
        v_duration := v_override_duration;
      END IF;
    END IF;

    v_current_date := p_start_date;

    FOR v_dep IN
      SELECT td.source_phase_id, td.dependency_type
      FROM template_dependencies td
      WHERE td.target_phase_id = v_phases.id
        AND td.source_phase_id != ALL(v_skipped)
    LOOP
      IF v_phase_dates ? v_dep.source_phase_id::TEXT THEN
        DECLARE
          dep_end DATE;
        BEGIN
          dep_end := (v_phase_dates->v_dep.source_phase_id::TEXT->>'end_date')::DATE;
          IF v_dep.dependency_type = 'starts_after' THEN
            dep_end := dep_end + 1;
            IF p_skip_weekends THEN
              WHILE EXTRACT(DOW FROM dep_end) IN (0, 6) LOOP
                dep_end := dep_end + 1;
              END LOOP;
            END IF;
          END IF;
          IF dep_end > v_current_date THEN
            v_current_date := dep_end;
          END IF;
        END;
      END IF;
    END LOOP;

    IF p_skip_weekends THEN
      WHILE EXTRACT(DOW FROM v_current_date) IN (0, 6) LOOP
        v_current_date := v_current_date + 1;
      END LOOP;
    END IF;

    v_end_date := v_current_date;
    IF NOT v_phases.is_milestone AND v_duration > 1 THEN
      DECLARE
        days_remaining INT := v_duration - 1;
      BEGIN
        WHILE days_remaining > 0 LOOP
          v_end_date := v_end_date + 1;
          IF p_skip_weekends AND EXTRACT(DOW FROM v_end_date) IN (0, 6) THEN
            CONTINUE;
          END IF;
          days_remaining := days_remaining - 1;
        END LOOP;
      END;
    END IF;

    v_phase_dates := v_phase_dates || jsonb_build_object(
      v_phases.id::TEXT,
      jsonb_build_object('start_date', v_current_date::TEXT, 'end_date', v_end_date::TEXT)
    );

    v_sort := v_sort + 1;
    INSERT INTO job_schedule_phases (
      job_schedule_id, phase_name, phase_color, target_start, target_end,
      duration_days, sort_order, template_phase_id
    ) VALUES (
      v_schedule_id, v_phases.name, v_phases.color, v_current_date, v_end_date,
      v_duration, v_sort, v_phases.id
    ) RETURNING id INTO v_jsp_id;
    v_phases_created := v_phases_created + 1;

    FOR v_task IN
      SELECT tt.id, tt.title, tt.is_required, tt.display_order
      FROM template_tasks tt
      WHERE tt.template_phase_id = v_phases.id
      ORDER BY tt.display_order
    LOOP
      INSERT INTO job_tasks (
        job_id, job_schedule_id, phase_name, phase_color, template_task_id, template_phase_id,
        title, is_required, target_date, job_schedule_phase_id
      ) VALUES (
        p_job_id, v_schedule_id, v_phases.name, v_phases.color, v_task.id, v_phases.id,
        v_task.title, v_task.is_required, v_current_date, v_jsp_id
      );
      v_tasks_created := v_tasks_created + 1;
    END LOOP;
  END LOOP;

  -- Auto-advance job phase to reconstruction_in_progress if currently pre-production
  IF v_current_phase IN ('lead', 'job_received', 'estimate_submitted', 'estimate_approved', 'work_authorized') THEN
    UPDATE jobs SET
      phase = 'reconstruction_in_progress',
      phase_entered_at = now(),
      updated_at = now()
    WHERE id = p_job_id;

    -- Log the phase change
    INSERT INTO job_phase_history (job_id, from_phase, to_phase, changed_by, changed_at)
    VALUES (p_job_id, v_current_phase, 'reconstruction_in_progress', p_created_by, now());
  END IF;

  RETURN jsonb_build_object(
    'schedule_id', v_schedule_id,
    'phases_created', v_phases_created,
    'tasks_created', v_tasks_created,
    'start_date', p_start_date,
    'end_date', (SELECT MAX(target_end) FROM job_schedule_phases WHERE job_schedule_id = v_schedule_id),
    'phase_advanced', v_current_phase IN ('lead', 'job_received', 'estimate_submitted', 'estimate_approved', 'work_authorized')
  );
END;
$$;


--
-- Name: approve_time_entries(uuid[], uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_time_entries(p_entry_ids uuid[], p_approved_by uuid, p_approved boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE job_time_entries
  SET approved = p_approved,
      approved_by = CASE WHEN p_approved THEN p_approved_by ELSE NULL END,
      updated_at = now()
  WHERE id = ANY(p_entry_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: assign_tasks_to_appointment(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_tasks_to_appointment(p_appointment_id uuid, p_task_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
BEGIN
  -- Unassign any tasks currently on this appointment that aren't in the new list
  UPDATE job_tasks
  SET appointment_id = NULL
  WHERE appointment_id = p_appointment_id
    AND NOT (id = ANY(p_task_ids))
    AND is_completed = false;

  -- Assign the selected tasks
  UPDATE job_tasks
  SET appointment_id = p_appointment_id
  WHERE id = ANY(p_task_ids);

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'appointment_id', p_appointment_id,
    'tasks_assigned', v_count
  );
END;
$$;


--
-- Name: attest_prior_sms_consent(uuid, uuid, text, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attest_prior_sms_consent(p_contact_id uuid, p_actor_id uuid, p_consent_method text, p_consent_obtained_on date, p_evidence_note text, p_request_ip text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor public.employees%ROWTYPE;
  v_contact public.contacts%ROWTYPE;
  v_existing public.service_sms_consents%ROWTYPE;
  v_method text := lower(btrim(COALESCE(p_consent_method, '')));
  v_note text := btrim(COALESCE(p_evidence_note, ''));
  v_request_ip text := NULLIF(btrim(COALESCE(p_request_ip, '')), '');
  v_phone_digits text;
  v_phone_key text;
  v_locked_phone_digits text;
  v_locked_phone_key text;
  v_recorded_at timestamptz := now();
  v_already_recorded boolean := false;
  v_attestation_id uuid;
BEGIN
  IF current_user <> 'service_role' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'CONSENT_ATTESTATION_NOT_AUTHORIZED'
    );
  END IF;

  IF p_contact_id IS NULL OR p_actor_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ATTESTATION');
  END IF;

  IF v_method <> ALL (ARRAY[
    'verbal_permission',
    'signed_work_authorization',
    'other_written_permission',
    'customer_requested_texts',
    'other_verified_permission'
  ]) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CONSENT_METHOD');
  END IF;

  IF char_length(v_note) < 10 OR char_length(v_note) > 500 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_EVIDENCE_NOTE');
  END IF;

  IF p_consent_obtained_on IS NULL
     OR p_consent_obtained_on > (v_recorded_at AT TIME ZONE 'America/Denver')::date THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CONSENT_DATE');
  END IF;

  IF v_request_ip IS NOT NULL
     AND (
       char_length(v_request_ip) < 3
       OR char_length(v_request_ip) > 64
       OR v_request_ip !~ '^[0-9A-Fa-f:.]+$'
     ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST_IP');
  END IF;

  SELECT *
  INTO v_actor
  FROM public.employees
  WHERE id = p_actor_id
  LIMIT 1
  FOR SHARE;

  IF v_actor.id IS NULL
     OR v_actor.is_active IS DISTINCT FROM true
     OR v_actor.is_external IS DISTINCT FROM false
     OR v_actor.role::text NOT IN ('admin', 'office') THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'CONSENT_ATTESTATION_NOT_AUTHORIZED'
    );
  END IF;

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id;

  IF v_contact.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_NOT_FOUND');
  END IF;

  v_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_phone_digits) = 10 THEN
    v_phone_key := v_phone_digits;
  ELSIF length(v_phone_digits) = 11 AND left(v_phone_digits, 1) = '1' THEN
    v_phone_key := right(v_phone_digits, 10);
  ELSE
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_HAS_NO_PHONE');
  END IF;

  -- Serialize with the CallRail inbound projector, then lock every duplicate
  -- contact using this normalized number before checking suppression.
  PERFORM pg_advisory_xact_lock(hashtextextended('messaging-phone:' || v_phone_key, 0));

  PERFORM c.id
  FROM public.contacts c
  WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
  ORDER BY c.id
  FOR UPDATE;

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id
  FOR UPDATE;

  v_locked_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_locked_phone_digits) = 10 THEN
    v_locked_phone_key := v_locked_phone_digits;
  ELSIF length(v_locked_phone_digits) = 11 AND left(v_locked_phone_digits, 1) = '1' THEN
    v_locked_phone_key := right(v_locked_phone_digits, 10);
  END IF;

  IF v_contact.id IS NULL
     OR v_locked_phone_key IS NULL
     OR v_locked_phone_key <> v_phone_key THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_PHONE_CHANGED');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.dnd IS TRUE
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_DND_ACTIVE');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.opt_out_at IS NOT NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_OPTED_OUT');
  END IF;

  -- The provider-event insert commits before the CallRail projection RPC. If a
  -- STOP is durable but not yet projected onto contacts, refuse attestation.
  IF EXISTS (
    SELECT 1
    FROM public.message_provider_events e
    WHERE e.direction = 'inbound'
      AND e.message_type IN ('sms', 'mms')
      AND e.processing_state IN ('received', 'claimed', 'retryable', 'failed')
      AND right(regexp_replace(COALESCE(e.sender_address, ''), '[^0-9]', '', 'g'), 10)
        = v_phone_key
      AND regexp_replace(lower(trim(COALESCE(e.content, ''))), '[^a-z0-9]', '', 'g')
        = ANY (ARRAY['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'])
      AND NOT EXISTS (
        SELECT 1
        FROM public.message_provider_events later_event
        WHERE later_event.direction = 'inbound'
          AND later_event.message_type IN ('sms', 'mms')
          AND later_event.processing_state = 'processed'
          AND right(
            regexp_replace(COALESCE(later_event.sender_address, ''), '[^0-9]', '', 'g'),
            10
          ) = v_phone_key
          AND later_event.occurred_at > e.occurred_at
          AND regexp_replace(
            lower(trim(COALESCE(later_event.content, ''))),
            '[^a-z0-9]',
            '',
            'g'
          ) = ANY (ARRAY['start', 'unstop', 'subscribe', 'yes'])
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_PENDING_STOP');
  END IF;

  SELECT *
  INTO v_existing
  FROM public.service_sms_consents
  WHERE contact_id = v_contact.id
  FOR UPDATE;
  v_already_recorded := v_existing.contact_id IS NOT NULL;

  -- Raw evidence is append-only and browser-inaccessible. The legacy
  -- sms_consent_log receives only a redacted reference to this row.
  INSERT INTO public.service_sms_consent_attestations (
    contact_id,
    phone,
    consent_scope,
    consent_method,
    consent_obtained_on,
    evidence_note,
    attestation_version,
    sender_identity,
    recorded_by,
    request_ip,
    recorded_at
  )
  VALUES (
    v_contact.id,
    v_contact.phone,
    'service_related_customer_project_messages',
    v_method,
    p_consent_obtained_on,
    v_note,
    'prior_sms_consent_v1',
    'Utah Pros Restoration',
    v_actor.id,
    v_request_ip,
    v_recorded_at
  )
  RETURNING id INTO v_attestation_id;

  INSERT INTO public.service_sms_consents (
    contact_id,
    phone,
    consent_scope,
    consent_method,
    consent_obtained_on,
    evidence_note,
    attestation_version,
    sender_identity,
    recorded_by,
    request_ip,
    attested_at,
    updated_at
  )
  VALUES (
    v_contact.id,
    v_contact.phone,
    'service_related_customer_project_messages',
    v_method,
    p_consent_obtained_on,
    v_note,
    'prior_sms_consent_v1',
    'Utah Pros Restoration',
    v_actor.id,
    v_request_ip,
    v_recorded_at,
    v_recorded_at
  )
  ON CONFLICT (contact_id) DO UPDATE
  SET
    phone = EXCLUDED.phone,
    consent_scope = EXCLUDED.consent_scope,
    consent_method = EXCLUDED.consent_method,
    consent_obtained_on = EXCLUDED.consent_obtained_on,
    evidence_note = EXCLUDED.evidence_note,
    attestation_version = EXCLUDED.attestation_version,
    sender_identity = EXCLUDED.sender_identity,
    recorded_by = EXCLUDED.recorded_by,
    request_ip = EXCLUDED.request_ip,
    attested_at = EXCLUDED.attested_at,
    updated_at = EXCLUDED.updated_at;

  -- Every successful submission appends evidence, including a re-attestation.
  INSERT INTO public.sms_consent_log (
    contact_id,
    phone,
    event_type,
    source,
    details,
    ip_address,
    performed_by,
    created_at
  )
  VALUES (
    v_contact.id,
    v_contact.phone,
    'prior_consent_attested',
    v_method,
    jsonb_build_object(
      'attestation', 'verified_prior_sms_consent',
      'attestation_id', v_attestation_id,
      'attestation_version', 'prior_sms_consent_v1',
      'consent_scope', 'service_related_customer_project_messages',
      'sender_identity', 'Utah Pros Restoration',
      'recorded_at', v_recorded_at
    )::text,
    NULL,
    v_actor.id,
    v_recorded_at
  );

  RETURN jsonb_build_object(
    'ok', true,
    'already_recorded', v_already_recorded,
    'contact_id', v_contact.id,
    'service_sms_consent', true,
    'consent_scope', 'service_related_customer_project_messages',
    'consent_method', v_method,
    'consent_obtained_on', p_consent_obtained_on,
    'recorded_by', v_actor.id,
    'attested_at', v_recorded_at
  );
END;
$_$;


--
-- Name: bust_postgrest_cache(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bust_postgrest_cache() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  NOTIFY pgrst, 'reload schema';
$$;


--
-- Name: calc_time_entry_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_time_entry_cost() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_rate numeric;
begin
  if NEW.hourly_rate is null or NEW.hourly_rate = 0 then
    select hourly_rate into v_rate from employees where id = NEW.employee_id;
    if v_rate is not null then NEW.hourly_rate := v_rate; end if;
  end if;
  NEW.updated_at := now();
  return NEW;
end; $$;


--
-- Name: can_current_employee_access_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_current_employee_access_settings() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_role text;
  v_override boolean;
BEGIN
  SELECT employee.id, employee.role::text
    INTO v_actor_id, v_actor_role
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active
    AND NOT employee.is_external
    AND employee.role::text IN (
      'admin',
      'office',
      'project_manager',
      'field_tech',
      'estimator',
      'supervisor'
    );

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.feature_flags flag
    WHERE flag.key = 'page:settings'
      AND flag.force_disabled
  ) THEN
    RETURN false;
  END IF;

  SELECT access.can_view
    INTO v_override
  FROM public.employee_page_access access
  WHERE access.employee_id = v_actor_id
    AND access.nav_key = 'settings';

  IF FOUND THEN
    RETURN v_override;
  END IF;

  IF v_actor_role = 'admin' THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.nav_permissions permission
    WHERE permission.role::text = v_actor_role
      AND permission.nav_key = 'settings'
      AND permission.can_view
  );
END;
$$;


--
-- Name: capture_claim_status_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_claim_status_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  BEGIN
    INSERT INTO public.claim_status_history (claim_id, from_status, to_status)
    VALUES (NEW.id, OLD.status, NEW.status);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'capture_claim_status_history failed for claim %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$$;


