END;
$$;


--
-- Name: message_provider_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.message_provider_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    event_type text NOT NULL,
    provider_event_id text,
    provider_message_id text,
    provider_conversation_id text,
    direction text,
    message_type text,
    provider_status text,
    sender_address text,
    recipient_address text,
    content text,
    company_resource_id text,
    person_resource_id text,
    agent_name text,
    media_count integer DEFAULT 0 NOT NULL,
    owned_media jsonb DEFAULT '[]'::jsonb NOT NULL,
    raw_body_hash text NOT NULL,
    dedupe_key text NOT NULL,
    occurred_at timestamp with time zone,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    processing_state text DEFAULT 'received'::text NOT NULL,
    processing_attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    claimed_at timestamp with time zone,
    processed_at timestamp with time zone,
    message_id uuid,
    contact_id uuid,
    conversation_id uuid,
    send_attempt_id uuid,
    outcome text,
    error_code text,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    CONSTRAINT message_provider_events_direction_check CHECK (((direction IS NULL) OR (direction = ANY (ARRAY['inbound'::text, 'outbound'::text])))),
    CONSTRAINT message_provider_events_media_count_check CHECK ((media_count >= 0)),
    CONSTRAINT message_provider_events_message_type_check CHECK (((message_type IS NULL) OR (message_type = ANY (ARRAY['sms'::text, 'mms'::text, 'rcs'::text])))),
    CONSTRAINT message_provider_events_owned_media_check CHECK ((jsonb_typeof(owned_media) = 'array'::text)),
    CONSTRAINT message_provider_events_processing_attempts_check CHECK ((processing_attempts >= 0)),
    CONSTRAINT message_provider_events_provider_check CHECK ((provider = ANY (ARRAY['twilio'::text, 'callrail'::text]))),
    CONSTRAINT message_provider_events_state_check CHECK ((processing_state = ANY (ARRAY['received'::text, 'claimed'::text, 'processed'::text, 'retryable'::text, 'failed'::text])))
);


--
-- Name: TABLE message_provider_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.message_provider_events IS 'Service-only deduplicated provider-event inbox. Stores normalized text facts needed for recovery, not raw provider payloads or short-lived media URLs.';


--
-- Name: COLUMN message_provider_events.provider_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_provider_events.provider_status IS 'Provider-native status observed on this event. Domain state is derived only after provider-specific validation.';


--
-- Name: COLUMN message_provider_events.resolved_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_provider_events.resolved_at IS 'Set when a human or Worker has acknowledged a terminal failure. The ops-health check ignores resolved rows, which is what stops a permanent failure alerting every Denver day forever. NULL means still outstanding.';


--
-- Name: claim_callrail_provider_event(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_callrail_provider_event(p_event_id uuid, p_now timestamp with time zone, p_stale_before timestamp with time zone) RETURNS SETOF public.message_provider_events
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'claim_callrail_provider_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  UPDATE public.message_provider_events AS event
  SET
    processing_state = 'claimed',
    processing_attempts = event.processing_attempts + 1,
    claimed_at = p_now,
    updated_at = p_now
  WHERE event.id = p_event_id
    AND event.provider = 'callrail'
    AND event.message_type IN ('sms', 'mms')
    AND (
      event.processing_state = 'received'
      OR (
        event.processing_state = 'retryable'
        AND event.next_attempt_at <= p_now
      )
      OR (
        event.processing_state = 'claimed'
        AND event.claimed_at < p_stale_before
      )
    )
  RETURNING event.*;
END;
$$;


--
-- Name: FUNCTION claim_callrail_provider_event(p_event_id uuid, p_now timestamp with time zone, p_stale_before timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_callrail_provider_event(p_event_id uuid, p_now timestamp with time zone, p_stale_before timestamp with time zone) IS 'Service-only atomic claim fence for one due CallRail provider event.';


--
-- Name: claim_fixed_automation(text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_fixed_automation(p_automation_key text, p_entity_type text, p_entity_id uuid, p_now timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_claimed boolean := false;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'claim_fixed_automation is service-role only'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.fixed_automation_claims AS c (
    automation_key, entity_type, entity_id, claimed_at
  )
  VALUES (p_automation_key, p_entity_type, p_entity_id, p_now)
  ON CONFLICT ON CONSTRAINT fixed_automation_claims_unique_entity DO NOTHING;

  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  RETURN v_claimed;
END;
$$;


--
-- Name: FUNCTION claim_fixed_automation(p_automation_key text, p_entity_type text, p_entity_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_fixed_automation(p_automation_key text, p_entity_type text, p_entity_id uuid, p_now timestamp with time zone) IS 'Service-only atomic claim taken BEFORE a fixed automation sends. True means this caller may send.';


--
-- Name: claim_inbound_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_inbound_email(p_message_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_rows int;
BEGIN
  IF p_message_key IS NULL OR btrim(p_message_key) = '' THEN
    RETURN false;
  END IF;
  INSERT INTO public.email_inbound_events (message_key)
  VALUES (btrim(p_message_key))
  ON CONFLICT (message_key) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows > 0;
END;
$$;


--
-- Name: claim_message_notification_outbox(integer, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_message_notification_outbox(p_limit integer, p_now timestamp with time zone, p_stale_before timestamp with time zone, p_claim_token uuid) RETURNS TABLE(id uuid, type_key text, payload jsonb, delivery_attempts integer, claim_token uuid)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'claim_message_notification_outbox is service-role only'
      USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100
     OR p_now IS NULL OR p_stale_before IS NULL OR p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Notification outbox claim arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH due AS (
    SELECT o.id
    FROM public.message_notification_outbox o
    WHERE (
        o.delivery_state = 'pending'
        OR (
          o.delivery_state = 'retryable'
          AND o.next_attempt_at <= p_now
        )
        OR (
          o.delivery_state = 'processing'
          AND o.claimed_at < p_stale_before
        )
      )
    ORDER BY COALESCE(o.next_attempt_at, o.created_at), o.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  )
  UPDATE public.message_notification_outbox o
  SET
    delivery_state = 'processing',
    delivery_attempts = o.delivery_attempts + 1,
    claimed_at = p_now,
    claim_token = p_claim_token,
    updated_at = p_now
  FROM due
  WHERE o.id = due.id
  RETURNING o.id, o.type_key, o.payload, o.delivery_attempts, o.claim_token;
END;
$$;


--
-- Name: FUNCTION claim_message_notification_outbox(p_limit integer, p_now timestamp with time zone, p_stale_before timestamp with time zone, p_claim_token uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_message_notification_outbox(p_limit integer, p_now timestamp with time zone, p_stale_before timestamp with time zone, p_claim_token uuid) IS 'Service-role-only fenced lease claim for due or stale inbound-message notification jobs.';


--
-- Name: claim_message_recipient_attempt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_message_recipient_attempt(p_attempt_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'claim_message_recipient_attempt is service-role only'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.message_send_attempts
  SET
    state = 'submitting',
    started_at = now(),
    updated_at = now()
  WHERE id = p_attempt_id
    AND parent_attempt_id IS NOT NULL
    AND state = 'prepared'
    AND message_id IS NULL
    AND provider_message_id IS NULL;

  RETURN FOUND;
END;
$$;


--
-- Name: FUNCTION claim_message_recipient_attempt(p_attempt_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_message_recipient_attempt(p_attempt_id uuid) IS 'Service-role-only atomic prepared-to-submitting claim; only the winning worker may perform the recipient provider side effect.';


--
-- Name: claim_native_push_delivery(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_native_push_delivery(p_delivery_key uuid, p_employee_id uuid, p_device_token_id uuid, p_device_fingerprint uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_claimed boolean;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required'
      USING errcode = '42501';
  END IF;

  -- The claim prevents duplicate retries, but it is not permanent business
  -- history. Retain a 90-day replay window and remove at most 1,000 expired
  -- rows per delivery so an active device cannot grow this table forever.
  WITH expired_claims AS (
    SELECT existing_claim.delivery_key
    FROM public.native_push_delivery_claims existing_claim
    WHERE existing_claim.claimed_at < now() - interval '90 days'
    ORDER BY existing_claim.claimed_at
    LIMIT 1000
  )
  DELETE FROM public.native_push_delivery_claims existing_claim
  USING expired_claims
  WHERE existing_claim.delivery_key = expired_claims.delivery_key;

  INSERT INTO public.native_push_delivery_claims (
    delivery_key,
    employee_id,
    device_fingerprint
  )
  SELECT
    p_delivery_key,
    p_employee_id,
    p_device_fingerprint
  WHERE EXISTS (
    SELECT 1
    FROM public.device_tokens token_row
    WHERE token_row.id = p_device_token_id
      AND token_row.employee_id = p_employee_id
  )
  ON CONFLICT (delivery_key) DO NOTHING
  RETURNING true INTO v_claimed;

  RETURN COALESCE(v_claimed, false);
END;
$$;


