              jsonb_build_object('error', SQLERRM, 'contact_id', NEW.contact_id, 'target_stage', 'Won'));
    END;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: dash_division_bucket(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_division_bucket(p_division text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_division = 'reconstruction' THEN 'reconstruction'
    WHEN p_division = 'mold' THEN 'mold'
    WHEN p_division = 'remodeling' THEN 'remodeling'
    WHEN p_division = 'contents' THEN 'contents'
    ELSE 'mitigation'
  END;
$$;


--
-- Name: delete_appointment(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_appointment(p_appointment_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_date date;
  v_time_start time;
  v_time_end time;
  v_status text;
BEGIN
  SELECT date, time_start, time_end, status::text
    INTO v_date, v_time_start, v_time_end, v_status
  FROM appointments
  WHERE id = p_appointment_id;

  IF FOUND THEN
    INSERT INTO appointment_status_history (
      appointment_id, event_type,
      old_date, old_time_start, old_time_end, old_status,
      actor_id, reason
    ) VALUES (
      p_appointment_id, 'deleted',
      v_date, v_time_start, v_time_end, v_status,
      p_actor_id, p_reason
    );
  END IF;

  UPDATE job_tasks SET appointment_id = NULL WHERE appointment_id = p_appointment_id;
  DELETE FROM appointment_crew WHERE appointment_id = p_appointment_id;
  DELETE FROM appointments WHERE id = p_appointment_id;
END;
$$;


--
-- Name: delete_contact_address(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_contact_address(p_address_id uuid, p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  was_billing boolean;
BEGIN
  SELECT is_billing INTO was_billing FROM contact_addresses WHERE id = p_address_id AND contact_id = p_contact_id;
  DELETE FROM contact_addresses WHERE id = p_address_id AND contact_id = p_contact_id;

  -- If we deleted the billing address, clear it from contacts table
  IF was_billing THEN
    UPDATE contacts SET billing_address = NULL, billing_city = NULL, billing_state = NULL, billing_zip = NULL, updated_at = now()
    WHERE id = p_contact_id;
    -- Auto-promote another address to billing if one exists
    UPDATE contact_addresses SET is_billing = true
    WHERE contact_id = p_contact_id AND id = (
      SELECT id FROM contact_addresses WHERE contact_id = p_contact_id ORDER BY created_at ASC LIMIT 1
    );
  END IF;

  RETURN jsonb_build_object('success', true);
END; $$;


