--
-- Name: delete_email_campaign(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_email_campaign(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_name   text;
BEGIN
  SELECT status, name INTO v_status, v_name FROM email_campaigns WHERE id = p_id;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF v_status NOT IN ('draft', 'failed') THEN
    RAISE EXCEPTION 'Cannot delete a campaign that is % — only draft/failed campaigns can be deleted', v_status;
  END IF;
  DELETE FROM email_campaigns WHERE id = p_id;
  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_email_campaign_deleted', 'email_campaign', p_id,
    jsonb_build_object('campaign_id', p_id, 'name', v_name, 'status', v_status));
END;
$$;


--
-- Name: delete_employee_notification_override(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_employee_notification_override(p_employee_id uuid, p_type_key text, p_channel text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  DELETE FROM public.notification_employee_overrides
   WHERE employee_id = p_employee_id
     AND type_key    = p_type_key
     AND channel     = p_channel;
END;
$$;


