--
-- Name: delete_reading(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_reading(p_reading_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_taken_at TIMESTAMPTZ;
BEGIN
  SELECT taken_at INTO v_taken_at FROM moisture_readings WHERE id = p_reading_id;
  IF v_taken_at IS NULL THEN
    RAISE EXCEPTION 'delete_reading: reading % not found', p_reading_id;
  END IF;
  IF v_taken_at <= now() - interval '10 minutes' THEN
    RAISE EXCEPTION 'delete_reading: delete window closed';
  END IF;
  DELETE FROM moisture_readings WHERE id = p_reading_id;
END;
$$;


