--
-- Name: delete_time_entry(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_time_entry(p_id uuid, p_reason text, p_actor_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_e job_time_entries%ROWTYPE;
begin
  if not is_time_admin(p_actor_id) then raise exception 'NOT_AUTHORIZED' using errcode='P0001'; end if;
  select * into v_e from job_time_entries where id=p_id;
  if v_e.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
  if v_e.approved then raise exception 'ENTRY_APPROVED_CANNOT_DELETE' using errcode='P0001'; end if;
  insert into time_entry_deletions (entry_id, snapshot, reason, deleted_by) values (v_e.id, to_jsonb(v_e), p_reason, p_actor_id);
  insert into system_events (event_type, entity_type, entity_id, actor_id, job_id, payload) values ('time_entry.deleted','job_time_entry', v_e.id, p_actor_id, v_e.job_id, jsonb_build_object('reason', p_reason, 'snapshot', to_jsonb(v_e)));
  delete from job_time_entries where id=p_id;
end; $$;


