--
-- Name: TABLE email_suppressions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.email_suppressions IS 'Service-role only. Every writer is a Worker (resend-webhook, email-unsubscribe, conversation-email, email-consent). This is the opt-out list: anonymous DELETE was a CAN-SPAM exposure.';


--
-- Name: email_unsubscribe(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_unsubscribe(p_email text DEFAULT NULL::text, p_recipient_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS public.email_suppressions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email       text;
  v_campaign_id uuid;
  v_org_id      uuid;
  v_row         email_suppressions;
BEGIN
  v_email := p_email;

  IF p_recipient_id IS NOT NULL THEN
    SELECT email, campaign_id INTO v_email, v_campaign_id
    FROM email_campaign_recipients WHERE id = p_recipient_id;

    IF v_campaign_id IS NOT NULL THEN
      UPDATE email_campaign_recipients SET status = 'suppressed' WHERE id = p_recipient_id AND status != 'sent';
    END IF;
  END IF;

  IF v_email IS NULL OR btrim(v_email) = '' THEN
    RAISE EXCEPTION 'No email address to unsubscribe';
  END IF;

  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  INSERT INTO email_suppressions (org_id, email, reason, source)
  VALUES (v_org_id, btrim(v_email), 'unsubscribed', 'email_unsubscribe_link')
  ON CONFLICT (lower(email)) DO UPDATE SET suppressed_at = now()
  RETURNING * INTO v_row;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_email_unsubscribed', 'email_suppression', v_row.id, jsonb_build_object('email', v_row.email, 'campaign_id', v_campaign_id));

  RETURN v_row;
END;
$$;


--
-- Name: enforce_private_appointment_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_private_appointment_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_role TEXT;
BEGIN
  IF NEW.is_private AND (
       TG_OP = 'INSERT'
    OR COALESCE(OLD.is_private, false) IS DISTINCT FROM NEW.is_private
  ) THEN
    SELECT role INTO v_role
    FROM employees
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_role IS NULL OR v_role NOT IN ('admin', 'project_manager') THEN
      RAISE EXCEPTION 'Only admins or project managers can mark appointments or events as private';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


