CREATE FUNCTION public.enqueue_automation_run(p_automation_id uuid, p_org_id uuid, p_triggering_event_id uuid, p_contact_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_next_run_at timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO crm_automation_runs
    (automation_id, org_id, triggering_event_id, contact_id, entity_type, entity_id, status, current_action, next_run_at)
  VALUES
    (p_automation_id, p_org_id, p_triggering_event_id, p_contact_id, p_entity_type, p_entity_id, 'active', 0, COALESCE(p_next_run_at, now()))
  ON CONFLICT (automation_id, triggering_event_id) DO NOTHING
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


