    org_id uuid NOT NULL,
    platform text NOT NULL,
    campaign_id text NOT NULL,
    campaign_name text,
    date date NOT NULL,
    spend numeric DEFAULT 0 NOT NULL,
    impressions integer,
    clicks integer,
    platform_conversions numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
