);


--
-- Name: get_ad_spend(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ad_spend(p_platform text DEFAULT NULL::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS SETOF public.ad_spend
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM ad_spend
  WHERE (p_platform IS NULL OR platform = p_platform)
    AND (p_start_date IS NULL OR date >= p_start_date)
    AND (p_end_date IS NULL OR date <= p_end_date)
  ORDER BY date DESC, platform, campaign_name;
$$;


--
-- Name: get_all_employees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_employees() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT COALESCE(
       auth.jwt() ->> 'role' = 'service_role',
       false
     )
     AND NOT EXISTS (
       SELECT 1
       FROM public.employees actor
       WHERE actor.auth_user_id = auth.uid()
         AND actor.is_active
         AND NOT actor.is_external
         AND actor.role::text = 'admin'
     ) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: employee administration requires admin'
      USING errcode = '42501';
  END IF;

  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'id', employee.id,
               'auth_user_id', employee.auth_user_id,
               'full_name', employee.full_name,
               'display_name', employee.display_name,
               'email', employee.email,
               'phone', employee.phone,
               'role', employee.role,
               'hourly_rate', employee.hourly_rate,
               'overtime_rate', employee.overtime_rate,
               'is_active', employee.is_active,
               'color', employee.color,
               'created_at', employee.created_at,
               'updated_at', employee.updated_at
             )
             ORDER BY employee.full_name
           ),
           '[]'::jsonb
         )
    INTO v_result
  FROM public.employees employee;

  RETURN v_result;
END;
$$;


