$$;


--
-- Name: get_appointment_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_appointment_detail(p_appointment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  v_caller_emp_id UUID;
  v_caller_role TEXT;
BEGIN
  SELECT id, role INTO v_caller_emp_id, v_caller_role
  FROM employees WHERE auth_user_id = auth.uid() LIMIT 1;

  SELECT jsonb_build_object(
    'id', a.id,
    'job_id', a.job_id,
    'kind', a.kind,
    'title', a.title,
    'date', a.date,
    'time_start', a.time_start,
    'time_end', a.time_end,
    'type', a.type,
    'status', a.status,
    'notes', a.notes,
    'is_private', a.is_private,
    'created_by', a.created_by,
    'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
      'id', j.id,
      'job_number', j.job_number,
      'insured_name', j.insured_name,
      'address', j.address,
      'city', j.city,
      'division', j.division,
      'phase', j.phase,
      'client_phone', j.client_phone,
      'claim_id', j.claim_id,
      'encircle_claim_id', j.encircle_claim_id
    ) ELSE NULL END,
    'appointment_crew', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', ac.id,
        'employee_id', ac.employee_id,
        'role', ac.role,
        'employees', jsonb_build_object(
          'id', e.id,
          'display_name', e.display_name,
          'full_name', e.full_name,
          'role', e.role
        )
      ))
      FROM appointment_crew ac
      JOIN employees e ON e.id = ac.employee_id
      WHERE ac.appointment_id = a.id
    ), '[]'::jsonb)
  )
  INTO result
  FROM appointments a
  LEFT JOIN jobs j ON j.id = a.job_id
  WHERE a.id = p_appointment_id
    AND (
      NOT a.is_private
      OR v_caller_role IN ('admin', 'project_manager')
      OR EXISTS (
        SELECT 1 FROM appointment_crew ac
        WHERE ac.appointment_id = a.id AND ac.employee_id = v_caller_emp_id
      )
    );

  RETURN result;
END;
$$;


--
-- Name: get_appointment_tasks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_appointment_tasks(p_appointment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', jt.id, 'title', jt.title, 'description', jt.description,
    'is_required', jt.is_required, 'is_completed', jt.is_completed,
    'completed_by', jt.completed_by, 'completed_at', jt.completed_at,
    'display_order', jt.display_order, 'template_task_id', jt.template_task_id,
    'completed_by_name', e.display_name
  ) ORDER BY jt.display_order), '[]'::jsonb) INTO result
  FROM job_tasks jt
  LEFT JOIN employees e ON e.id = jt.completed_by
  WHERE jt.appointment_id = p_appointment_id;
  RETURN result;
END; $$;


--
-- Name: get_appointments_range(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_appointments_range(p_start_date date, p_end_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  v_caller_emp_id UUID;
  v_caller_role TEXT;
BEGIN
  SELECT id, role INTO v_caller_emp_id, v_caller_role
  FROM employees WHERE auth_user_id = auth.uid() LIMIT 1;

  SELECT jsonb_agg(row_data ORDER BY (row_data->>'date'), (row_data->>'time_start'))
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', a.id, 'job_id', a.job_id, 'title', a.title, 'date', a.date,
      'time_start', a.time_start, 'time_end', a.time_end, 'type', a.type,
      'status', a.status, 'notes', a.notes, 'is_private', a.is_private, 'created_by', a.created_by,
      'color', a.color, 'kind', a.kind, 'duration_days', a.duration_days, 'is_milestone', a.is_milestone,
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true),
      'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
        'id', j.id, 'job_number', j.job_number, 'insured_name', j.insured_name, 'address', j.address,
        'city', j.city, 'division', j.division, 'phase', j.phase, 'client_phone', j.client_phone
      ) ELSE NULL END,
      'appointment_crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', ac.id, 'employee_id', ac.employee_id, 'role', ac.role,
          'employees', jsonb_build_object(
            'id', e.id, 'display_name', e.display_name, 'full_name', e.full_name,
            'role', e.role, 'color', e.color, 'avatar_url', e.avatar_url
          )
        ))
        FROM appointment_crew ac JOIN employees e ON e.id = ac.employee_id
        WHERE ac.appointment_id = a.id
      ), '[]'::jsonb)
    ) as row_data
    FROM appointments a
    LEFT JOIN jobs j ON j.id = a.job_id
    WHERE a.date BETWEEN p_start_date AND p_end_date
      AND (
        NOT a.is_private
        OR v_caller_role IN ('admin', 'project_manager')
        OR EXISTS (SELECT 1 FROM appointment_crew ac WHERE ac.appointment_id = a.id AND ac.employee_id = v_caller_emp_id)
      )
  ) sub;
  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: get_ar_invoices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ar_invoices() RETURNS TABLE(invoice_id uuid, invoice_number text, qbo_doc_number text, status text, total numeric, amount_paid numeric, balance numeric, sent_at timestamp with time zone, due_date date, invoice_date date, qbo_invoice_id text, qbo_sync_error text, job_id uuid, job_number text, division text, claim_id uuid, claim_number text, contact_id uuid, client_name text, job_address text, job_city text, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    i.id, i.invoice_number, i.qbo_doc_number, i.status,
    COALESCE(i.adjusted_total, i.total, 0)                              AS total,
    COALESCE(i.amount_paid, 0)                                          AS amount_paid,
    COALESCE(i.adjusted_total, i.total, 0) - COALESCE(i.amount_paid, 0) AS balance,
    i.sent_at, i.due_date, i.invoice_date,
    i.qbo_invoice_id, i.qbo_sync_error,
    i.job_id, j.job_number, j.division,
    j.claim_id, cl.claim_number,
    i.contact_id, ct.name AS client_name,
    j.address AS job_address, j.city AS job_city,
    i.created_at
  FROM invoices i
  LEFT JOIN jobs     j  ON j.id  = i.job_id
  LEFT JOIN claims   cl ON cl.id = j.claim_id
  LEFT JOIN contacts ct ON ct.id = i.contact_id
  ORDER BY (COALESCE(i.adjusted_total, i.total, 0) - COALESCE(i.amount_paid, 0)) DESC,
           i.due_date NULLS LAST;
$$;


--
-- Name: get_ar_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ar_jobs() RETURNS TABLE(id uuid, job_number text, division text, phase text, created_at timestamp with time zone, updated_at timestamp with time zone, invoiced_value numeric, collected_value numeric, ar_status text, ar_notes text, invoiced_date date, last_followup_date date, deductible numeric, deductible_collected boolean, deductible_collected_date date, depreciation_held numeric, depreciation_released numeric, claim_id uuid, claim_number text, insurance_company text, policy_number text, date_of_loss date, insured_name text, client_phone text, client_email text, adjuster_name text, adjuster_phone text, adjuster_email text, phase_entered_at timestamp with time zone, received_date timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    j.id,
    j.job_number,
    j.division,
    j.phase,
    j.created_at,
    j.updated_at,
    COALESCE(j.invoiced_value,        0)       AS invoiced_value,
    COALESCE(j.collected_value,       0)       AS collected_value,
    COALESCE(j.ar_status,        'open')       AS ar_status,
    j.ar_notes,
    j.invoiced_date,
    j.last_followup_date,
    COALESCE(j.deductible,            0)       AS deductible,
    COALESCE(j.deductible_collected,  FALSE)   AS deductible_collected,
    j.deductible_collected_date,
    COALESCE(j.depreciation_held,     0)       AS depreciation_held,
    COALESCE(j.depreciation_released, 0)       AS depreciation_released,
    -- claim link (for reference / future use)
    j.claim_id,
    j.claim_number,
    j.insurance_company,
    j.policy_number,
    j.date_of_loss,
    -- contact info — all on jobs directly
    j.insured_name,
    j.client_phone,
    j.client_email,
    j.adjuster_name,
    j.adjuster_phone,
    j.adjuster_email,
    j.phase_entered_at,
    j.received_date
  FROM jobs j
  ORDER BY
    (COALESCE(j.invoiced_value, 0) - COALESCE(j.collected_value, 0)) DESC,
    j.created_at DESC;
$$;


--
-- Name: get_assigned_tasks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_assigned_tasks(p_employee_id uuid) RETURNS TABLE(task_id uuid, task_name text, is_complete boolean, sort_order integer, phase_name text, appointment_id uuid, appointment_date date, appointment_time text, is_today boolean, job_id uuid, job_number text, insured_name text, division text, job_phase text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    jt.id                                              AS task_id,
    jt.title                                           AS task_name,
    COALESCE(jt.is_completed, FALSE)                   AS is_complete,
    COALESCE(jt.display_order, 0)                      AS sort_order,
    jt.phase_name,
    jt.appointment_id,
    a.date                                             AS appointment_date,
    a.time_start::TEXT                                 AS appointment_time,
    (a.date = public.mt_today())                       AS is_today,
    j.id                                               AS job_id,
    j.job_number,
    c.name                                             AS insured_name,
    j.division::TEXT,
    j.phase                                            AS job_phase
  FROM job_tasks jt
  JOIN appointments a        ON a.id = jt.appointment_id
  JOIN appointment_crew acr  ON acr.appointment_id = a.id
                             AND acr.employee_id = p_employee_id
  JOIN jobs j                ON j.id = jt.job_id
  LEFT JOIN contacts c       ON c.id = j.primary_contact_id
  WHERE COALESCE(jt.is_completed, FALSE) = FALSE
    AND a.status NOT IN ('cancelled', 'completed')
  ORDER BY
    (a.date = public.mt_today()) DESC,
    a.date ASC,
    a.time_start ASC,
    jt.display_order ASC;
END;
$$;


--
-- Name: get_attribution_by_campaign(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attribution_by_campaign(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_org_id uuid DEFAULT NULL::uuid) RETURNS TABLE(channel text, platform text, campaign_id text, campaign_name text, spend numeric, leads bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  RETURN QUERY
  SELECT CASE s.platform WHEN 'google' THEN 'google_ads' WHEN 'meta' THEN 'meta_ads' ELSE 'other' END AS channel,
         s.platform,
         s.campaign_id,
         s.campaign_name,
         SUM(s.spend)::numeric AS spend,
         COALESCE((
           SELECT COUNT(*) FROM inbound_leads il
            WHERE il.org_id = v_org
              AND COALESCE(il.spam_flag, false) = false
              AND il.campaign IS NOT NULL
              AND lower(il.campaign) = lower(s.campaign_name)
              AND (p_start_date IS NULL OR il.occurred_at >= p_start_date::timestamptz)
              AND (p_end_date   IS NULL OR il.occurred_at <  (p_end_date + 1)::timestamptz)
         ), 0)::bigint AS leads
  FROM ad_spend s
  WHERE s.org_id = v_org
    AND (p_start_date IS NULL OR s.date >= p_start_date)
    AND (p_end_date   IS NULL OR s.date <= p_end_date)
  GROUP BY s.platform, s.campaign_id, s.campaign_name
  ORDER BY spend DESC;
END;
$$;


--
-- Name: get_attribution_rollup(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attribution_rollup(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_org_id uuid DEFAULT NULL::uuid) RETURNS TABLE(channel text, spend numeric, leads bigint, estimates bigint, won_jobs bigint, revenue numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  RETURN QUERY
  WITH channels(channel) AS (
    VALUES ('google_ads'),('meta_ads'),('organic'),('referral'),('insurance'),('other')
  ),
  contact_channel AS (
    SELECT c.id AS contact_id,
           COALESCE(
             (SELECT la.channel FROM lead_attribution la
               WHERE la.contact_id = c.id
               ORDER BY la.occurred_at DESC LIMIT 1),
             crm_channel_for_source(c.referral_source)
           ) AS channel
    FROM contacts c
  ),
  spend_agg AS (
    SELECT CASE s.platform WHEN 'google' THEN 'google_ads' WHEN 'meta' THEN 'meta_ads' ELSE 'other' END AS channel,
           SUM(s.spend) AS spend
    FROM ad_spend s
    WHERE s.org_id = v_org
      AND (p_start_date IS NULL OR s.date >= p_start_date)
      AND (p_end_date   IS NULL OR s.date <= p_end_date)
    GROUP BY 1
  ),
  leads_agg AS (
    SELECT COALESCE(
             (SELECT la.channel FROM lead_attribution la
               WHERE la.lead_id = il.id ORDER BY la.occurred_at DESC LIMIT 1),
             NULLIF(crm_channel_for_source(il.source), 'other'),
             cc.channel,
             'other'
           ) AS channel,
           COUNT(*) AS leads
    FROM inbound_leads il
    LEFT JOIN contact_channel cc ON cc.contact_id = il.contact_id
    WHERE il.org_id = v_org
      AND COALESCE(il.spam_flag, false) = false
      AND il.merged_into_lead_id IS NULL
      AND (il.source_type <> 'call' OR public.crm_call_is_answered(il.raw_payload, il.duration_sec))
      -- Denver calendar days (database-standard.md §7), not UTC midnights.
      AND (p_start_date IS NULL OR public.mt_date(il.occurred_at) >= p_start_date)
      AND (p_end_date   IS NULL OR public.mt_date(il.occurred_at) <= p_end_date)
    GROUP BY 1
  ),
  est_agg AS (
    SELECT COALESCE(cc.channel, 'other') AS channel, COUNT(DISTINCT e.id) AS estimates
    FROM estimates e
    LEFT JOIN contact_channel cc ON cc.contact_id = e.contact_id
    WHERE e.status IS DISTINCT FROM 'draft'
      AND crm_contact_is_traced(e.contact_id)
      AND (p_start_date IS NULL OR public.mt_date(e.created_at) >= p_start_date)
      AND (p_end_date   IS NULL OR public.mt_date(e.created_at) <= p_end_date)
    GROUP BY 1
  ),
  -- CANONICAL SALE RULE (UPR-Web-Context.md ⭐): is_real_job gates the SET,
  -- COALESCE(claim.created_at, job.created_at) dates it — identical to
  -- get_jobs_closed, the company's "when-sold" reporting view.
  job_agg AS (
    SELECT COALESCE(cc.channel, 'other') AS channel,
           COUNT(DISTINCT j.id) AS won_jobs,
           COALESCE(SUM(j.invoiced_value), 0) AS revenue
    FROM jobs j
    LEFT JOIN claims cl ON cl.id = j.claim_id
    LEFT JOIN contact_channel cc ON cc.contact_id = j.primary_contact_id
    WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
      AND crm_contact_is_traced(j.primary_contact_id)
      AND (p_start_date IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start_date)
      AND (p_end_date   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end_date)
    GROUP BY 1
  )
  SELECT ch.channel,
         COALESCE(sp.spend, 0)::numeric,
         COALESCE(l.leads, 0)::bigint,
         COALESCE(e.estimates, 0)::bigint,
         COALESCE(j.won_jobs, 0)::bigint,
         COALESCE(j.revenue, 0)::numeric
  FROM channels ch
  LEFT JOIN spend_agg sp ON sp.channel = ch.channel
  LEFT JOIN leads_agg l  ON l.channel  = ch.channel
  LEFT JOIN est_agg   e  ON e.channel  = ch.channel
  LEFT JOIN job_agg   j  ON j.channel  = ch.channel
  ORDER BY COALESCE(sp.spend,0) DESC, COALESCE(j.revenue,0) DESC, ch.channel;
END;
$$;


--
-- Name: get_automation_runs(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_automation_runs(p_automation_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'id', r.id, 'automation_id', r.automation_id, 'triggering_event_id', r.triggering_event_id,
    'contact_id', r.contact_id, 'contact_name', c.name,
    'entity_type', r.entity_type, 'entity_id', r.entity_id,
    'current_action', r.current_action, 'status', r.status,
    'next_run_at', r.next_run_at, 'last_error', r.last_error,
    'created_at', r.created_at, 'updated_at', r.updated_at
  )
  FROM crm_automation_runs r
  LEFT JOIN contacts c ON c.id = r.contact_id
  WHERE (p_automation_id IS NULL OR r.automation_id = p_automation_id)
    AND (p_automation_id IS NOT NULL
         OR r.org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1)))
  ORDER BY r.created_at DESC
  LIMIT GREATEST(COALESCE(p_limit, 100), 1);
$$;


--
-- Name: automation_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    sms_sending_enabled boolean DEFAULT false NOT NULL,
    speed_to_lead_enabled boolean DEFAULT false NOT NULL,
    missed_call_textback_enabled boolean DEFAULT false NOT NULL,
    no_response_followup_enabled boolean DEFAULT false NOT NULL,
    review_request_enabled boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE automation_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.automation_settings IS 'RPC-only. Read via get_automation_settings, written via set_automation_setting (both SECURITY DEFINER). Browser roles hold no table privilege: the anon key is public, and this table carries the customer-SMS kill switch.';


--
-- Name: get_automation_settings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_automation_settings(p_org_id uuid DEFAULT NULL::uuid) RETURNS public.automation_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_row automation_settings;
BEGIN
  v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'get_automation_settings: no org resolved';
  END IF;

  SELECT * INTO v_row FROM automation_settings WHERE org_id = v_org;
  IF NOT FOUND THEN
    INSERT INTO automation_settings (org_id) VALUES (v_org)
    ON CONFLICT (org_id) DO UPDATE SET updated_at = now()
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: get_avg_ticket(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_avg_ticket(p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH inv AS (
    SELECT public.dash_division_bucket(j.division::text) AS bucket,
           j.claim_id,
           COALESCE(i.adjusted_total, i.total, 0) AS amt
    FROM invoices i JOIN jobs j ON j.id = i.job_id
    WHERE i.qbo_invoice_id IS NOT NULL AND i.invoice_date BETWEEN p_start AND p_end
  )
  SELECT jsonb_build_object(
    'divisions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('key', bucket, 'avg', av))
      FROM (SELECT bucket, AVG(amt) AS av FROM inv GROUP BY bucket) s), '[]'::jsonb),
    'avg_per_claim', COALESCE((
      SELECT AVG(cs) FROM (SELECT claim_id, SUM(amt) cs FROM inv WHERE claim_id IS NOT NULL GROUP BY claim_id) c), 0)
  );
$$;


--
-- Name: get_billing_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_settings() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
  FROM integration_config
  WHERE key IN (
    'accept_card','accept_ach','default_terms','surcharge_enabled','surcharge_pct',
    'qbo_stripe_clearing_account_id','qbo_stripe_clearing_account_name',
    'qbo_fee_expense_account_id','qbo_fee_expense_account_name','stripe_connected',
    'qbo_bank_account_id','qbo_bank_account_name',
    'stripe_payout_bank_id','stripe_payout_bank_name',
    'stripe_instant_card_id','stripe_instant_card_name'
  );
$$;


--
-- Name: get_call_volume(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_call_volume(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org        uuid;
  v_start      date;
  v_end        date;
  v_earliest   date;
BEGIN
  v_org   := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_end   := COALESCE(p_end, public.mt_today());

  IF p_start IS NULL THEN
    SELECT public.mt_date(MIN(COALESCE(il.occurred_at, il.created_at))) INTO v_earliest
    FROM inbound_leads il
    WHERE il.org_id = v_org AND il.source_type = 'call' AND COALESCE(il.spam_flag, false) = false;
  END IF;
  v_start := COALESCE(p_start, v_earliest, (v_end - 29));

  RETURN QUERY
  -- Day series over NAIVE timestamps (dates), calls bucketed to their Denver
  -- day via mt_date() — no server-TZ dependence anywhere.
  WITH days AS (
    SELECT generate_series(v_start::timestamp, v_end::timestamp, interval '1 day') AS d
  ),
  calls AS (
    SELECT public.mt_date(COALESCE(il.occurred_at, il.created_at)) AS d,
           COUNT(*) AS total,
           COUNT(*) FILTER (WHERE public.crm_call_is_answered(il.raw_payload, il.duration_sec)) AS answered,
           COUNT(*) FILTER (WHERE NOT public.crm_call_is_answered(il.raw_payload, il.duration_sec)) AS missed
    FROM inbound_leads il
    WHERE il.org_id = v_org AND il.source_type = 'call' AND COALESCE(il.spam_flag, false) = false
      AND public.mt_date(COALESCE(il.occurred_at, il.created_at)) >= v_start
      AND public.mt_date(COALESCE(il.occurred_at, il.created_at)) <= v_end
    GROUP BY 1
  )
  SELECT json_build_object(
    'period',       to_char(days.d, 'YYYY-MM-DD'),
    'period_start', days.d::date,
    'total',        COALESCE(calls.total, 0),
    'answered',     COALESCE(calls.answered, 0),
    'missed',       COALESCE(calls.missed, 0)
  )
  FROM days
  LEFT JOIN calls ON calls.d = days.d::date
  ORDER BY days.d;
END;
$$;


--
-- Name: get_campaign_exclusions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_campaign_exclusions(p_campaign_id uuid) RETURNS TABLE(contact_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT contact_id FROM email_campaign_exclusions WHERE campaign_id = p_campaign_id;
$$;


--
-- Name: get_claim_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_claim_activity(p_claim_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'created_at') DESC), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', se.id,
      'event_type', se.event_type,
      'entity_type', se.entity_type,
      'entity_id', se.entity_id,
      'job_id', se.job_id,
      'payload', se.payload,
      'created_at', se.created_at,
      'actor_name', e.full_name
    ) AS row_data
    FROM system_events se
    LEFT JOIN employees e ON e.auth_user_id = se.actor_id
    WHERE se.entity_id = p_claim_id
       OR se.job_id IN (SELECT id FROM jobs WHERE claim_id = p_claim_id)
    ORDER BY se.created_at DESC
    LIMIT 50
  ) sub;

  RETURN result;
END;
$$;


--
-- Name: get_claim_appointments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_claim_appointments(p_claim_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY row_data->>'date' DESC, row_data->>'time_start' DESC NULLS LAST), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', a.id,
      'job_id', a.job_id,
      'job_number', j.job_number,
      'division', j.division,
      'title', a.title,
      'date', a.date,
      'time_start', a.time_start,
      'time_end', a.time_end,
      'type', a.type,
      'status', a.status,
      'notes', a.notes,
      'duration_days', a.duration_days,
      'is_milestone', a.is_milestone,
      'color', a.color,
      'crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'employee_id', ac.employee_id,
          'full_name', e.full_name,
          'role', ac.role
        ))
        FROM appointment_crew ac
        JOIN employees e ON e.id = ac.employee_id
        WHERE ac.appointment_id = a.id
      ), '[]'::jsonb),
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true)
    ) AS row_data
    FROM appointments a
    JOIN jobs j ON j.id = a.job_id
    WHERE j.claim_id = p_claim_id
  ) sub;

  RETURN result;
END;
$$;


--
-- Name: get_claim_demo_sheets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_claim_demo_sheets(p_claim_id uuid) RETURNS TABLE(id uuid, status text, created_at timestamp with time zone, updated_at timestamp with time zone, email_sent boolean, job_id uuid, job_number text, job_division text, technician_name text, form_date date, insured_name text, address text, room_count integer, summary jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    f.id,
    f.status,
    f.created_at,
    f.updated_at,
    f.email_sent,
    f.job_id,
    j.job_number,
    j.division::text AS job_division,
    f.technician_name,
    f.form_date,
    (f.form_data -> 'jobInfo' ->> 'insuredName') AS insured_name,
    (f.form_data -> 'jobInfo' ->> 'address')     AS address,
    COALESCE(jsonb_array_length(f.form_data -> 'rooms'), 0)::int AS room_count,
    f.summary
  FROM forms f
  JOIN jobs j ON j.id = f.job_id
  WHERE f.form_type = 'demo_sheet'
    AND j.claim_id = p_claim_id
  ORDER BY f.updated_at DESC;
$$;


--
-- Name: get_claim_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_claim_detail(p_claim_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(

    'claim', (SELECT to_jsonb(cl) FROM (
      SELECT c.id, c.claim_number, c.insurance_claim_number,
             c.contact_id, c.adjuster_contact_id,
             c.insurance_carrier, c.policy_number, c.date_of_loss,
             c.loss_address, c.loss_city, c.loss_state, c.loss_zip,
             c.loss_type, c.status, c.deductible, c.notes,
             c.created_at, c.updated_at
      FROM claims c WHERE c.id = p_claim_id
    ) cl),

    'jobs', COALESCE((
      SELECT jsonb_agg(to_jsonb(j) ORDER BY j.created_at ASC)
      FROM (
        SELECT j.id, j.job_number, j.division, j.phase, j.status, j.priority,
               j.insured_name, j.client_phone, j.client_email,
               j.address, j.city, j.state, j.zip,
               j.insurance_company, j.claim_number, j.policy_number,
               j.adjuster_name, j.adjuster_phone, j.adjuster_email,
               j.date_of_loss, j.type_of_loss, j.received_date, j.phase_entered_at,
               COALESCE(j.invoiced_value,        0)     AS invoiced_value,
               COALESCE(j.collected_value,       0)     AS collected_value,
               COALESCE(j.ar_status,        'open')     AS ar_status,
               j.ar_notes, j.invoiced_date, j.last_followup_date,
               COALESCE(j.deductible,            0)     AS deductible,
               COALESCE(j.deductible_collected,  false) AS deductible_collected,
               j.deductible_collected_date,
               COALESCE(j.depreciation_held,     0)     AS depreciation_held,
               COALESCE(j.depreciation_released, 0)     AS depreciation_released,
               COALESCE(j.supplement_value,      0)     AS supplement_value,
               COALESCE(j.estimated_value,       0)     AS estimated_value,
               COALESCE(j.approved_value,        0)     AS approved_value,
               j.primary_contact_id, j.claim_id,
               j.is_cat_loss, j.has_asbestos, j.has_lead,
               j.created_at, j.updated_at
        FROM jobs j WHERE j.claim_id = p_claim_id
      ) j
    ), '[]'::jsonb),

    'contact', (SELECT to_jsonb(ct) FROM (
      SELECT ct.id, ct.name, ct.phone, ct.email,
             ct.billing_address, ct.billing_city, ct.billing_state, ct.billing_zip
      FROM contacts ct
      WHERE ct.id = (SELECT contact_id FROM claims WHERE id = p_claim_id)
    ) ct),

    'adjuster', (SELECT to_jsonb(adj) FROM (
      SELECT adj.id, adj.name, adj.phone, adj.email, adj.company,
             adj.desk_phone, adj.desk_extension, adj.territory
      FROM contacts adj
      WHERE adj.id = (SELECT adjuster_contact_id FROM claims WHERE id = p_claim_id)
    ) adj)

  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_claim_jobs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_claim_jobs(p_claim_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'claim', (SELECT to_jsonb(cl) FROM (
      SELECT id, claim_number, insurance_claim_number, contact_id,
             insurance_carrier, policy_number, date_of_loss,
             loss_address, loss_city, loss_state, loss_zip,
             loss_type, status, deductible
      FROM claims WHERE id = p_claim_id
    ) cl),
    'jobs', COALESCE((
      SELECT jsonb_agg(to_jsonb(j) ORDER BY j.created_at ASC)
      FROM (
        SELECT id, job_number, division, phase, status, priority,
               address, city, insured_name, type_of_loss,
               estimated_value, approved_value, date_of_loss, created_at
        FROM jobs WHERE claim_id = p_claim_id
      ) j
    ), '[]'::jsonb)
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_claim_rooms(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_claim_rooms(p_claim_id uuid) RETURNS TABLE(id uuid, claim_id uuid, name text, area_sqft numeric, ceiling_height_ft numeric, sort_order integer, client_id uuid, created_by uuid, created_at timestamp with time zone, deleted_at timestamp with time zone, photo_count integer, reading_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT r.id, r.claim_id, r.name, r.area_sqft, r.ceiling_height_ft,
           r.sort_order, r.client_id, r.created_by, r.created_at, r.deleted_at,
           COALESCE((SELECT COUNT(*)::INT FROM job_documents d
                     WHERE d.room_id = r.id AND d.category='photo'), 0) AS photo_count,
           0::INT AS reading_count
    FROM rooms r
    WHERE r.claim_id = p_claim_id AND r.deleted_at IS NULL
    ORDER BY r.sort_order ASC, r.created_at ASC;
END;
$$;


--
-- Name: get_claims_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_claims_list() RETURNS TABLE(id uuid, claim_number text, insurance_claim_number text, insurance_carrier text, policy_number text, date_of_loss date, loss_type text, loss_city text, loss_state text, status text, deductible numeric, created_at timestamp with time zone, last_activity_at timestamp with time zone, insured_name text, client_phone text, job_count bigint, total_invoiced numeric, total_collected numeric, total_balance numeric, jobs_summary jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    c.id, c.claim_number, c.insurance_claim_number, c.insurance_carrier,
    c.policy_number, c.date_of_loss, c.loss_type, c.loss_city, c.loss_state,
    c.status, c.deductible, c.created_at,
    -- last_activity_at: NULL when no real activity exists (so the UI can distinguish)
    GREATEST(
      (SELECT MAX(a.updated_at) FROM appointments a JOIN jobs jj ON jj.id = a.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) AS last_activity_at,
    ct.name  AS insured_name,
    ct.phone AS client_phone,
    COUNT(j.id) AS job_count,
    COALESCE(SUM(COALESCE(j.invoiced_value,  0)), 0) AS total_invoiced,
    COALESCE(SUM(COALESCE(j.collected_value, 0)), 0) AS total_collected,
    COALESCE(SUM(GREATEST(COALESCE(j.invoiced_value,0) - COALESCE(j.collected_value,0), 0)), 0) AS total_balance,
    COALESCE(
      jsonb_agg(
        jsonb_build_object('id', j.id, 'job_number', j.job_number, 'division', j.division, 'phase', j.phase)
        ORDER BY j.created_at ASC
      ) FILTER (WHERE j.id IS NOT NULL),
      '[]'::jsonb
    ) AS jobs_summary
  FROM claims c
  LEFT JOIN contacts ct ON ct.id = c.contact_id
  LEFT JOIN jobs j ON j.claim_id = c.id
  WHERE c.status IS DISTINCT FROM 'deleted'
  GROUP BY c.id, ct.name, ct.phone
  ORDER BY
    GREATEST(
      (SELECT MAX(a.updated_at) FROM appointments a JOIN jobs jj ON jj.id = a.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) DESC NULLS LAST,
    c.created_at DESC;
$$;


--
-- Name: get_commissions(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_commissions(p_month date DEFAULT NULL::date) RETURNS TABLE(employee_id uuid, employee_name text, job_id uuid, job_number text, division text, sale_date timestamp with time zone, sale_source text, base numeric, commission numeric, commission_period date, is_attributed boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH inv AS (
    SELECT i.job_id, SUM(COALESCE(i.adjusted_total, i.total, 0)) AS base
    FROM public.invoices i
    GROUP BY i.job_id
  ),
  sold AS (
    SELECT j.id AS job_id,
           COALESCE(
             (SELECT sr.sent_by FROM public.sign_requests sr
               WHERE sr.job_id = j.id AND sr.status = 'signed'
                 AND sr.doc_type IN ('work_auth','recon_agreement') AND sr.sent_by IS NOT NULL
               ORDER BY sr.signed_at NULLS LAST LIMIT 1),
             (SELECT e.created_by FROM public.estimates e
               WHERE e.job_id = j.id AND e.created_by IS NOT NULL
                 AND lower(COALESCE(e.status,'')) IN ('approved','accepted','converted','signed')
               ORDER BY e.approved_at NULLS LAST LIMIT 1)
           ) AS sold_by
    FROM public.jobs j
    WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
  )
  SELECT
    sd.sold_by                                            AS employee_id,
    emp.full_name                                         AS employee_name,
    j.id                                                  AS job_id,
    j.job_number,
    j.division::text                                      AS division,
    j.created_at                                          AS sale_date,
    j.real_job_source                                     AS sale_source,
    COALESCE(iv.base, 0)                                  AS base,
    CASE
      WHEN emp.commission_flat    IS NOT NULL THEN emp.commission_flat
      WHEN emp.commission_percent IS NOT NULL THEN round(COALESCE(iv.base, 0) * emp.commission_percent / 100.0, 2)
      ELSE 0
    END                                                   AS commission,
    date_trunc('month', j.created_at)::date               AS commission_period,
    (sd.sold_by IS NOT NULL
       AND (emp.commission_percent IS NOT NULL OR emp.commission_flat IS NOT NULL)) AS is_attributed
  FROM public.jobs j
  JOIN sold sd              ON sd.job_id = j.id
  LEFT JOIN public.employees emp ON emp.id = sd.sold_by
  LEFT JOIN inv iv          ON iv.job_id = j.id
  WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
    AND (p_month IS NULL
         OR date_trunc('month', j.created_at) = date_trunc('month', p_month::timestamptz))
  ORDER BY j.created_at DESC;
$$;


--
-- Name: get_contact_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contact_activity(p_contact_id uuid) RETURNS TABLE(activity_type text, occurred_at timestamp with time zone, title text, body text, meta jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    'lead'::text,
    COALESCE(il.occurred_at, il.created_at),
    CASE WHEN il.source_type = 'call' THEN 'Call' ELSE 'Web form' END,
    il.transcription,
    jsonb_build_object(
      'source_type', il.source_type, 'duration_sec', il.duration_sec,
      'lead_status', il.lead_status, 'source', il.source, 'campaign', il.campaign,
      'recording_url', il.recording_url, 'transcript_analysis', il.transcript_analysis
    )
  FROM inbound_leads il
  WHERE il.contact_id = p_contact_id
    AND il.merged_into_lead_id IS NULL

  UNION ALL

  SELECT
    'sms'::text,
    m.created_at,
    CASE WHEN m.sender_contact_id = p_contact_id THEN 'Received SMS' ELSE 'Sent SMS' END,
    m.body,
    jsonb_build_object(
      'type', m.type, 'status', m.status,
      'sent_by_name', COALESCE(es.display_name, es.full_name)
    )
  FROM messages m
  LEFT JOIN employees es ON es.id = m.sent_by
  WHERE m.conversation_id IN (
    SELECT cp.conversation_id FROM conversation_participants cp WHERE cp.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'note'::text,
    jn.created_at,
    'Note'::text,
    jn.body,
    jsonb_build_object('job_id', jn.job_id, 'author_name', jn.author_name)
  FROM job_notes jn
  WHERE jn.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'note'::text,
    ln.created_at,
    'Note'::text,
    ln.body,
    jsonb_build_object('note_id', ln.id, 'author_name', COALESCE(eln.display_name, eln.full_name))
  FROM crm_lead_notes ln
  LEFT JOIN employees eln ON eln.id = ln.created_by
  WHERE ln.contact_id = p_contact_id
     OR ln.lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'estimate'::text,
    e.created_at,
    'Estimate ' || COALESCE(e.estimate_number, e.id::text),
    NULL::text,
    jsonb_build_object(
      'status', e.status, 'amount', e.amount, 'estimate_id', e.id,
      'created_by_name', COALESCE(eest.display_name, eest.full_name)
    )
  FROM estimates e
  LEFT JOIN employees eest ON eest.id = e.created_by
  WHERE e.contact_id = p_contact_id

  UNION ALL

  SELECT
    'email'::text,
    COALESCE(r.sent_at, r.created_at),
    'Campaign email'::text,
    ec.subject,
    jsonb_build_object('status', r.status, 'campaign', ec.name, 'campaign_id', ec.id)
  FROM email_campaign_recipients r
  JOIN email_campaigns ec ON ec.id = r.campaign_id
  WHERE r.contact_id = p_contact_id

  UNION ALL

  SELECT
    'job'::text,
    j.created_at,
    'Job ' || COALESCE(j.job_number, j.id::text),
    j.address,
    jsonb_build_object('status', j.status, 'job_id', j.id)
  FROM jobs j
  WHERE j.id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'task'::text,
    COALESCE(t.due_at, t.created_at),
    t.title,
    t.notes,
    jsonb_build_object(
      'status', t.status, 'due_at', t.due_at, 'task_id', t.id,
      'created_by_name', COALESCE(etc.display_name, etc.full_name),
      'assignee_name', COALESCE(eta.display_name, eta.full_name)
    )
  FROM crm_tasks t
  LEFT JOIN employees etc ON etc.id = t.created_by
  LEFT JOIN employees eta ON eta.id = t.assignee_id
  WHERE t.contact_id = p_contact_id
     OR t.lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'appointment'::text,
    (a.date + COALESCE(a.time_start, '00:00'::time))::timestamptz,
    COALESCE(a.title, 'Appointment'),
    a.notes,
    jsonb_build_object(
      'status', a.status, 'type', a.type, 'time_start', a.time_start,
      'time_end', a.time_end, 'job_id', a.job_id,
      'created_by_name', COALESCE(eap.display_name, eap.full_name)
    )
  FROM appointments a
  LEFT JOIN employees eap ON eap.id = a.created_by
  WHERE a.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'invoice'::text,
    COALESCE(i.invoice_date::timestamptz, i.created_at),
    'Invoice ' || COALESCE(i.invoice_number, i.id::text),
    NULL::text,
    jsonb_build_object(
      'status', i.status, 'total', i.total, 'amount_paid', i.amount_paid,
      'balance_due', i.balance_due, 'invoice_id', i.id, 'due_date', i.due_date,
      'created_by_name', COALESCE(einv.display_name, einv.full_name)
    )
  FROM invoices i
  LEFT JOIN employees einv ON einv.id = i.created_by
  WHERE i.contact_id = p_contact_id

  UNION ALL

  SELECT
    'work_authorization'::text,
    COALESCE(sr.signed_at, sr.sent_at, sr.created_at),
    COALESCE(initcap(replace(sr.doc_type, '_', ' ')), 'Work Authorization'),
    NULL::text,
    jsonb_build_object(
      'status', sr.status, 'doc_type', sr.doc_type, 'signed_at', sr.signed_at,
      'signed_file_path', sr.signed_file_path, 'job_id', sr.job_id,
      'sent_by_name', COALESCE(esr.display_name, esr.full_name)
    )
  FROM sign_requests sr
  LEFT JOIN employees esr ON esr.id = sr.sent_by
  WHERE sr.contact_id = p_contact_id

  UNION ALL

  SELECT
    'stage_change'::text,
    lsh.moved_at,
    'Moved to ' || ps.name,
    NULL::text,
    jsonb_build_object(
      'from_stage_id', lsh.from_stage_id, 'stage_id', lsh.stage_id, 'lost_reason', lsh.lost_reason,
      'moved_by_name', COALESCE(elsh.display_name, elsh.full_name)
    )
  FROM lead_stage_history lsh
  JOIN pipeline_stages ps ON ps.id = lsh.stage_id
  LEFT JOIN employees elsh ON elsh.id = lsh.moved_by
  WHERE lsh.lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'follow_up_call'::text,
    COALESCE(fu.occurred_at, fu.created_at),
    CASE WHEN fu.source_type = 'call' THEN 'Follow-up call' ELSE 'Follow-up web form' END,
    fu.transcription,
    jsonb_build_object(
      'source_type', fu.source_type, 'duration_sec', fu.duration_sec,
      'caller_number', fu.caller_number, 'recording_url', fu.recording_url,
      'transcript_analysis', fu.transcript_analysis, 'merged_lead_id', fu.id
    )
  FROM inbound_leads fu
  WHERE fu.merged_into_lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'claim'::text,
    cl.created_at,
    'Claim ' || COALESCE(cl.claim_number, cl.id::text),
    NULLIF(TRIM(BOTH ' ' FROM COALESCE(cl.loss_type, '') || CASE WHEN cl.insurance_carrier IS NOT NULL THEN ' — ' || cl.insurance_carrier ELSE '' END), ''),
    jsonb_build_object(
      'status', cl.status, 'claim_id', cl.id, 'insurance_carrier', cl.insurance_carrier,
      'date_of_loss', cl.date_of_loss,
      'created_by_name', COALESCE(ecl.display_name, ecl.full_name)
    )
  FROM claims cl
  LEFT JOIN employees ecl ON ecl.id = cl.created_by
  WHERE cl.contact_id = p_contact_id

  UNION ALL

  SELECT
    'phase_change'::text,
    h.changed_at,
    'Phase: ' || COALESCE(pf.label, h.from_phase) || ' → ' || COALESCE(pt.label, h.to_phase),
    NULL::text,
    jsonb_build_object(
      'job_id', h.job_id, 'from_phase', h.from_phase, 'to_phase', h.to_phase,
      'changed_by_name', COALESCE(eph.display_name, eph.full_name)
    )
  FROM job_phase_history h
  LEFT JOIN employees eph ON eph.id = h.changed_by
  LEFT JOIN job_phases pf ON pf.key = h.from_phase
  LEFT JOIN job_phases pt ON pt.key = h.to_phase
  WHERE h.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'payment'::text,
    COALESCE(p.payment_date::timestamptz, p.created_at),
    'Payment received'::text,
    NULL::text,
    jsonb_build_object(
      'amount', p.amount, 'method', p.payment_method, 'invoice_id', p.invoice_id,
      'recorded_by_name', COALESCE(epay.display_name, epay.full_name)
    )
  FROM payments p
  LEFT JOIN employees epay ON epay.id = p.recorded_by
  WHERE p.contact_id = p_contact_id

  UNION ALL

  SELECT
    'document'::text,
    jd.created_at,
    COALESCE(jd.name, initcap(replace(jd.category, '_', ' ')), 'Document'),
    NULL::text,
    jsonb_build_object(
      'job_id', jd.job_id, 'category', jd.category,
      'uploaded_by_name', COALESCE(eupl.display_name, eupl.full_name)
    )
  FROM job_documents jd
  LEFT JOIN employees eupl ON eupl.id = jd.uploaded_by
  WHERE jd.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'contact_owner_set'::text,
    se_own.created_at,
    'Owner changed'::text,
    NULL::text,
    se_own.payload || jsonb_build_object(
      'actor_name', COALESCE(eown.display_name, eown.full_name)
    )
  FROM system_events se_own
  LEFT JOIN employees eown ON eown.id = se_own.actor_id
  WHERE se_own.event_type = 'crm_contact_owner_set'
    AND se_own.entity_type = 'contact'
    AND se_own.entity_id = p_contact_id

  UNION ALL

  SELECT
    'contact_lifecycle_set'::text,
    se_life.created_at,
    'Lifecycle status changed'::text,
    NULL::text,
    se_life.payload || jsonb_build_object(
      'actor_name', COALESCE(elife.display_name, elife.full_name)
    )
  FROM system_events se_life
  LEFT JOIN employees elife ON elife.id = se_life.actor_id
  WHERE se_life.event_type = 'crm_contact_lifecycle_set'
    AND se_life.entity_type = 'contact'
    AND se_life.entity_id = p_contact_id

  UNION ALL

  SELECT
    'work_auth_sent'::text,
    COALESCE(wasent.sent_at, wasent.created_at),
    'Work authorization sent'::text,
    NULL::text,
    jsonb_build_object(
      'status', wasent.status, 'doc_type', wasent.doc_type, 'sent_at', wasent.sent_at,
      'job_id', wasent.job_id, 'signer_name', wasent.signer_name, 'signer_email', wasent.signer_email,
      'sent_by_name', COALESCE(ewasent.display_name, ewasent.full_name)
    )
  FROM sign_requests wasent
  LEFT JOIN employees ewasent ON ewasent.id = wasent.sent_by
  WHERE wasent.contact_id = p_contact_id
    AND wasent.doc_type = 'work_auth'

  UNION ALL

  SELECT
    'work_auth_signed'::text,
    wasigned.signed_at,
    'Work authorization signed'::text,
    NULL::text,
    jsonb_build_object(
      'status', wasigned.status, 'doc_type', wasigned.doc_type, 'job_id', wasigned.job_id,
      'signed_file_path', wasigned.signed_file_path,
      'signer_name', wasigned.signer_name, 'signer_email', wasigned.signer_email
    )
  FROM sign_requests wasigned
  WHERE wasigned.contact_id = p_contact_id
    AND wasigned.doc_type = 'work_auth'
    AND wasigned.signed_at IS NOT NULL

  UNION ALL

  SELECT
    'scope_sheet'::text,
    COALESCE(ds.form_date::timestamptz, ds.created_at),
    COALESCE('Scope sheet — ' || ds.technician_name, 'Scope sheet'),
    NULL::text,
    jsonb_build_object(
      'status', ds.status, 'job_id', ds.job_id, 'technician_name', ds.technician_name,
      'form_date', ds.form_date, 'summary', ds.summary,
      'submitted_by_name', COALESCE(eds.display_name, eds.full_name)
    )
  FROM forms ds
  LEFT JOIN employees eds ON eds.id = ds.submitted_by
  WHERE ds.form_type = 'demo_sheet'
    AND ds.job_id IN (
      SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
    )

  UNION ALL

  SELECT
    'invoice_sent'::text,
    i2.qbo_emailed_at,
    'Invoice sent' || CASE WHEN i2.invoice_number IS NOT NULL THEN ' — ' || i2.invoice_number ELSE '' END,
    NULL::text,
    jsonb_build_object(
      'invoice_id', i2.id, 'sent_to_email', i2.sent_to_email, 'qbo_email_status', i2.qbo_email_status
    )
  FROM invoices i2
  WHERE i2.contact_id = p_contact_id
    AND i2.qbo_emailed_at IS NOT NULL

  UNION ALL

  SELECT
    'estimate_sent'::text,
    e2.qbo_emailed_at,
    'Estimate sent' || CASE WHEN e2.estimate_number IS NOT NULL THEN ' — ' || e2.estimate_number ELSE '' END,
    NULL::text,
    jsonb_build_object(
      'estimate_id', e2.id, 'sent_to_email', e2.sent_to_email, 'qbo_email_status', e2.qbo_email_status
    )
  FROM estimates e2
  WHERE e2.contact_id = p_contact_id
    AND e2.qbo_emailed_at IS NOT NULL

  ORDER BY 2 DESC;
$$;


--
-- Name: get_contact_addresses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contact_addresses(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(to_jsonb(a) ORDER BY a.is_billing DESC, a.created_at ASC)
    FROM contact_addresses a WHERE a.contact_id = p_contact_id
  ), '[]'::jsonb);
END; $$;


--
-- Name: get_contact_consent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contact_consent(p_contact_id uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'contact_id', c.id,
    'do_not_contact',
      COALESCE(c.dnd, false)
      OR c.opt_out_at IS NOT NULL
      OR EXISTS (SELECT 1 FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))),
    'sms', json_build_object(
      'dnd', COALESCE(c.dnd, false),
      'opted_out', c.opt_out_at IS NOT NULL,
      'opt_out_at', c.opt_out_at,
      'opt_out_reason', c.opt_out_reason
    ),
    'email', json_build_object(
      'address', c.email,
      'suppressed', EXISTS (SELECT 1 FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))),
      'reason', (SELECT es.reason FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))
                 ORDER BY es.suppressed_at DESC NULLS LAST LIMIT 1),
      'suppressed_at', (SELECT es.suppressed_at FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))
                 ORDER BY es.suppressed_at DESC NULLS LAST LIMIT 1)
    )
  )
  FROM contacts c
  WHERE c.id = p_contact_id;
$$;


--
-- Name: get_contact_ltv(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contact_ltv(p_contact_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH won AS (
    SELECT j.primary_contact_id AS cid,
           COUNT(*) AS jobs,
           COALESCE(SUM(j.invoiced_value), 0) AS revenue,
           MIN(COALESCE(cl.created_at, j.created_at)) AS first_job_at,
           MAX(COALESCE(cl.created_at, j.created_at)) AS last_job_at
    FROM jobs j
    LEFT JOIN claims cl ON cl.id = j.claim_id
    WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
      AND j.primary_contact_id IS NOT NULL
      AND (p_contact_id IS NULL OR j.primary_contact_id = p_contact_id)
    GROUP BY j.primary_contact_id
  )
  SELECT json_build_object(
    'contact_id',   won.cid,
    'contact_name', c.name,
    'jobs',         won.jobs,
    'revenue',      won.revenue,
    'first_job_at', won.first_job_at,
    'last_job_at',  won.last_job_at,
    'is_repeat',    (won.jobs > 1)
  )
  FROM won
  LEFT JOIN contacts c ON c.id = won.cid
  ORDER BY won.revenue DESC
  LIMIT (CASE WHEN p_contact_id IS NULL THEN 25 ELSE 1 END);
END;
$$;


--
-- Name: get_conversion_trend(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conversion_trend(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_start date;
  v_end   date;
BEGIN
  v_org   := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_end   := COALESCE(p_end, public.mt_today());
  v_start := COALESCE(p_start, (date_trunc('month', v_end::timestamp) - interval '11 months')::date);

  RETURN QUERY
  -- All buckets are Denver calendar months: mt_date() collapses each event to
  -- its Denver day first, then date_trunc months over NAIVE timestamps (no
  -- server-TZ dependence anywhere).
  WITH months AS (
    SELECT generate_series(date_trunc('month', v_start::timestamp),
                           date_trunc('month', v_end::timestamp),
                           interval '1 month') AS m
  ),
  lead_c AS (
    SELECT date_trunc('month', public.mt_date(COALESCE(il.occurred_at, il.created_at))::timestamp) AS m, COUNT(*) AS c
    FROM inbound_leads il
    WHERE il.org_id = v_org AND COALESCE(il.spam_flag, false) = false
      AND (il.source_type <> 'call' OR public.crm_call_is_answered(il.raw_payload, il.duration_sec))
      AND public.mt_date(COALESCE(il.occurred_at, il.created_at)) >= v_start
      AND public.mt_date(COALESCE(il.occurred_at, il.created_at)) <= v_end
    GROUP BY 1
  ),
  est_c AS (
    SELECT date_trunc('month', public.mt_date(e.created_at)::timestamp) AS m, COUNT(*) AS c
    FROM estimates e
    WHERE e.status IS DISTINCT FROM 'draft'
      AND crm_contact_is_traced(e.contact_id)
      AND public.mt_date(e.created_at) >= v_start
      AND public.mt_date(e.created_at) <= v_end
    GROUP BY 1
  ),
  -- CANONICAL SALE RULE (see job_agg note in get_attribution_rollup).
  job_c AS (
    SELECT date_trunc('month', public.mt_date(COALESCE(cl.created_at, j.created_at))::timestamp) AS m,
           COUNT(*) AS c,
           COALESCE(SUM(j.invoiced_value), 0) AS rev
    FROM jobs j
    LEFT JOIN claims cl ON cl.id = j.claim_id
    WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
      AND crm_contact_is_traced(j.primary_contact_id)
      AND public.mt_date(COALESCE(cl.created_at, j.created_at)) >= v_start
      AND public.mt_date(COALESCE(cl.created_at, j.created_at)) <= v_end
    GROUP BY 1
  )
  SELECT json_build_object(
    'period',       to_char(months.m, 'YYYY-MM'),
    'period_start', months.m::date,
    'leads',        COALESCE(lead_c.c, 0),
    'estimates',    COALESCE(est_c.c, 0),
    'won_jobs',     COALESCE(job_c.c, 0),
    'revenue',      COALESCE(job_c.rev, 0)
  )
  FROM months
  LEFT JOIN lead_c ON lead_c.m = months.m
  LEFT JOIN est_c  ON est_c.m  = months.m
  LEFT JOIN job_c  ON job_c.m  = months.m
  ORDER BY months.m;
END;
$$;


--
-- Name: get_crm_automations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_automations(p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'id', a.id, 'name', a.name, 'description', a.description,
    'trigger_event_type', a.trigger_event_type,
    'conditions', a.conditions, 'actions', a.actions,
    'enabled', a.enabled, 'created_at', a.created_at, 'updated_at', a.updated_at,
    'stats', (
      SELECT json_build_object(
        'active',    count(*) FILTER (WHERE r.status = 'active'),
        'held',      count(*) FILTER (WHERE r.status = 'held'),
        'completed', count(*) FILTER (WHERE r.status = 'completed'),
        'skipped',   count(*) FILTER (WHERE r.status = 'skipped'),
        'failed',    count(*) FILTER (WHERE r.status = 'failed'),
        'total',     count(*)
      ) FROM crm_automation_runs r WHERE r.automation_id = a.id
    )
  )
  FROM crm_automations a
  WHERE a.org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1))
  ORDER BY a.created_at DESC;
$$;


--
-- Name: get_crm_build_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_build_progress() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_phases jsonb;
  v_overall_done  int;
  v_overall_total int;
BEGIN
  SELECT COALESCE(jsonb_agg(x.phase_obj ORDER BY x.sort_order), '[]'::jsonb)
    INTO v_phases
  FROM (
    SELECT
      p.sort_order,
      jsonb_build_object(
        'phase_key',   p.phase_key,
        'title',       p.title,
        'status',      p.status,
        'shipped_at',  p.shipped_at,
        'sort_order',  p.sort_order,
        'stages',      COALESCE(s.stages, '[]'::jsonb),
        'done_count',  COALESCE(s.done_count, 0),
        'total_count', COALESCE(s.total_count, 0)
      ) AS phase_obj
    FROM crm_build_phases p
    LEFT JOIN (
      SELECT
        cs.phase_key,
        jsonb_agg(
          jsonb_build_object('id', cs.id, 'title', cs.title, 'status', cs.status, 'sort_order', cs.sort_order)
          ORDER BY cs.sort_order
        ) AS stages,
        COUNT(*) FILTER (WHERE cs.status = 'done') AS done_count,
        COUNT(*) AS total_count
      FROM crm_build_stages cs
      GROUP BY cs.phase_key
    ) s ON s.phase_key = p.phase_key
  ) x;

  SELECT COALESCE(SUM((phase->>'done_count')::int), 0), COALESCE(SUM((phase->>'total_count')::int), 0)
    INTO v_overall_done, v_overall_total
  FROM jsonb_array_elements(v_phases) AS phase;

  RETURN jsonb_build_object(
    'phases',        v_phases,
    'overall_done',  v_overall_done,
    'overall_total', v_overall_total
  );
END;
$$;


--
-- Name: get_crm_contacts(text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_contacts(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH s AS (SELECT nullif(btrim(p_search), '') AS term),
  d AS (SELECT regexp_replace(COALESCE((SELECT term FROM s), ''), '[^0-9]', '', 'g') AS digits),
  matched AS (
    SELECT c.*
    FROM contacts c
    WHERE (SELECT term FROM s) IS NULL
       OR c.name    ILIKE '%' || (SELECT term FROM s) || '%'
       OR c.email   ILIKE '%' || (SELECT term FROM s) || '%'
       OR c.company ILIKE '%' || (SELECT term FROM s) || '%'
       OR ((SELECT digits FROM d) <> ''
           AND regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g') LIKE '%' || (SELECT digits FROM d) || '%')
  )
  SELECT json_build_object(
    'id', id, 'name', name, 'phone', phone, 'email', email,
    'company', company, 'role', role, 'lifecycle_status', lifecycle_status,
    'owner_id', owner_id, 'tags', COALESCE(tags, '[]'::jsonb), 'created_at', created_at,
    'total_count', total_count
  )
  FROM (
    SELECT m.*, count(*) OVER () AS total_count FROM matched m
  ) x
  ORDER BY (x.name IS NULL), lower(x.name), x.created_at DESC
  LIMIT  GREATEST(COALESCE(p_limit, 50), 0)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$$;


--
-- Name: get_crm_revenue_by_division(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_revenue_by_division(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(division text, won_jobs bigint, revenue numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT j.division::text,
         COUNT(*)::bigint,
         COALESCE(SUM(j.invoiced_value), 0)::numeric
  FROM jobs j
  LEFT JOIN claims cl ON cl.id = j.claim_id
  WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
    AND crm_contact_is_traced(j.primary_contact_id)
    AND (p_start_date IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start_date)
    AND (p_end_date   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end_date)
  GROUP BY j.division
  ORDER BY 3 DESC;
$$;


--
-- Name: get_crm_sales_summary(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_sales_summary(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'total_won',      COUNT(*),
    'total_revenue',  COALESCE(SUM(j.invoiced_value), 0),
    'traced_won',     COUNT(*) FILTER (WHERE crm_contact_is_traced(j.primary_contact_id)),
    'traced_revenue', COALESCE(SUM(j.invoiced_value) FILTER (WHERE crm_contact_is_traced(j.primary_contact_id)), 0)
  )
  FROM jobs j
  LEFT JOIN claims cl ON cl.id = j.claim_id
  WHERE j.is_real_job = true
    AND j.status IS DISTINCT FROM 'deleted'
    AND (p_start_date IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start_date)
    AND (p_end_date   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end_date);
$$;


--
-- Name: get_crm_tasks(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_tasks(p_assignee uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_lead_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT json_build_object(
    'id', t.id, 'title', t.title, 'notes', t.notes, 'due_at', t.due_at,
    'remind_at', t.remind_at, 'status', t.status,
    'assignee_id', t.assignee_id, 'assignee_name', e.full_name,
    'contact_id', t.contact_id, 'contact_name', c.name, 'lead_id', t.lead_id,
    'created_at', t.created_at, 'updated_at', t.updated_at, 'completed_at', t.completed_at
  )
  FROM crm_tasks t
  LEFT JOIN employees e ON e.id = t.assignee_id
  LEFT JOIN contacts  c ON c.id = t.contact_id
  WHERE (p_org_id     IS NULL OR t.org_id      = p_org_id)
    AND (p_assignee   IS NULL OR t.assignee_id = p_assignee)
    AND (p_status     IS NULL OR t.status      = p_status)
    AND (p_contact_id IS NULL OR t.contact_id  = p_contact_id)
    AND (p_lead_id    IS NULL OR t.lead_id     = p_lead_id)
  ORDER BY (t.status <> 'open') ASC, t.due_at ASC NULLS LAST, t.created_at DESC;
END;
$$;


--
-- Name: get_customer_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_detail(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_contact jsonb; v_claims jsonb; v_financials jsonb; v_files jsonb; v_activity jsonb; v_addresses jsonb;
  v_job_ids uuid[];
BEGIN
  SELECT to_jsonb(c) INTO v_contact FROM contacts c WHERE c.id = p_contact_id;
  IF v_contact IS NULL THEN RETURN NULL; END IF;

  SELECT array_agg(cj.job_id) INTO v_job_ids FROM contact_jobs cj WHERE cj.contact_id = p_contact_id;

  -- Addresses
  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.is_billing DESC, a.created_at ASC), '[]'::jsonb)
  INTO v_addresses FROM contact_addresses a WHERE a.contact_id = p_contact_id;

  -- Claims with nested jobs
  SELECT COALESCE(jsonb_agg(to_jsonb(cl_row) ORDER BY cl_row.date_of_loss DESC NULLS LAST), '[]'::jsonb)
  INTO v_claims
  FROM (
    SELECT cl.id, cl.claim_number, cl.insurance_claim_number, cl.insurance_carrier,
      cl.policy_number, cl.date_of_loss, cl.loss_address, cl.loss_city, cl.loss_state, cl.loss_zip,
      cl.loss_type, cl.status, cl.deductible, cl.notes,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id',j.id,'job_number',j.job_number,'division',j.division,'phase',j.phase,'status',j.status,'priority',j.priority,
          'address',j.address,'city',j.city,'insurance_company',j.insurance_company,'date_of_loss',j.date_of_loss,'created_at',j.created_at,
          'estimated_value',j.estimated_value,'approved_value',j.approved_value,'invoiced_value',j.invoiced_value,'collected_value',j.collected_value,
          'deductible',j.deductible,'supplement_value',j.supplement_value,
          'total_labor_cost',j.total_labor_cost,'total_material_cost',j.total_material_cost,
          'total_equipment_cost',j.total_equipment_cost,'total_sub_cost',j.total_sub_cost,'total_other_cost',j.total_other_cost
        ) ORDER BY j.created_at ASC)
        FROM jobs j WHERE j.claim_id = cl.id
      ), '[]'::jsonb) AS jobs
    FROM claims cl WHERE cl.contact_id = p_contact_id
  ) cl_row;

  -- Financials
  SELECT jsonb_build_object(
    'total_estimated',COALESCE(sum(j.estimated_value),0),'total_approved',COALESCE(sum(j.approved_value),0),
    'total_invoiced',COALESCE(sum(j.invoiced_value),0),'total_collected',COALESCE(sum(j.collected_value),0),
    'total_deductible',COALESCE(sum(j.deductible),0),'total_supplement',COALESCE(sum(j.supplement_value),0),
    'total_depreciation_held',COALESCE(sum(j.depreciation_held),0),'total_depreciation_released',COALESCE(sum(j.depreciation_released),0),
    'total_labor_cost',COALESCE(sum(j.total_labor_cost),0),'total_material_cost',COALESCE(sum(j.total_material_cost),0),
    'total_equipment_cost',COALESCE(sum(j.total_equipment_cost),0),'total_sub_cost',COALESCE(sum(j.total_sub_cost),0),
    'total_other_cost',COALESCE(sum(j.total_other_cost),0),'job_count',count(*)::int
  ) INTO v_financials FROM jobs j WHERE j.id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[]));

  -- Files
  SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.created_at DESC), '[]'::jsonb)
  INTO v_files FROM (
    SELECT doc.id,doc.job_id,doc.name,doc.file_path,doc.file_size,doc.mime_type,doc.category,doc.created_at,j.job_number
    FROM job_documents doc JOIN jobs j ON j.id=doc.job_id
    WHERE doc.job_id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[])) LIMIT 200
  ) d;

  -- Activity
  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.date DESC), '[]'::jsonb)
  INTO v_activity FROM (
    SELECT n.id,'note' as type,n.created_at as date,COALESCE(n.body,'') as content,
      COALESCE(n.author_name,e.full_name,'Unknown') as author,j.job_number
    FROM job_notes n LEFT JOIN employees e ON e.id=n.author_id LEFT JOIN jobs j ON j.id=n.job_id
    WHERE n.job_id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[]))
    UNION ALL
    SELECT h.id,'phase_change' as type,h.changed_at as date,
      ('Phase: '||COALESCE(pf.label,h.from_phase)||' → '||COALESCE(pt.label,h.to_phase)) as content,
      COALESCE(e.full_name,'System') as author,j.job_number
    FROM job_phase_history h LEFT JOIN employees e ON e.id=h.changed_by LEFT JOIN jobs j ON j.id=h.job_id
      LEFT JOIN job_phases pf ON pf.key=h.from_phase LEFT JOIN job_phases pt ON pt.key=h.to_phase
    WHERE h.job_id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[]))
    ORDER BY date DESC LIMIT 100
  ) a;

  RETURN jsonb_build_object(
    'contact', v_contact, 'addresses', v_addresses, 'claims', v_claims,
    'financials', COALESCE(v_financials,'{}'::jsonb), 'files', v_files, 'activity', v_activity
  );
END; $$;


--
-- Name: get_customers_list(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customers_list(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  q text;
BEGIN
  q := '%' || lower(COALESCE(trim(p_search), '')) || '%';

  SELECT jsonb_agg(to_jsonb(r))
  INTO result
  FROM (
    SELECT
      c.id, c.name, c.phone, c.email, c.company, c.role,
      c.billing_address, c.billing_city, c.billing_state, c.billing_zip,
      c.insurance_carrier, c.policy_number,
      c.preferred_contact_method, c.preferred_language,
      c.tags, c.notes, c.dnd, c.created_at, c.updated_at,
      -- Claims with nested jobs
      COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', cl.id,
            'claim_number', cl.claim_number,
            'insurance_claim_number', cl.insurance_claim_number,
            'date_of_loss', cl.date_of_loss,
            'loss_address', cl.loss_address,
            'loss_city', cl.loss_city,
            'loss_type', cl.loss_type,
            'insurance_carrier', cl.insurance_carrier,
            'status', cl.status,
            'jobs', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'id', j.id, 'job_number', j.job_number, 'division', j.division,
                'phase', j.phase, 'address', j.address, 'city', j.city,
                'insurance_company', j.insurance_company,
                'date_of_loss', j.date_of_loss, 'created_at', j.created_at
              ) ORDER BY j.created_at ASC)
              FROM jobs j WHERE j.claim_id = cl.id
            ), '[]'::jsonb)
          ) ORDER BY cl.date_of_loss DESC NULLS LAST
        )
        FROM claims cl WHERE cl.contact_id = c.id),
        '[]'::jsonb
      ) AS claims,
      -- Flat jobs list (backward compat)
      COALESCE(
        (SELECT jsonb_agg(jsonb_build_object(
          'id', j.id, 'job_number', j.job_number, 'division', j.division,
          'phase', j.phase, 'address', j.address, 'city', j.city,
          'insurance_company', j.insurance_company, 'date_of_loss', j.date_of_loss,
          'created_at', j.created_at
        ) ORDER BY j.created_at DESC)
        FROM contact_jobs cj JOIN jobs j ON j.id = cj.job_id
        WHERE cj.contact_id = c.id),
        '[]'::jsonb
      ) AS jobs,
      (SELECT count(*) FROM contact_jobs cj WHERE cj.contact_id = c.id)::int AS job_count
    FROM contacts c
    WHERE c.role IN ('homeowner', 'tenant', 'property_manager')
      AND (p_search IS NULL OR p_search = ''
        OR lower(c.name) LIKE q
        OR c.phone LIKE q
        OR lower(COALESCE(c.email, '')) LIKE q
        OR lower(COALESCE(c.billing_address, '')) LIKE q
        OR lower(COALESCE(c.billing_city, '')) LIKE q)
    ORDER BY c.created_at DESC
    LIMIT p_limit OFFSET p_offset
  ) r;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: get_dashboard_action_items(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_action_items(p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH sigs AS (
    SELECT j.id AS job_id,
           j.job_number AS job,
           j.insured_name AS client,
           NULLIF(CONCAT_WS(', ',
             NULLIF(j.address, ''),
             NULLIF(j.city, ''),
             NULLIF(j.state, '') || CASE WHEN j.zip IS NOT NULL AND j.zip <> '' THEN ' ' || j.zip ELSE '' END
           ), '') AS address,
           CASE sr.doc_type
             WHEN 'coc' THEN 'Certificate of Completion unsigned'
             WHEN 'work_auth' THEN 'Work authorization unsigned'
             WHEN 'direction_pay' THEN 'Direction-to-pay unsigned'
             WHEN 'recon_agreement' THEN 'Reconstruction agreement unsigned'
             ELSE 'Document unsigned'
           END AS text,
           'Awaiting signature · sent ' || to_char(COALESCE(sr.sent_at, sr.created_at), 'Mon DD') AS sub,
           COALESCE(sr.sent_at, sr.created_at) AS ts
    FROM sign_requests sr LEFT JOIN jobs j ON j.id = sr.job_id
    WHERE sr.status = 'pending'
  )
  SELECT COALESCE(jsonb_agg(x ORDER BY ts ASC NULLS LAST), '[]'::jsonb)
  FROM (
    SELECT jsonb_build_object(
             'job_id', job_id, 'job', job, 'client', client, 'address', address,
             'kind', 'esign', 'text', text, 'sub', sub
           ) AS x, ts
    FROM sigs ORDER BY ts ASC NULLS LAST LIMIT p_limit
  ) q;
$$;


--
-- Name: get_dashboard_layout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_layout() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT dl.layout
  FROM public.dashboard_layouts dl
  JOIN public.employees e ON e.id = dl.employee_id
  WHERE e.auth_user_id = auth.uid()
  LIMIT 1;
$$;


--
-- Name: get_dashboard_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_stats() RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT json_build_object(
    'active_jobs', (
      SELECT COUNT(*)::int
      FROM jobs
      WHERE phase NOT IN ('completed', 'closed', 'cancelled')
    ),
    'needs_response', (
      SELECT COUNT(*)::int
      FROM conversations
      WHERE status = 'needs_response'
    ),
    'total_contacts', (
      SELECT COUNT(*)::int
      FROM contacts
    ),
    'open_leads', (
      SELECT COUNT(*)::int
      FROM contacts
      WHERE role = 'lead'
    )
  );
$$;


