--
-- Name: get_employee_commissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_commissions() RETURNS TABLE(id uuid, full_name text, role text, is_active boolean, commission_percent numeric, commission_flat numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NOT COALESCE(
       auth.jwt() ->> 'role' = 'service_role',
       false
     )
     AND NOT public.can_current_employee_access_settings() THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: commission settings access required'
      USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    employee.id,
    employee.full_name,
    employee.role::text,
    employee.is_active,
    employee.commission_percent,
    employee.commission_flat
  FROM public.employees employee
  ORDER BY
    (employee.is_active IS NOT TRUE),
    employee.full_name;
END;
$$;


--
-- Name: get_employee_directory(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_directory(p_include_inactive boolean DEFAULT false) RETURNS TABLE(id uuid, full_name text, display_name text, role text, color text, avatar_url text, is_active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_actor_is_external boolean;
  v_is_service boolean := COALESCE(
    auth.jwt() ->> 'role' = 'service_role',
    false
  );
BEGIN
  IF NOT v_is_service THEN
    SELECT employee.role::text, employee.is_external
      INTO v_actor_role, v_actor_is_external
    FROM public.employees employee
    WHERE employee.auth_user_id = v_actor_id
      AND employee.is_active;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'NOT_AUTHORIZED: active employee required'
        USING errcode = '42501';
    END IF;

    IF p_include_inactive
       AND (
         v_actor_is_external
         OR v_actor_role NOT IN (
           'admin',
           'office',
           'project_manager',
           'supervisor'
         )
       ) THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: inactive employee directory requires time-admin access'
        USING errcode = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    employee.id,
    employee.full_name,
    employee.display_name,
    employee.role::text,
    employee.color,
    employee.avatar_url,
    employee.is_active
  FROM public.employees employee
  WHERE COALESCE(p_include_inactive, false)
     OR employee.is_active
  ORDER BY
    (employee.is_active IS NOT TRUE),
    COALESCE(employee.display_name, employee.full_name),
    employee.full_name;
END;
$$;


--
-- Name: get_employee_notification_overrides(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_notification_overrides(p_employee_id uuid) RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH emp AS (
    SELECT id, role::text AS role FROM public.employees WHERE id = p_employee_id
  ),
  channels(channel) AS (VALUES ('bell'), ('push'), ('email')),
  matrix AS (
    SELECT t.type_key, t.label, t.category, t.sort_order,
           t.enabled AS type_enabled, c.channel,
           CASE c.channel WHEN 'bell'  THEN t.bell_default
                          WHEN 'push'  THEN t.push_default
                          ELSE              t.email_default END AS type_channel_default
      FROM public.notification_types t
      CROSS JOIN channels c
  )
  SELECT json_build_object(
    'type_key',          m.type_key,
    'label',             m.label,
    'category',          m.category,
    'sort_order',        m.sort_order,
    'channel',           m.channel,
    'type_enabled',      m.type_enabled,
    'role_default',      COALESCE(rd.enabled, m.type_channel_default),
    'user_customizable', COALESCE(rd.user_customizable, true),
    'has_override',      (ov.id IS NOT NULL),
    'override_enabled',  ov.enabled,
    'has_my_pref',       (mp.id IS NOT NULL),
    'effective',
      CASE
        WHEN COALESCE(rd.user_customizable, true) AND mp.enabled IS NOT NULL
          THEN mp.enabled
        ELSE COALESCE(ov.enabled, rd.enabled, m.type_channel_default)
      END
  )
  FROM matrix m
  CROSS JOIN emp e
  LEFT JOIN public.notification_role_defaults rd
    ON rd.role = e.role AND rd.type_key = m.type_key AND rd.channel = m.channel
  LEFT JOIN public.notification_employee_overrides ov
    ON ov.employee_id = e.id AND ov.type_key = m.type_key AND ov.channel = m.channel
  LEFT JOIN public.notification_prefs mp
    ON mp.employee_id = e.id AND mp.type_key = m.type_key AND mp.channel = m.channel
  ORDER BY m.sort_order, m.type_key, m.channel;
$$;


