--
-- Name: get_estimate_aging(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_estimate_aging(p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH open_est AS (
    SELECT COALESCE(e.submitted_at, e.created_at) AS since, e.amount
    FROM estimates e
    WHERE e.status = 'submitted' AND e.converted_invoice_id IS NULL
  ),
  aged AS (
    SELECT amount, EXTRACT(EPOCH FROM (now() - since)) / 86400.0 AS days FROM open_est
  ),
  binned AS (
    SELECT CASE
      WHEN days <= 7  THEN 1
      WHEN days <= 14 THEN 2
      WHEN days <= 30 THEN 3
      WHEN days <= 60 THEN 4
      ELSE 5
    END AS b, amount
    FROM aged
  ),
  counts AS (SELECT b, COUNT(*) AS c, COALESCE(SUM(amount), 0) AS amt FROM binned GROUP BY b),
  defs(sort_order, label) AS (
    VALUES (1, '0–7 days'), (2, '8–14 days'), (3, '15–30 days'), (4, '31–60 days'), (5, '60+ days')
  )
  SELECT json_build_object(
    'bucket',       defs.label,
    'sort_order',   defs.sort_order,
    'count',        COALESCE(counts.c, 0),
    'total_amount', COALESCE(counts.amt, 0)
  )
  FROM defs
  LEFT JOIN counts ON counts.b = defs.sort_order
  ORDER BY defs.sort_order;
END;
$$;


--
-- Name: get_estimates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_estimates() RETURNS TABLE(estimate_id uuid, estimate_number text, estimate_type text, status text, amount numeric, created_at timestamp with time zone, submitted_at timestamp with time zone, expiration_date date, qbo_estimate_id text, qbo_doc_number text, qbo_sync_error text, qbo_emailed_at timestamp with time zone, job_id uuid, job_number text, division text, claim_id uuid, claim_number text, contact_id uuid, client_name text, converted_invoice_id uuid, converted_invoice_number text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    e.id, e.estimate_number, e.estimate_type, e.status,
    COALESCE(e.amount, 0), e.created_at, e.submitted_at, e.expiration_date,
    e.qbo_estimate_id, e.qbo_doc_number, e.qbo_sync_error, e.qbo_emailed_at,
    e.job_id, j.job_number,
    COALESCE(e.intended_division, j.division::text)    AS division,
    j.claim_id, cl.claim_number,
    COALESCE(e.contact_id, j.primary_contact_id)       AS contact_id,
    ct.name                                            AS client_name,
    e.converted_invoice_id,
    COALESCE(iv.qbo_doc_number, iv.invoice_number)     AS converted_invoice_number
  FROM estimates e
  LEFT JOIN jobs     j  ON j.id  = e.job_id
  LEFT JOIN claims   cl ON cl.id = j.claim_id
  LEFT JOIN contacts ct ON ct.id = COALESCE(e.contact_id, j.primary_contact_id)
  LEFT JOIN invoices iv ON iv.id = e.converted_invoice_id
  ORDER BY e.created_at DESC;
$$;


--
-- Name: get_estimator_leaderboard(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_estimator_leaderboard(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  -- `total_jobs` is the DENOMINATOR — every opportunity the estimator touched —
  -- so it stays windowed by `j.created_at` (when the opportunity entered the
  -- system). Only the WON half is a sale, so only it is gated by is_real_job
  -- AND dated by the canonical sale date. Keeping the claim-date substitution
  -- out of the outer WHERE is deliberate: putting it there silently re-windows
  -- the denominator too (caught by migration-safety-checker, 2026-07-22).
  SELECT json_build_object(
    'estimator',  j.estimator,
    'total_jobs', COUNT(*),
    'won_jobs',   COUNT(*) FILTER (
                    WHERE j.is_real_job = true
                      AND (p_start IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start)
                      AND (p_end   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end)),
    'revenue',    COALESCE(SUM(j.invoiced_value) FILTER (
                    WHERE j.is_real_job = true
                      AND (p_start IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start)
                      AND (p_end   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end)), 0)
  )
  FROM jobs j
  LEFT JOIN claims cl ON cl.id = j.claim_id
  WHERE j.estimator IS NOT NULL AND btrim(j.estimator) <> ''
    AND j.status IS DISTINCT FROM 'deleted'
    AND crm_contact_is_traced(j.primary_contact_id)
    AND (p_start IS NULL OR public.mt_date(j.created_at) >= p_start)
    AND (p_end   IS NULL OR public.mt_date(j.created_at) <= p_end)
  GROUP BY j.estimator
  ORDER BY COALESCE(SUM(j.invoiced_value) FILTER (
             WHERE j.is_real_job = true
               AND (p_start IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start)
               AND (p_end   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end)), 0) DESC;
END;
$$;


