    AS $$
  SELECT id, name, short_name
  FROM insurance_carriers
  WHERE is_active = true
  ORDER BY sort_order ASC, name ASC;
$$;


--
-- Name: get_integration_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_integration_status(p_provider text DEFAULT 'quickbooks'::text) RETURNS TABLE(provider text, connected boolean, environment text, company_name text, realm_id text, token_expires_at timestamp with time zone, connected_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    p_provider,
    EXISTS (
      SELECT 1 FROM integration_credentials c
      WHERE c.provider = p_provider AND (c.refresh_token IS NOT NULL OR c.access_token IS NOT NULL)
    ),
    c.environment, c.company_name, c.realm_id, c.token_expires_at, c.connected_at
  FROM (SELECT 1) one
  LEFT JOIN integration_credentials c ON c.provider = p_provider
  WHERE NOT is_crm_partner(auth.uid());
$$;


--
-- Name: get_job_contacts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_contacts(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(to_jsonb(r) ORDER BY r.is_primary DESC, r.role ASC)
  INTO result
  FROM (
    SELECT
      cj.id AS link_id, cj.role, cj.is_primary, cj.notes AS link_notes,
      c.id, c.name, c.phone, c.email, c.company,
      c.role AS contact_role,
      c.billing_address, c.billing_city, c.billing_state, c.billing_zip,
      c.insurance_carrier, c.desk_phone, c.desk_extension
    FROM contact_jobs cj
    JOIN contacts c ON c.id = cj.contact_id
    WHERE cj.job_id = p_job_id
  ) r;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: get_job_demo_sheets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_demo_sheets(p_job_id uuid) RETURNS TABLE(id uuid, status text, created_at timestamp with time zone, updated_at timestamp with time zone, email_sent boolean, job_id uuid, technician_name text, form_date date, insured_name text, address text, room_count integer, summary jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    f.id,
    f.status,
    f.created_at,
    f.updated_at,
    f.email_sent,
    f.job_id,
    f.technician_name,
    f.form_date,
    (f.form_data -> 'jobInfo' ->> 'insuredName') AS insured_name,
    (f.form_data -> 'jobInfo' ->> 'address')     AS address,
    COALESCE(jsonb_array_length(f.form_data -> 'rooms'), 0)::int AS room_count,
    f.summary
  FROM forms f
  WHERE f.form_type = 'demo_sheet'
    AND f.job_id = p_job_id
  ORDER BY f.updated_at DESC;
$$;


--
-- Name: get_job_equipment(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_equipment(p_job_id uuid, p_include_removed boolean DEFAULT false) RETURNS TABLE(id uuid, job_id uuid, room_id uuid, room_name text, equipment_type public.equipment_type, nickname text, serial_number text, status text, placed_at timestamp with time zone, removed_at timestamp with time zone, placed_by uuid, removed_by uuid, notes text, client_id uuid, created_at timestamp with time zone, days_onsite integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT ep.id, ep.job_id, ep.room_id, r.name AS room_name,
           ep.equipment_type, ep.nickname, ep.serial_number, ep.status,
           ep.placed_at, ep.removed_at, ep.placed_by, ep.removed_by,
           ep.notes, ep.client_id, ep.created_at,
           EXTRACT(DAY FROM (COALESCE(ep.removed_at, now()) - ep.placed_at))::INT AS days_onsite
      FROM equipment_placements ep
      LEFT JOIN rooms r ON r.id = ep.room_id
     WHERE ep.job_id = p_job_id
       AND (p_include_removed OR ep.status = 'active')
     ORDER BY CASE WHEN ep.status = 'active' THEN 0 ELSE 1 END ASC, ep.placed_at DESC;
END;
$$;


--
-- Name: get_job_financials(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_financials(p_job_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(job_id uuid, invoice_count integer, invoiced numeric, collected numeric, balance_due numeric, deductible numeric, insurance_responsibility numeric, homeowner_responsibility numeric, depreciation_withheld numeric, depreciation_released numeric, invoiced_date date)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    i.job_id,
    count(*)::int                                          AS invoice_count,
    COALESCE(sum(COALESCE(i.adjusted_total, i.total)), 0)  AS invoiced,
    COALESCE(sum(COALESCE(i.amount_paid, 0)), 0)           AS collected,
    COALESCE(sum(
      COALESCE(i.balance_due,
               COALESCE(i.adjusted_total, i.total) - COALESCE(i.amount_paid, 0))
    ), 0)                                                  AS balance_due,
    COALESCE(sum(COALESCE(i.deductible_amount, 0)), 0)         AS deductible,
    COALESCE(sum(COALESCE(i.insurance_responsibility, 0)), 0)  AS insurance_responsibility,
    COALESCE(sum(COALESCE(i.homeowner_responsibility, 0)), 0)  AS homeowner_responsibility,
    COALESCE(sum(COALESCE(i.depreciation_withheld, 0)), 0)     AS depreciation_withheld,
    COALESCE(sum(COALESCE(i.depreciation_released, 0)), 0)     AS depreciation_released,
    min(i.qbo_synced_at)::date                                 AS invoiced_date
  FROM invoices i
  WHERE i.qbo_invoice_id IS NOT NULL
    AND i.job_id IS NOT NULL
    AND (p_job_ids IS NULL OR i.job_id = ANY (p_job_ids))
  GROUP BY i.job_id;
$$;


--
-- Name: get_job_hub(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_hub(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'job', to_jsonb(j.*),
    'claim', CASE WHEN c.id IS NOT NULL
      THEN jsonb_build_object('id', c.id, 'claim_number', c.claim_number)
      ELSE NULL END,
    'contacts', public.get_job_contacts(j.id),
    'work_auth_signed', EXISTS (
      SELECT 1 FROM sign_requests sr
      WHERE sr.job_id = j.id
        AND sr.doc_type = 'work_auth'
        AND sr.status = 'signed'
    ),
    'appointments', COALESCE((
      SELECT jsonb_agg(row_data ORDER BY row_data->>'date' DESC, row_data->>'time_start' DESC NULLS LAST)
      FROM (
        SELECT jsonb_build_object(
          'id', a.id,
          'job_id', a.job_id,
          'job_number', j.job_number,
          'division', j.division,
          'title', a.title,
          'date', a.date,
          'time_start', a.time_start,
          'time_end', a.time_end,
          'type', a.type,
          'status', a.status,
          'notes', a.notes,
          'duration_days', a.duration_days,
          'is_milestone', a.is_milestone,
          'color', a.color,
          'crew', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
              'employee_id', ac.employee_id,
              'full_name', e.full_name,
              'role', ac.role
            ))
            FROM appointment_crew ac
            JOIN employees e ON e.id = ac.employee_id
            WHERE ac.appointment_id = a.id
          ), '[]'::jsonb),
          'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
          'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true)
        ) AS row_data
        FROM appointments a
        WHERE a.job_id = j.id
      ) sub
    ), '[]'::jsonb)
  )
  INTO result
  FROM jobs j
  LEFT JOIN claims c ON c.id = j.claim_id
  WHERE j.id = p_job_id;

  RETURN result;
END;
$$;


--
-- Name: get_job_labor_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_labor_summary(p_job_id uuid DEFAULT NULL::uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(job_id uuid, job_number text, insured_name text, division text, employee_id uuid, employee_name text, total_hours numeric, travel_hours numeric, total_cost numeric, approved_hours numeric, approved_cost numeric, entry_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    j.id AS job_id,
    j.job_number,
    j.insured_name,
    j.division,
    e.id AS employee_id,
    e.full_name AS employee_name,
    SUM(t.hours) AS total_hours,
    SUM(COALESCE(t.travel_minutes, 0)) / 60.0 AS travel_hours,
    SUM(t.total_cost) AS total_cost,
    SUM(CASE WHEN t.approved THEN t.hours ELSE 0 END) AS approved_hours,
    SUM(CASE WHEN t.approved THEN t.total_cost ELSE 0 END) AS approved_cost,
    COUNT(*) AS entry_count
  FROM job_time_entries t
  JOIN employees e ON e.id = t.employee_id
  JOIN jobs j ON j.id = t.job_id
  WHERE (p_job_id IS NULL OR t.job_id = p_job_id)
    AND (p_start_date IS NULL OR t.work_date >= p_start_date)
    AND (p_end_date IS NULL OR t.work_date <= p_end_date)
  GROUP BY j.id, j.job_number, j.insured_name, j.division, e.id, e.full_name
  ORDER BY j.job_number, e.full_name;
$$;


--
-- Name: get_job_readings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_readings(p_job_id uuid) RETURNS TABLE(id uuid, job_id uuid, room_id uuid, room_name text, equipment_id uuid, reading_date date, material public.material_type, location_description text, mc_pct numeric, rh_pct numeric, temp_f numeric, gpp numeric, dew_point_f numeric, dry_standard_pct numeric, drying_goal_pct numeric, is_affected boolean, taken_by uuid, taken_at timestamp with time zone, edited_at timestamp with time zone, edited_by uuid, notes text, client_id uuid, created_at timestamp with time zone, is_stalled boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH latest_per_pair AS (
    SELECT DISTINCT ON (mr.room_id, mr.material)
           mr.id AS latest_id, mr.room_id, mr.material,
           mr.mc_pct AS latest_mc, mr.drying_goal_pct AS latest_goal,
           mr.taken_at AS latest_taken_at
      FROM moisture_readings mr
     WHERE mr.job_id = p_job_id
     ORDER BY mr.room_id, mr.material, mr.taken_at DESC
  ),
  stall_check AS (
    SELECT lpp.latest_id,
           (lpp.latest_mc IS NOT NULL AND lpp.latest_goal IS NOT NULL
            AND lpp.latest_mc > lpp.latest_goal
            AND EXISTS (
              SELECT 1 FROM moisture_readings prior
               WHERE prior.job_id = p_job_id
                 AND prior.room_id IS NOT DISTINCT FROM lpp.room_id
                 AND prior.material = lpp.material
                 AND prior.id <> lpp.latest_id
                 AND prior.taken_at <= lpp.latest_taken_at - interval '36 hours'
                 AND prior.mc_pct IS NOT NULL
                 AND (prior.mc_pct - lpp.latest_mc) < 1.0
            )) AS is_stalled
      FROM latest_per_pair lpp
  )
  SELECT mr.id, mr.job_id, mr.room_id, r.name AS room_name,
         mr.equipment_id, mr.reading_date, mr.material, mr.location_description,
         mr.mc_pct, mr.rh_pct, mr.temp_f, mr.gpp, mr.dew_point_f,
         mr.dry_standard_pct, mr.drying_goal_pct,
         mr.is_affected, mr.taken_by, mr.taken_at, mr.edited_at, mr.edited_by,
         mr.notes, mr.client_id, mr.created_at,
         COALESCE(sc.is_stalled, false) AS is_stalled
    FROM moisture_readings mr
    LEFT JOIN rooms r ON r.id = mr.room_id
    LEFT JOIN stall_check sc ON sc.latest_id = mr.id
   WHERE mr.job_id = p_job_id
   ORDER BY mr.reading_date DESC, mr.taken_at DESC;
END;
$$;


--
-- Name: get_job_rooms(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_rooms(p_job_id uuid) RETURNS TABLE(id uuid, claim_id uuid, name text, area_sqft numeric, ceiling_height_ft numeric, sort_order integer, client_id uuid, created_by uuid, created_at timestamp with time zone, deleted_at timestamp with time zone, photo_count integer, reading_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_claim_id UUID;
BEGIN
  SELECT j.claim_id INTO v_claim_id FROM jobs j WHERE j.id = p_job_id;
  IF v_claim_id IS NULL THEN RETURN; END IF;
  RETURN QUERY
    SELECT r.id, r.claim_id, r.name, r.area_sqft, r.ceiling_height_ft,
           r.sort_order, r.client_id, r.created_by, r.created_at, r.deleted_at,
           COALESCE((SELECT COUNT(*)::INT FROM job_documents d
                     WHERE d.room_id = r.id AND d.category='photo'), 0) AS photo_count,
           0::INT AS reading_count
    FROM rooms r
    WHERE r.claim_id = v_claim_id AND r.deleted_at IS NULL
    ORDER BY r.sort_order ASC, r.created_at ASC;
END;
$$;


--
-- Name: get_job_schedule(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_schedule(p_job_schedule_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', js.id, 'job_id', js.job_id, 'template_id', js.template_id,
    'name', js.name, 'start_date', js.start_date, 'status', js.status,
    'notes', js.notes, 'created_at', js.created_at,
    'template', (SELECT jsonb_build_object('name', st.name, 'division', st.division) FROM schedule_templates st WHERE st.id = js.template_id),
    'appointments', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'title', a.title, 'date', a.date,
        'time_start', a.time_start, 'time_end', a.time_end,
        'type', a.type, 'status', a.status, 'duration_days', a.duration_days,
        'color', a.color, 'is_milestone', a.is_milestone,
        'template_phase_id', a.template_phase_id, 'notes', a.notes,
        'crew', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', ac.id, 'employee_id', ac.employee_id, 'role', ac.role,
            'employee', jsonb_build_object('display_name', e.display_name, 'full_name', e.full_name, 'role', e.role)
          )) FROM appointment_crew ac JOIN employees e ON e.id = ac.employee_id WHERE ac.appointment_id = a.id
        ), '[]'::jsonb),
        'tasks', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', at2.id, 'title', at2.title, 'description', at2.description,
            'is_required', at2.is_required, 'is_completed', at2.is_completed,
            'completed_by', at2.completed_by, 'completed_at', at2.completed_at,
            'display_order', at2.display_order
          ) ORDER BY at2.display_order) FROM appointment_tasks at2 WHERE at2.appointment_id = a.id
        ), '[]'::jsonb)
      ) ORDER BY a.date, a.time_start NULLS LAST)
      FROM appointments a WHERE a.job_schedule_id = js.id
    ), '[]'::jsonb),
    'dependencies', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', ad.id, 'source_appointment_id', ad.source_appointment_id,
        'target_appointment_id', ad.target_appointment_id,
        'dependency_type', ad.dependency_type, 'lag_days', ad.lag_days
      )) FROM appointment_dependencies ad WHERE ad.job_schedule_id = js.id
    ), '[]'::jsonb)
  ) INTO result
  FROM job_schedules js WHERE js.id = p_job_schedule_id;
  RETURN result;
END; $$;


--
-- Name: get_job_schedules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_schedules(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', js.id, 'template_id', js.template_id, 'name', js.name,
    'start_date', js.start_date, 'status', js.status, 'created_at', js.created_at,
    'template_name', st.name,
    'appointment_count', (SELECT count(*) FROM appointments a WHERE a.job_schedule_id = js.id),
    'completed_count', (SELECT count(*) FROM appointments a WHERE a.job_schedule_id = js.id AND a.status = 'completed'),
    'task_count', (SELECT count(*) FROM appointment_tasks at2 JOIN appointments a ON at2.appointment_id = a.id WHERE a.job_schedule_id = js.id),
    'tasks_completed', (SELECT count(*) FROM appointment_tasks at2 JOIN appointments a ON at2.appointment_id = a.id WHERE a.job_schedule_id = js.id AND at2.is_completed = true)
  ) ORDER BY js.created_at DESC), '[]'::jsonb) INTO result
  FROM job_schedules js LEFT JOIN schedule_templates st ON st.id = js.template_id
  WHERE js.job_id = p_job_id;
  RETURN result;
END; $$;


--
-- Name: get_job_task_pool(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_task_pool(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(phase_data ORDER BY (phase_data->>'sort_order')::INT), '[]'::JSONB)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'phase_name', sub.phase_name,
      'phase_color', sub.phase_color,
      'target_start', sub.target_start,
      'target_end', sub.target_end,
      'duration_days', sub.duration_days,
      'sort_order', COALESCE(sub.sort_order, 999),
      'total', sub.total,
      'assigned', sub.assigned,
      'completed', sub.completed,
      'tasks', sub.tasks
    ) AS phase_data
    FROM (
      SELECT
        jt.phase_name,
        jt.phase_color,
        MAX(jsp.target_start) AS target_start,
        MAX(jsp.target_end) AS target_end,
        MAX(jsp.duration_days) AS duration_days,
        MIN(jsp.sort_order) AS sort_order,
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE jt.appointment_id IS NOT NULL) AS assigned,
        COUNT(*) FILTER (WHERE jt.is_completed) AS completed,
        jsonb_agg(
          jsonb_build_object(
            'id', jt.id,
            'title', jt.title,
            'is_completed', jt.is_completed,
            'is_required', jt.is_required,
            'appointment_id', jt.appointment_id,
            'target_date', jt.target_date,
            'completed_at', jt.completed_at
          ) ORDER BY jt.created_at
        ) AS tasks
      FROM job_tasks jt
      LEFT JOIN job_schedule_phases jsp ON jsp.id = jt.job_schedule_phase_id
      WHERE jt.job_id = p_job_id
      GROUP BY jt.phase_name, jt.phase_color
    ) sub
  ) wrapper;

  RETURN v_result;
END;
$$;


--
-- Name: get_job_task_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_task_summary(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total', count(*),
    'assigned', count(*) FILTER (WHERE appointment_id IS NOT NULL),
    'unassigned', count(*) FILTER (WHERE appointment_id IS NULL),
    'completed', count(*) FILTER (WHERE is_completed),
    'required_total', count(*) FILTER (WHERE is_required),
    'required_completed', count(*) FILTER (WHERE is_required AND is_completed),
    'by_phase', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'phase_name', sub.phase_name,
        'phase_color', sub.phase_color,
        'total', sub.total,
        'completed', sub.completed,
        'assigned', sub.assigned
      ) ORDER BY sub.phase_name), '[]'::jsonb)
      FROM (
        SELECT phase_name, phase_color,
          count(*) as total,
          count(*) FILTER (WHERE is_completed) as completed,
          count(*) FILTER (WHERE appointment_id IS NOT NULL) as assigned
        FROM job_tasks WHERE job_id = p_job_id
        GROUP BY phase_name, phase_color
      ) sub
    )
  ) INTO result
  FROM job_tasks WHERE job_id = p_job_id;

  RETURN result;
END;
$$;


--
-- Name: get_jobs_closed(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_jobs_closed(p_floor date DEFAULT NULL::date) RETURNS TABLE(job_id uuid, sale_date timestamp with time zone, sale_source text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT j.id,
         COALESCE(c.created_at, j.created_at) AS sale_date,
         j.real_job_source                    AS sale_source
  FROM public.jobs j
  LEFT JOIN public.claims c ON c.id = j.claim_id
  WHERE j.is_real_job = true
    AND j.status IS DISTINCT FROM 'deleted'
    AND (p_floor IS NULL OR public.mt_date(COALESCE(c.created_at, j.created_at)) >= p_floor)
  ORDER BY sale_date DESC;
$$;


--
-- Name: get_jobs_completed(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_jobs_completed(p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'count', (SELECT count(*) FROM jobs
              WHERE phase IN ('completed','closed') AND actual_completion BETWEEN p_start AND p_end),
    'last_month', (SELECT count(*) FROM jobs
              WHERE phase IN ('completed','closed')
                AND actual_completion >= date_trunc('month', CURRENT_DATE - interval '1 month')::date
                AND actual_completion <  date_trunc('month', CURRENT_DATE)::date)
  );
$$;


--
-- Name: get_jobs_list(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_jobs_list(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT to_json(t) FROM (
    SELECT
      j.id, j.job_number, j.insured_name, j.phase, j.division, j.source, j.status,
      j.address, j.city, j.state, j.zip, j.claim_number, j.insurance_company,
      j.date_of_loss, j.received_date, j.target_completion,
      j.project_manager, j.project_manager_id, j.lead_tech_id,
      j.estimated_value, j.approved_value, j.invoiced_value, j.collected_value,
      j.priority, j.tags, j.is_cat_loss, j.has_asbestos, j.has_lead,
      j.phase_entered_at, j.created_at, j.updated_at,
      count(*) OVER() AS total_count
    FROM public.jobs j
    WHERE j.status <> 'deleted'
      AND (
        p_search IS NULL OR btrim(p_search) = '' OR
        j.insured_name      ILIKE '%' || btrim(p_search) || '%' OR
        j.job_number        ILIKE '%' || btrim(p_search) || '%' OR
        j.address           ILIKE '%' || btrim(p_search) || '%' OR
        j.claim_number      ILIKE '%' || btrim(p_search) || '%' OR
        j.insurance_company ILIKE '%' || btrim(p_search) || '%'
      )
    ORDER BY j.created_at DESC
    LIMIT  GREATEST(LEAST(COALESCE(p_limit, 100), 500), 1)
    OFFSET GREATEST(COALESCE(p_offset, 0), 0)
  ) t;
$$;


--
-- Name: get_lead_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lead_activity(p_lead_id uuid) RETURNS TABLE(activity_type text, occurred_at timestamp with time zone, title text, body text, meta jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    'lead'::text,
    COALESCE(il.occurred_at, il.created_at),
    CASE WHEN il.source_type = 'call' THEN 'Call' ELSE 'Web form' END,
    il.transcription,
    jsonb_build_object(
      'source_type', il.source_type, 'duration_sec', il.duration_sec,
      'lead_status', il.lead_status, 'source', il.source, 'campaign', il.campaign,
      'recording_url', il.recording_url, 'transcript_analysis', il.transcript_analysis
    )
  FROM inbound_leads il
  WHERE il.id = p_lead_id

  UNION ALL

  SELECT
    'note'::text,
    ln.created_at,
    'Note'::text,
    ln.body,
    jsonb_build_object('note_id', ln.id, 'author_name', COALESCE(en.display_name, en.full_name))
  FROM crm_lead_notes ln
  LEFT JOIN employees en ON en.id = ln.created_by
  WHERE ln.lead_id = p_lead_id
     OR ln.lead_id IN (SELECT id FROM inbound_leads WHERE merged_into_lead_id = p_lead_id)

  UNION ALL

  SELECT
    'task'::text,
    COALESCE(t.due_at, t.created_at),
    t.title,
    t.notes,
    jsonb_build_object(
      'status', t.status, 'due_at', t.due_at, 'task_id', t.id,
      'created_by_name', COALESCE(ec.display_name, ec.full_name),
      'assignee_name', COALESCE(ea.display_name, ea.full_name)
    )
  FROM crm_tasks t
  LEFT JOIN employees ec ON ec.id = t.created_by
  LEFT JOIN employees ea ON ea.id = t.assignee_id
  WHERE t.lead_id = p_lead_id

  UNION ALL

  SELECT
    'stage_change'::text,
    lsh.moved_at,
    'Moved to ' || ps.name,
    NULL::text,
    jsonb_build_object(
      'from_stage_id', lsh.from_stage_id, 'stage_id', lsh.stage_id, 'lost_reason', lsh.lost_reason,
      'moved_by_name', COALESCE(em.display_name, em.full_name)
    )
  FROM lead_stage_history lsh
  JOIN pipeline_stages ps ON ps.id = lsh.stage_id
  LEFT JOIN employees em ON em.id = lsh.moved_by
  WHERE lsh.lead_id = p_lead_id

  UNION ALL

  SELECT
    'follow_up_call'::text,
    COALESCE(fu.occurred_at, fu.created_at),
    CASE WHEN fu.source_type = 'call' THEN 'Follow-up call' ELSE 'Follow-up web form' END,
    fu.transcription,
    jsonb_build_object(
      'source_type', fu.source_type, 'duration_sec', fu.duration_sec,
      'caller_number', fu.caller_number, 'recording_url', fu.recording_url,
      'transcript_analysis', fu.transcript_analysis, 'merged_lead_id', fu.id
    )
  FROM inbound_leads fu
  WHERE fu.merged_into_lead_id = p_lead_id

  ORDER BY 2 DESC;
$$;


--
-- Name: get_lead_notes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lead_notes(p_lead_id uuid) RETURNS SETOF json
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'id', ln.id,
    'lead_id', ln.lead_id,
    'body', ln.body,
    'created_at', ln.created_at,
    'created_by', ln.created_by,
    'author_name', COALESCE(e.display_name, e.full_name)
  )
  FROM crm_lead_notes ln
  LEFT JOIN employees e ON e.id = ln.created_by
  WHERE ln.lead_id = p_lead_id
     OR ln.lead_id IN (SELECT id FROM inbound_leads WHERE merged_into_lead_id = p_lead_id)
  ORDER BY ln.created_at DESC;
$$;


--
-- Name: get_managed_credentials_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_managed_credentials_status() RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.p9_assert_admin();

  RETURN QUERY
  SELECT json_build_object(
           'provider', p.provider,
           'connected', (c.access_token IS NOT NULL AND (
             p.provider <> 'encircle' OR c.managed_status = 'active'
           )),
           'connected_at', CASE WHEN c.access_token IS NOT NULL THEN c.connected_at END,
           'updated_at', c.updated_at,
           'managed_status', CASE WHEN p.provider = 'encircle' THEN c.managed_status END,
           'last_verified_at', CASE WHEN p.provider = 'encircle' THEN c.last_verified_at END,
           'last_verification_status',
             CASE WHEN p.provider = 'encircle' THEN c.last_verification_status END,
           'organization_name', CASE WHEN p.provider = 'encircle' THEN c.company_name END,
           'phone_number', CASE WHEN p.provider = 'twilio'
                                THEN (SELECT value FROM integration_config WHERE key = 'twilio_phone_number')
                           END,
           'has_account_sid', CASE WHEN p.provider = 'twilio'
                                   THEN (SELECT value IS NOT NULL AND btrim(value) <> ''
                                         FROM integration_config WHERE key = 'twilio_account_sid')
                              END,
           'has_messaging_service', CASE WHEN p.provider = 'twilio'
                                         THEN (SELECT value IS NOT NULL AND btrim(value) <> ''
                                               FROM integration_config WHERE key = 'twilio_messaging_service_sid')
                                    END
         )
  FROM (VALUES ('stripe'), ('twilio'), ('resend'), ('encircle')) AS p(provider)
  LEFT JOIN public.integration_credentials c ON c.provider = p.provider;
END;
$$;


--
-- Name: get_message_author_directory(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_message_author_directory(p_message_ids uuid[]) RETURNS TABLE(id uuid, full_name text, display_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_is_service boolean := COALESCE(
    auth.jwt() ->> 'role' = 'service_role',
    false
  );
BEGIN
  IF NOT v_is_service
     AND NOT public.messaging_can_access_conversations() THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: Conversations access required for message authors'
      USING errcode = '42501';
  END IF;

  IF p_message_ids IS NULL
     OR array_position(p_message_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION
      'INVALID_MESSAGE_AUTHORS: message IDs must be non-null'
      USING errcode = '22023';
  END IF;

  IF cardinality(p_message_ids) > 200 THEN
    RAISE EXCEPTION
      'INVALID_MESSAGE_AUTHORS: at most 200 message IDs are allowed'
      USING errcode = '22023';
  END IF;

  IF cardinality(p_message_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH requested_message AS (
    SELECT DISTINCT requested.message_id
    FROM unnest(p_message_ids) requested(message_id)
  ),
  author AS (
    SELECT DISTINCT
      employee.id,
      employee.full_name,
      employee.display_name
    FROM requested_message requested
    JOIN public.messages message
      ON message.id = requested.message_id
     AND message.type = 'internal_note'
    JOIN public.employees employee
      ON employee.id = message.sent_by
  )
  SELECT
    author.id,
    author.full_name,
    author.display_name
  FROM author
  ORDER BY
    COALESCE(author.display_name, author.full_name),
    author.full_name;
END;
$$;


--
-- Name: get_message_log(integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_message_log(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_direction text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS TABLE(id uuid, body text, direction text, status text, created_at timestamp with time zone, contact_name text, contact_phone text, conversation_id uuid, media_url text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    m.id, m.body,
    CASE WHEN m.sender_contact_id IS NOT NULL THEN 'inbound' ELSE 'outbound' END AS direction,
    m.status, m.created_at,
    COALESCE(c.name, cp.phone) AS contact_name,
    cp.phone AS contact_phone,
    m.conversation_id,
    m.media_urls AS media_url
  FROM messages m
  JOIN conversations conv ON m.conversation_id = conv.id
  LEFT JOIN conversation_participants cp ON cp.conversation_id = conv.id AND cp.is_active = true
  LEFT JOIN contacts c ON cp.contact_id = c.id
  WHERE (p_direction IS NULL
    OR (p_direction = 'inbound' AND m.sender_contact_id IS NOT NULL)
    OR (p_direction = 'outbound' AND m.sender_contact_id IS NULL))
    AND (p_status IS NULL OR m.status = p_status)
  ORDER BY m.created_at DESC
  LIMIT p_limit OFFSET p_offset;
$$;


--
-- Name: account_deletion_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_deletion_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    notes text,
    actioned_by uuid,
    actioned_at timestamp with time zone,
    CONSTRAINT account_deletion_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'actioned'::text, 'denied'::text])))
);


--
-- Name: get_my_account_deletion_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_account_deletion_request() RETURNS public.account_deletion_requests
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.*
  FROM public.account_deletion_requests r
  JOIN public.employees e ON e.id = r.employee_id
  WHERE e.auth_user_id = auth.uid()
    AND r.status = 'pending'
  ORDER BY r.requested_at DESC
  LIMIT 1;
$$;


--
-- Name: get_my_appointments_today(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_appointments_today(p_employee_id uuid, p_include_cancelled boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  today date := public.mt_today();
BEGIN
  SELECT jsonb_agg(row_data ORDER BY (row_data->>'time_start'))
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', a.id, 'job_id', a.job_id, 'title', a.title, 'date', a.date,
      'time_start', a.time_start, 'time_end', a.time_end, 'type', a.type,
      'status', a.status, 'notes', a.notes,
      'color', a.color, 'kind', a.kind, 'duration_days', a.duration_days, 'is_milestone', a.is_milestone,
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true),
      'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
        'id', j.id, 'job_number', j.job_number, 'insured_name', j.insured_name, 'address', j.address,
        'city', j.city, 'division', j.division, 'phase', j.phase, 'client_phone', j.client_phone
      ) ELSE NULL END,
      'appointment_crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', ac2.id, 'employee_id', ac2.employee_id, 'role', ac2.role,
          'employees', jsonb_build_object(
            'id', e2.id, 'display_name', e2.display_name, 'full_name', e2.full_name,
            'color', e2.color, 'avatar_url', e2.avatar_url
          )
        ))
        FROM appointment_crew ac2 JOIN employees e2 ON e2.id = ac2.employee_id
        WHERE ac2.appointment_id = a.id
      ), '[]'::jsonb)
    ) as row_data
    FROM appointments a
    JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
    LEFT JOIN jobs j ON j.id = a.job_id
    WHERE a.date = today
      AND (p_include_cancelled OR a.status <> 'cancelled')
  ) sub;
  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: get_my_employee_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_employee_profile() RETURNS TABLE(id uuid, full_name text, display_name text, email text, role text, is_active boolean, is_external boolean, default_division text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_binding_count integer;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: authenticated employee required'
      USING errcode = '42501';
  END IF;

  SELECT count(*)
    INTO v_binding_count
  FROM public.employees employee
  WHERE employee.auth_user_id = v_actor_id
    AND employee.is_active;

  IF v_binding_count > 1 THEN
    RAISE EXCEPTION 'IDENTITY_CONFLICT: multiple active employee bindings'
      USING errcode = '21000';
  END IF;

  IF v_binding_count = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    employee.id,
    employee.full_name,
    employee.display_name,
    employee.email,
    employee.role::text,
    employee.is_active,
    employee.is_external,
    employee.default_division
  FROM public.employees employee
  WHERE employee.auth_user_id = v_actor_id
    AND employee.is_active;
END;
$$;


--
-- Name: get_my_notification_prefs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_notification_prefs(p_employee_id uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT COALESCE(
       (SELECT auth.jwt() ->> 'role' = 'service_role'),
       false
     )
     AND NOT public.is_current_native_push_preferences_employee(p_employee_id) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: own notification preferences only'
      USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT resolved_pref
  FROM public.get_effective_notification_prefs(p_employee_id) AS resolved_pref
  WHERE COALESCE((resolved_pref->>'type_enabled')::boolean, false);
END;
$$;


--
-- Name: get_my_push_subscriptions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_push_subscriptions(p_employee_id uuid) RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'id',            ps.id,
    'label',         ps.user_agent,
    'created_at',    ps.created_at,
    'endpoint_hash', substr(encode(extensions.digest(ps.endpoint, 'sha256'), 'hex'), 1, 16)
  )
  FROM public.push_subscriptions ps
  WHERE ps.employee_id = p_employee_id
  ORDER BY ps.created_at DESC;
$$;


--
-- Name: get_notification_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_defaults() RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH roles(role) AS (
    VALUES ('admin'), ('office'), ('project_manager'), ('supervisor'),
           ('field_tech'), ('crm_partner')
  ),
  channels(channel) AS (VALUES ('bell'), ('push'), ('email')),
  matrix AS (
    SELECT r.role, t.type_key, t.label, t.category, t.sort_order,
           t.enabled AS type_enabled, c.channel,
           CASE c.channel WHEN 'bell'  THEN t.bell_default
                          WHEN 'push'  THEN t.push_default
                          ELSE              t.email_default END AS type_channel_default
      FROM public.notification_types t
      CROSS JOIN roles r
      CROSS JOIN channels c
  )
  SELECT json_build_object(
    'role',                 m.role,
    'type_key',             m.type_key,
    'label',                m.label,
    'category',             m.category,
    'sort_order',           m.sort_order,
    'channel',              m.channel,
    'type_enabled',         m.type_enabled,
    'type_channel_default', m.type_channel_default,
    'enabled',             COALESCE(rd.enabled, m.type_channel_default),
    'user_customizable',   COALESCE(rd.user_customizable, true),
    'has_default',         (rd.id IS NOT NULL)
  )
  FROM matrix m
  LEFT JOIN public.notification_role_defaults rd
    ON rd.role = m.role AND rd.type_key = m.type_key AND rd.channel = m.channel
  ORDER BY m.sort_order, m.type_key, m.role, m.channel;
$$;


--
-- Name: get_notifications(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notifications(p_limit integer DEFAULT 30, p_employee_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.notifications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  IF v_is_service_role THEN
    RETURN QUERY
    SELECT notification.*
    FROM public.notifications notification
    WHERE notification.recipient_id IS NULL
       OR notification.recipient_id = p_employee_id
    ORDER BY notification.created_at DESC
    LIMIT greatest(1, least(p_limit, 100));
    RETURN;
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active = true
    AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  IF p_employee_id IS NOT NULL AND p_employee_id <> v_actor THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    notification.id,
    notification.type,
    notification.title,
    notification.body,
    notification.link,
    notification.entity_type,
    notification.entity_id,
    notification.job_id,
    notification.payload,
    CASE
      WHEN notification.recipient_id IS NULL
        THEN COALESCE(notification.read_at, receipt.read_at)
      ELSE notification.read_at
    END AS read_at,
    notification.created_at,
    notification.recipient_id,
    notification.type_key
  FROM public.notifications notification
  LEFT JOIN public.notification_reads receipt
    ON receipt.notification_id = notification.id
   AND receipt.employee_id = v_actor
   AND notification.recipient_id IS NULL
  WHERE notification.recipient_id IS NULL
     OR notification.recipient_id = p_employee_id
  ORDER BY notification.created_at DESC
  LIMIT greatest(1, least(p_limit, 100));
END;
$$;


--
-- Name: oop_quotes; Type: TABLE; Schema: public; Owner: -
