    xlgr_days integer DEFAULT 0,
    air_scrubber_count integer DEFAULT 0,
    air_scrubber_days integer DEFAULT 0,
    neg_air_count integer DEFAULT 0,
    neg_air_days integer DEFAULT 0,
    materials_actual_cost numeric(10,2) DEFAULT 0,
    antimicrobial_sqft numeric(10,2) DEFAULT 0,
