--
-- Name: get_open_estimates_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_open_estimates_summary() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH e AS (
    SELECT public.dash_division_bucket(COALESCE(es.intended_division, j.division::text)) AS bucket,
           COALESCE(es.amount, 0) AS amt
    FROM estimates es
    LEFT JOIN jobs j ON j.id = es.job_id
    WHERE COALESCE(es.status, 'open') NOT IN ('approved','denied','rejected','cancelled','void','converted','paid')
  )
  SELECT jsonb_build_object(
    'total_count', COALESCE((SELECT count(*) FROM e), 0),
    'total_value', COALESCE((SELECT SUM(amt) FROM e), 0),
    'segments', COALESCE((SELECT jsonb_agg(jsonb_build_object('key', bucket, 'count', c, 'value', v))
                          FROM (SELECT bucket, count(*) c, SUM(amt) v FROM e GROUP BY bucket) s), '[]'::jsonb)
  );
$$;


--
-- Name: get_orphan_contacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_orphan_contacts() RETURNS TABLE(id uuid, name text, phone text, role text, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT c.id, c.name, c.phone, c.role, c.created_at
  FROM contacts c
  LEFT JOIN contact_jobs cj ON c.id = cj.contact_id
  WHERE cj.id IS NULL
  ORDER BY c.created_at DESC LIMIT 100;
$$;


--
-- Name: get_overdue_tasks(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overdue_tasks(p_assignee uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now()) RETURNS SETOF json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT json_build_object(
    'id', t.id, 'title', t.title, 'notes', t.notes, 'due_at', t.due_at,
    'remind_at', t.remind_at, 'status', t.status,
    'assignee_id', t.assignee_id, 'assignee_name', e.full_name,
    'contact_id', t.contact_id, 'contact_name', c.name, 'lead_id', t.lead_id,
    'created_at', t.created_at, 'updated_at', t.updated_at, 'completed_at', t.completed_at
  )
  FROM crm_tasks t
  LEFT JOIN employees e ON e.id = t.assignee_id
  LEFT JOIN contacts  c ON c.id = t.contact_id
  WHERE t.status = 'open'
    AND t.due_at IS NOT NULL
    AND (t.due_at AT TIME ZONE 'America/Denver')::date < (p_now AT TIME ZONE 'America/Denver')::date
    AND (p_org_id   IS NULL OR t.org_id      = p_org_id)
    AND (p_assignee IS NULL OR t.assignee_id = p_assignee)
  ORDER BY t.due_at ASC;
END;
$$;


--
-- Name: get_payments_ledger(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payments_ledger(p_limit integer DEFAULT 500) RETURNS TABLE(payment_id uuid, amount numeric, payment_date date, payment_method text, payer_type text, payer_name text, reference_number text, is_deductible boolean, created_at timestamp with time zone, source text, qbo_payment_id text, qbo_synced_at timestamp with time zone, qbo_sync_error text, invoice_id uuid, invoice_number text, qbo_doc_number text, job_id uuid, job_number text, division text, claim_id uuid, claim_number text, contact_id uuid, client_name text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    p.id, p.amount, p.payment_date, p.payment_method,
    p.payer_type, p.payer_name, p.reference_number,
    p.is_deductible, p.created_at, p.source,
    p.qbo_payment_id, p.qbo_synced_at, p.qbo_sync_error,
    p.invoice_id, i.invoice_number, i.qbo_doc_number,
    p.job_id, j.job_number, j.division,
    j.claim_id, cl.claim_number,
    p.contact_id, COALESCE(ct.name, jc.name) AS client_name
  FROM payments p
  LEFT JOIN invoices i  ON i.id  = p.invoice_id
  LEFT JOIN jobs     j  ON j.id  = p.job_id
  LEFT JOIN claims   cl ON cl.id = j.claim_id
  LEFT JOIN contacts ct ON ct.id = p.contact_id
  LEFT JOIN contacts jc ON jc.id = j.primary_contact_id
  ORDER BY p.payment_date DESC NULLS LAST, p.created_at DESC
  LIMIT GREATEST(1, LEAST(p_limit, 2000));
$$;


--
-- Name: get_payments_received(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payments_received(p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH pay AS (
    SELECT public.dash_division_bucket(j.division::text) AS bucket,
           COALESCE(p.amount, 0) - COALESCE(p.refunded_amount, 0) AS amt,
           p.payment_date AS d
    FROM payments p
    LEFT JOIN invoices i ON i.id = p.invoice_id
    LEFT JOIN jobs j ON j.id = COALESCE(p.job_id, i.job_id)
    WHERE p.payment_date IS NOT NULL
  ),
  cur  AS (SELECT bucket, SUM(amt) AS v FROM pay WHERE d BETWEEN p_start AND p_end AND bucket IS NOT NULL GROUP BY bucket),
  tot  AS (SELECT SUM(amt) AS v FROM pay WHERE d BETWEEN p_start AND p_end),
  prev AS (SELECT SUM(amt) AS v FROM pay WHERE d BETWEEN (p_start - ((p_end - p_start) + 1)) AND (p_start - 1))
  SELECT jsonb_build_object(
    'total',      COALESCE((SELECT v FROM tot), 0),
    'prev_total', COALESCE((SELECT v FROM prev), 0),
    'segments',   COALESCE((SELECT jsonb_agg(jsonb_build_object('key', bucket, 'value', v)) FROM cur), '[]'::jsonb)
  );
$$;


--
-- Name: mt_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mt_today() RETURNS date
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  SELECT (now() AT TIME ZONE 'America/Denver')::date;
$$;


--
-- Name: get_payroll_summary(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payroll_summary(p_start_date date DEFAULT (date_trunc('week'::text, (public.mt_today())::timestamp with time zone))::date, p_end_date date DEFAULT ((date_trunc('week'::text, (public.mt_today())::timestamp with time zone) + '6 days'::interval))::date) RETURNS TABLE(employee_id uuid, employee_name text, hourly_rate numeric, overtime_rate numeric, total_hours numeric, regular_hours numeric, overtime_hours numeric, regular_cost numeric, overtime_cost numeric, total_cost numeric, approved_hours numeric, pending_hours numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH weekly_hours AS (
    SELECT
      t.employee_id,
      date_trunc('week', t.work_date::timestamp) AS week_start,
      SUM(t.hours) AS week_hours
    FROM job_time_entries t
    WHERE t.work_date BETWEEN p_start_date AND p_end_date
    GROUP BY t.employee_id, date_trunc('week', t.work_date::timestamp)
  ),
  ot_by_employee AS (
    SELECT
      employee_id,
      SUM(GREATEST(week_hours - 40, 0)) AS total_ot_hours,
      SUM(LEAST(week_hours, 40)) AS total_reg_hours
    FROM weekly_hours
    GROUP BY employee_id
  )
  SELECT
    e.id AS employee_id,
    e.full_name AS employee_name,
    e.hourly_rate,
    COALESCE(e.overtime_rate, e.hourly_rate * 1.5) AS overtime_rate,
    SUM(t.hours) AS total_hours,
    COALESCE(ot.total_reg_hours, SUM(t.hours)) AS regular_hours,
    COALESCE(ot.total_ot_hours, 0) AS overtime_hours,
    ROUND(COALESCE(ot.total_reg_hours, SUM(t.hours)) * e.hourly_rate, 2) AS regular_cost,
    ROUND(COALESCE(ot.total_ot_hours, 0) * COALESCE(e.overtime_rate, e.hourly_rate * 1.5), 2) AS overtime_cost,
    ROUND(
      COALESCE(ot.total_reg_hours, SUM(t.hours)) * e.hourly_rate +
      COALESCE(ot.total_ot_hours, 0) * COALESCE(e.overtime_rate, e.hourly_rate * 1.5),
    2) AS total_cost,
    SUM(CASE WHEN t.approved THEN t.hours ELSE 0 END) AS approved_hours,
    SUM(CASE WHEN NOT COALESCE(t.approved, false) THEN t.hours ELSE 0 END) AS pending_hours
  FROM employees e
  JOIN job_time_entries t ON t.employee_id = e.id
  LEFT JOIN ot_by_employee ot ON ot.employee_id = e.id
  WHERE t.work_date BETWEEN p_start_date AND p_end_date
    AND e.is_active = true
  GROUP BY e.id, e.full_name, e.hourly_rate, e.overtime_rate, ot.total_reg_hours, ot.total_ot_hours
  ORDER BY e.full_name;
$$;


--
-- Name: get_pipeline_movement(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pipeline_movement(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_since timestamptz;
BEGIN
  v_org   := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_since := (SELECT MIN(moved_at) FROM lead_stage_history WHERE org_id = v_org);

  RETURN QUERY
  WITH moves AS (
    SELECT lsh.stage_id, lsh.from_stage_id
    FROM lead_stage_history lsh
    JOIN inbound_leads il ON il.id = lsh.lead_id
    WHERE lsh.org_id = v_org
      AND COALESCE(il.spam_flag, false) = false
      AND (p_start IS NULL OR public.mt_date(lsh.moved_at) >= p_start)
      AND (p_end   IS NULL OR public.mt_date(lsh.moved_at) <= p_end)
  ),
  in_c  AS (SELECT stage_id AS sid, COUNT(*) AS c FROM moves GROUP BY stage_id),
  out_c AS (SELECT from_stage_id AS sid, COUNT(*) AS c FROM moves WHERE from_stage_id IS NOT NULL GROUP BY from_stage_id)
  SELECT json_build_object(
    'stage_id',   ps.id,
    'stage_name', ps.name,
    'sort_order', ps.sort_order,
    'is_won',     ps.is_won,
    'is_lost',    ps.is_lost,
    'moved_in',   COALESCE(in_c.c, 0),
    'moved_out',  COALESCE(out_c.c, 0),
    'net',        COALESCE(in_c.c, 0) - COALESCE(out_c.c, 0),
    'data_since', v_since
  )
  FROM pipeline_stages ps
  LEFT JOIN in_c  ON in_c.sid  = ps.id
  LEFT JOIN out_c ON out_c.sid = ps.id
  WHERE ps.org_id = v_org
  ORDER BY ps.sort_order;
END;
$$;


--
-- Name: pipeline_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pipeline_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    color text DEFAULT '#6366f1'::text NOT NULL,
    is_won boolean DEFAULT false NOT NULL,
    is_lost boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    win_probability numeric,
    is_recoverable boolean DEFAULT false NOT NULL,
    CONSTRAINT pipeline_stages_win_probability_check CHECK (((win_probability IS NULL) OR ((win_probability >= (0)::numeric) AND (win_probability <= (1)::numeric))))
);


--
-- Name: COLUMN pipeline_stages.is_recoverable; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pipeline_stages.is_recoverable IS 'A terminal (is_won/is_lost) stage a lead may automatically LEAVE when new forward evidence arrives (AI-detected qualification/appointment, auto-advance triggers). Missed Calls = true; Won/Lost = false (human judgments stay sticky).';


--
-- Name: get_pipeline_stages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pipeline_stages(p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.pipeline_stages
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM pipeline_stages
  WHERE org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1))
  ORDER BY sort_order;
$$;


--
-- Name: get_pipeline_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pipeline_summary() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object('stages', jsonb_build_array(
    jsonb_build_object('label','New / FNOL','count',
      (SELECT count(*) FROM jobs WHERE phase = 'job_received' AND status IS DISTINCT FROM 'deleted')),
    jsonb_build_object('label','In production','count',
      (SELECT count(*) FROM jobs WHERE phase = 'reconstruction_in_progress' AND status IS DISTINCT FROM 'deleted')),
    jsonb_build_object('label','Invoiced','count',
      (SELECT count(DISTINCT job_id) FROM invoices WHERE qbo_invoice_id IS NOT NULL)),
    jsonb_build_object('label','Paid','count',
      (SELECT count(DISTINCT job_id) FROM invoices WHERE status = 'paid'))
  ));
$$;


--
-- Name: get_property_meld_melds(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_property_meld_melds(p_include_closed boolean DEFAULT false) RETURNS SETOF json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
    SELECT row_to_json(m)
    FROM property_meld_melds m
    WHERE p_include_closed OR m.state IN ('open', 'imported')
    ORDER BY m.is_emergency DESC, m.received_at DESC NULLS LAST;
END;
$$;


--
-- Name: get_purgeable_feedback_media(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_purgeable_feedback_media(p_days integer DEFAULT 90) RETURNS TABLE(id uuid, attachments jsonb, resolved_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  -- Clamp INSIDE the RPC: the purge endpoint that will call this runs
  -- unauthenticated (cron convention), so a caller-supplied p_days must never
  -- be able to shorten retention below 30 days.
  v_days int := GREATEST(COALESCE(p_days, 90), 30);
BEGIN
  RETURN QUERY
    SELECT f.id, f.attachments, f.resolved_at
    FROM tech_feedback f
    WHERE f.status IN ('resolved', 'dismissed')
      AND f.resolved_at IS NOT NULL
      AND f.resolved_at < now() - make_interval(days => v_days)
      AND f.attachments_purged_at IS NULL
      AND f.attachments <> '[]'::jsonb
    ORDER BY f.resolved_at ASC;
END;
$$;


--
-- Name: get_qbo_connection_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_qbo_connection_status() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c record;
begin
  select refresh_token, granted_scopes, company_name, environment
    into c
  from integration_credentials
  where provider = 'quickbooks'
  limit 1;

  return json_build_object(
    'connected',         (c.refresh_token is not null),
    'has_payment_scope', coalesce(c.granted_scopes ilike '%com.intuit.quickbooks.payment%', false),
    'company_name',      c.company_name,
    'environment',       coalesce(c.environment, 'production')
  );
end;
$$;


--
-- Name: get_qbo_sync_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_qbo_sync_stats() RETURNS TABLE(synced bigint, pending bigint, errored bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    COUNT(*) FILTER (WHERE qbo_customer_id IS NOT NULL),
    COUNT(*) FILTER (
      WHERE qbo_customer_id IS NULL
        AND role IN ('homeowner','property_manager','tenant')
        AND name IS NOT NULL AND btrim(name) <> ''
    ),
    COUNT(*) FILTER (WHERE qbo_sync_error IS NOT NULL AND qbo_customer_id IS NULL)
  FROM contacts;
$$;


--
-- Name: get_real_claims_created(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_real_claims_created(p_floor timestamp with time zone) RETURNS TABLE(created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.created_at
  FROM public.claims c
  WHERE c.created_at >= p_floor
    AND COALESCE(c.status,'') <> 'deleted'
    AND EXISTS (
      SELECT 1 FROM public.jobs j
      WHERE j.claim_id = c.id AND j.is_real_job = true AND COALESCE(j.status,'') <> 'deleted'
    )
  ORDER BY c.created_at DESC;
$$;


--
-- Name: get_real_job_evidence_mismatches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_real_job_evidence_mismatches() RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH ev AS (
    SELECT j.id                 AS job_id,
           j.job_number,
           j.is_real_job,
           j.real_job_source,
           j.real_job_marked_at,
           c.name               AS contact_name,
           EXISTS (SELECT 1 FROM invoices i
                    WHERE i.job_id = j.id
                      AND i.qbo_invoice_id IS NOT NULL)                    AS has_invoice,
           EXISTS (SELECT 1 FROM sign_requests sr
                    WHERE sr.job_id = j.id
                      AND sr.status = 'signed'
                      AND sr.doc_type IN ('work_auth','recon_agreement'))  AS has_work_auth,
           EXISTS (SELECT 1 FROM estimates e
                    WHERE e.job_id = j.id
                      AND lower(COALESCE(e.status, '')) IN
                          ('approved','accepted','converted','signed'))    AS has_estimate
    FROM jobs j
    LEFT JOIN contacts c ON c.id = j.primary_contact_id
    WHERE j.status IS DISTINCT FROM 'deleted'
  ),
  mismatches AS (
    SELECT 1                            AS grp,
           COALESCE(inv.invoiced_total, 0) AS sort_amt,
           json_build_object(
             'job_id',          ev.job_id,
             'job_number',      ev.job_number,
             'category',        'evidence_unflagged',
             'evidence',        array_to_json(
                                  ARRAY[]::text[]
                                  || CASE WHEN ev.has_work_auth THEN ARRAY['work_auth'] ELSE ARRAY[]::text[] END
                                  || CASE WHEN ev.has_invoice   THEN ARRAY['invoice']   ELSE ARRAY[]::text[] END
                                  || CASE WHEN ev.has_estimate  THEN ARRAY['estimate']  ELSE ARRAY[]::text[] END),
             'invoiced_total',  COALESCE(inv.invoiced_total, 0),
             'amount_paid',     COALESCE(inv.amount_paid, 0),
             'was_demoted',     (ev.real_job_marked_at IS NOT NULL),
             'real_job_source', ev.real_job_source,
             'contact_name',    ev.contact_name
           ) AS row_json
    FROM ev
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(COALESCE(i.adjusted_total, i.total, 0)), 0) AS invoiced_total,
             COALESCE(SUM(COALESCE(i.amount_paid, 0)), 0)             AS amount_paid
      FROM invoices i
      WHERE i.job_id = ev.job_id AND i.qbo_invoice_id IS NOT NULL
    ) inv ON true
    WHERE ev.is_real_job = false
      AND (ev.has_invoice OR ev.has_work_auth OR ev.has_estimate)

    UNION ALL

    SELECT 2       AS grp,
           0::numeric AS sort_amt,
           json_build_object(
             'job_id',             ev.job_id,
             'job_number',         ev.job_number,
             'category',           'flagged_no_evidence',
             'real_job_source',    ev.real_job_source,
             'real_job_marked_at', ev.real_job_marked_at,
             'contact_name',       ev.contact_name
           ) AS row_json
    FROM ev
    WHERE ev.is_real_job = true
      AND NOT (ev.has_invoice OR ev.has_work_auth OR ev.has_estimate)
  )
  SELECT m.row_json
  FROM mismatches m
  ORDER BY m.grp, m.sort_amt DESC;
END;
$$;


--
-- Name: get_referral_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_referral_sources() RETURNS TABLE(id uuid, name text, category text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT id, name, category
  FROM referral_sources
  WHERE is_active = true
  ORDER BY sort_order ASC, name ASC;
$$;


--
-- Name: get_revenue_by_division(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_by_division(p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH inv AS (
    SELECT public.dash_division_bucket(j.division::text) AS bucket,
           COALESCE(i.adjusted_total, i.total, 0) AS amt,
           i.invoice_date AS d
    FROM invoices i JOIN jobs j ON j.id = i.job_id
    WHERE i.qbo_invoice_id IS NOT NULL
  ),
  cur AS (SELECT bucket, SUM(amt) AS v FROM inv WHERE d BETWEEN p_start AND p_end GROUP BY bucket),
  prev AS (SELECT SUM(amt) AS v FROM inv WHERE d BETWEEN (p_start - ((p_end - p_start) + 1)) AND (p_start - 1))
  SELECT jsonb_build_object(
    'total', COALESCE((SELECT SUM(v) FROM cur), 0),
    'prev_total', COALESCE((SELECT v FROM prev), 0),
    'segments', COALESCE((SELECT jsonb_agg(jsonb_build_object('key', bucket, 'value', v)) FROM cur), '[]'::jsonb)
  );
$$;


--
-- Name: get_schedule_template(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_schedule_template(p_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', t.id, 'name', t.name, 'description', t.description,
    'division', t.division, 'is_active', t.is_active,
    'created_by', t.created_by, 'created_at', t.created_at,
    'phases', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', p.id, 'name', p.name, 'description', p.description,
        'appointment_type', p.appointment_type, 'day_offset', p.day_offset,
        'duration_days', p.duration_days, 'default_start_time', p.default_start_time,
        'default_end_time', p.default_end_time, 'is_milestone', p.is_milestone,
        'color', p.color, 'default_crew_count', p.default_crew_count,
        'display_order', p.display_order, 'notes', p.notes,
        'tasks', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', tk.id, 'title', tk.title, 'description', tk.description,
            'is_required', tk.is_required, 'display_order', tk.display_order
          ) ORDER BY tk.display_order)
          FROM template_tasks tk WHERE tk.template_phase_id = p.id
        ), '[]'::jsonb)
      ) ORDER BY p.display_order)
      FROM template_phases p WHERE p.template_id = t.id
    ), '[]'::jsonb),
    'dependencies', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', d.id, 'source_phase_id', d.source_phase_id,
        'target_phase_id', d.target_phase_id,
        'dependency_type', d.dependency_type, 'lag_days', d.lag_days
      ))
      FROM template_dependencies d WHERE d.template_id = t.id
    ), '[]'::jsonb)
  ) INTO result
  FROM schedule_templates t WHERE t.id = p_template_id;
  RETURN result;
END; $$;


--
-- Name: get_schedule_templates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_schedule_templates(p_division text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', t.id, 'name', t.name, 'description', t.description,
    'division', t.division, 'is_active', t.is_active, 'created_at', t.created_at,
    'phase_count', (SELECT count(*) FROM template_phases p WHERE p.template_id = t.id AND NOT p.is_milestone),
    'milestone_count', (SELECT count(*) FROM template_phases p WHERE p.template_id = t.id AND p.is_milestone),
    'task_count', (SELECT count(*) FROM template_tasks tk JOIN template_phases p ON tk.template_phase_id = p.id WHERE p.template_id = t.id)
  ) ORDER BY t.name), '[]'::jsonb) INTO result
  FROM schedule_templates t
  WHERE t.is_active = true AND (p_division IS NULL OR t.division = p_division);
  RETURN result;
END; $$;


--
-- Name: get_scheduled_queue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scheduled_queue(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, body text, send_at timestamp with time zone, status text, contact_name text, contact_phone text, template_name text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    sm.id, sm.body, sm.send_at, sm.status,
    COALESCE(c.name, cp.phone) AS contact_name,
    cp.phone AS contact_phone,
    mt.title AS template_name
  FROM scheduled_messages sm
  LEFT JOIN conversations conv ON sm.conversation_id = conv.id
  LEFT JOIN conversation_participants cp ON cp.conversation_id = conv.id AND cp.is_active = true
  LEFT JOIN contacts c ON cp.contact_id = c.id
  LEFT JOIN message_templates mt ON sm.template_id = mt.id
  ORDER BY sm.send_at ASC
  LIMIT p_limit;
$$;


--
-- Name: crm_segments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_segments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    filter jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: get_segments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_segments(p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.crm_segments
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM crm_segments
  WHERE org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1))
  ORDER BY lower(name);
$$;


--
-- Name: get_sequences(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sequences(p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'id', s.id,
    'name', s.name,
    'description', s.description,
    'status', s.status,
    'exit_on_reply', s.exit_on_reply,
    'exit_on_conversion', s.exit_on_conversion,
    'created_at', s.created_at,
    'updated_at', s.updated_at,
    'steps', COALESCE((
      SELECT json_agg(json_build_object(
        'id', st.id, 'step_order', st.step_order, 'channel', st.channel,
        'delay_hours', st.delay_hours, 'subject', st.subject, 'body', st.body,
        'template_id', st.template_id
      ) ORDER BY st.step_order)
      FROM crm_sequence_steps st WHERE st.sequence_id = s.id
    ), '[]'::json),
    'stats', (
      SELECT json_build_object(
        'active',    count(*) FILTER (WHERE e.status = 'active'),
        'paused',    count(*) FILTER (WHERE e.status = 'paused'),
        'completed', count(*) FILTER (WHERE e.status = 'completed'),
        'exited',    count(*) FILTER (WHERE e.status = 'exited'),
        'total',     count(*)
      )
      FROM crm_sequence_enrollments e WHERE e.sequence_id = s.id
    ),
    'enrollments', COALESCE((
      SELECT json_agg(en) FROM (
        SELECT e.id, e.contact_id, c.name AS contact_name, c.phone AS contact_phone,
               e.status, e.current_step, e.next_run_at, e.enrolled_at,
               e.completed_at, e.exit_reason
        FROM crm_sequence_enrollments e
        LEFT JOIN contacts c ON c.id = e.contact_id
        WHERE e.sequence_id = s.id
        ORDER BY e.enrolled_at DESC
        LIMIT 200
      ) en
    ), '[]'::json)
  )
  FROM crm_sequences s
  WHERE s.org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1))
  ORDER BY s.created_at DESC;
$$;


--
-- Name: get_service_sms_consent_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_service_sms_consent_status(p_contact_id uuid, p_destination_phone text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_contact public.contacts%ROWTYPE;
  v_service_consent public.service_sms_consents%ROWTYPE;
  v_work_auth_consent public.work_authorization_sms_consents%ROWTYPE;
  v_phone_digits text;
  v_phone_key text;
  v_locked_phone_digits text;
  v_locked_phone_key text;
  v_destination_digits text;
  v_destination_key text;
BEGIN
  IF current_user <> 'service_role' THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'CONSENT_STATUS_NOT_AUTHORIZED'
    );
  END IF;

  IF p_contact_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'CONTACT_NOT_FOUND');
  END IF;

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id;

  IF v_contact.id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'CONTACT_NOT_FOUND');
  END IF;

  v_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_phone_digits) = 10 THEN
    v_phone_key := v_phone_digits;
  ELSIF length(v_phone_digits) = 11 AND left(v_phone_digits, 1) = '1' THEN
    v_phone_key := right(v_phone_digits, 10);
  ELSE
    RETURN jsonb_build_object('allowed', false, 'code', 'CONTACT_HAS_NO_PHONE');
  END IF;

  v_destination_digits := regexp_replace(
    COALESCE(p_destination_phone, v_contact.phone, ''),
    '[^0-9]',
    '',
    'g'
  );
  IF length(v_destination_digits) = 10 THEN
    v_destination_key := v_destination_digits;
  ELSIF length(v_destination_digits) = 11 AND left(v_destination_digits, 1) = '1' THEN
    v_destination_key := right(v_destination_digits, 10);
  END IF;

  IF v_destination_key IS NULL OR v_destination_key <> v_phone_key THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'CONTACT_PHONE_MISMATCH',
      'contact_id', v_contact.id
    );
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('messaging-phone:' || v_phone_key, 0));

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id
  FOR SHARE;

  v_locked_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_locked_phone_digits) = 10 THEN
    v_locked_phone_key := v_locked_phone_digits;
  ELSIF length(v_locked_phone_digits) = 11 AND left(v_locked_phone_digits, 1) = '1' THEN
    v_locked_phone_key := right(v_locked_phone_digits, 10);
  END IF;

  IF v_contact.id IS NULL
     OR v_locked_phone_key IS NULL
     OR v_locked_phone_key <> v_phone_key THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'CONTACT_PHONE_CHANGED',
      'contact_id', p_contact_id
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.dnd IS TRUE
  ) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'DND_ACTIVE',
      'contact_id', v_contact.id
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.opt_out_at IS NOT NULL
  ) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'NO_CONSENT',
      'contact_id', v_contact.id,
      'source', 'explicit_opt_out'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.message_provider_events e
    WHERE e.direction = 'inbound'
      AND e.message_type IN ('sms', 'mms')
      AND e.processing_state IN ('received', 'claimed', 'retryable', 'failed')
      AND right(regexp_replace(COALESCE(e.sender_address, ''), '[^0-9]', '', 'g'), 10)
        = v_phone_key
      AND regexp_replace(lower(trim(COALESCE(e.content, ''))), '[^a-z0-9]', '', 'g')
        = ANY (ARRAY['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'])
      AND NOT EXISTS (
        SELECT 1
        FROM public.message_provider_events later_event
        WHERE later_event.direction = 'inbound'
          AND later_event.message_type IN ('sms', 'mms')
          AND later_event.processing_state = 'processed'
          AND right(
            regexp_replace(COALESCE(later_event.sender_address, ''), '[^0-9]', '', 'g'),
            10
          ) = v_phone_key
          AND later_event.occurred_at > e.occurred_at
          AND regexp_replace(
            lower(trim(COALESCE(later_event.content, ''))),
            '[^a-z0-9]',
            '',
            'g'
          ) = ANY (ARRAY['start', 'unstop', 'subscribe', 'yes'])
      )
  ) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'NO_CONSENT',
      'contact_id', v_contact.id,
      'source', 'pending_stop'
    );
  END IF;

  IF v_contact.opt_in_status IS TRUE THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'code', 'GLOBAL_OPT_IN',
      'contact_id', v_contact.id,
      'consent_source', v_contact.opt_in_source
    );
  END IF;

  SELECT *
  INTO v_service_consent
  FROM public.service_sms_consents s
  WHERE s.contact_id = v_contact.id
    AND s.consent_scope = 'service_related_customer_project_messages'
    AND s.attestation_version = 'prior_sms_consent_v1';

  IF v_service_consent.contact_id IS NOT NULL
     AND right(
       regexp_replace(COALESCE(v_service_consent.phone, ''), '[^0-9]', '', 'g'),
       10
     ) = v_phone_key THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'code', 'SERVICE_CONSENT',
      'contact_id', v_contact.id,
      'consent_scope', v_service_consent.consent_scope,
      'attested_at', v_service_consent.attested_at
    );
  END IF;

  SELECT *
  INTO v_work_auth_consent
  FROM public.work_authorization_sms_consents w
  WHERE w.contact_id = v_contact.id
    AND w.consent_scope = 'service_related_customer_project_messages'
    AND w.disclosure_version = 'upr_work_auth_sms_v1'
    AND right(
      regexp_replace(COALESCE(w.phone, ''), '[^0-9]', '', 'g'),
      10
    ) = v_phone_key
  ORDER BY w.signed_at DESC
  LIMIT 1;

  IF v_work_auth_consent.sign_request_id IS NULL THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'NO_CONSENT',
      'contact_id', v_contact.id
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'code', 'SERVICE_CONSENT',
    'contact_id', v_contact.id,
    'consent_scope', v_work_auth_consent.consent_scope,
    'attested_at', v_work_auth_consent.signed_at
  );
END;
$$;


--
-- Name: get_sign_document_templates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sign_document_templates(p_token text) RETURNS SETOF public.document_templates
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT dt.*
  FROM public.document_templates dt
  WHERE dt.doc_type = (
    SELECT sr.doc_type
    FROM public.sign_requests sr
    WHERE sr.token = p_token::uuid
    LIMIT 1
  )
  ORDER BY dt.sort_order ASC NULLS LAST;
$$;


--
-- Name: get_sign_request_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sign_request_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id',               sr.id,
    'token',            sr.token,
    'doc_type',         sr.doc_type,
    'divisions',        sr.divisions,
    'status',           sr.status,
    'expires_at',       sr.expires_at,
    'signer_name',      sr.signer_name,
    'signer_email',     sr.signer_email,
    'signed_at',        sr.signed_at,
    'signed_file_path', sr.signed_file_path,
    'job', jsonb_build_object(
      'id',                j.id,
      'job_number',        j.job_number,
      'insured_name',      j.insured_name,
      'address',           j.address,
      'city',              j.city,
      'state',             j.state,
      'zip',               j.zip,
      'date_of_loss',      j.date_of_loss,
      'division',          j.division,
      'insurance_company', j.insurance_company,
      'claim_number',      j.claim_number,
      'policy_number',     j.policy_number,
      'adjuster_name',     j.adjuster_name
    )
  )
  INTO v_result
  FROM sign_requests sr
  JOIN jobs j ON j.id = sr.job_id
  WHERE sr.token = p_token::uuid;  -- explicit cast: text → uuid

  RETURN v_result;
END;
$$;


--
-- Name: get_speed_to_lead(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_speed_to_lead(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_org_id uuid DEFAULT NULL::uuid) RETURNS SETOF json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_since timestamptz;
BEGIN
  v_org   := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_since := (SELECT MIN(moved_at) FROM lead_stage_history WHERE org_id = v_org);

  RETURN QUERY
  WITH first_move AS (
    SELECT lsh.lead_id, MIN(lsh.moved_at) AS first_moved_at
    FROM lead_stage_history lsh
    WHERE lsh.org_id = v_org
      AND lsh.moved_by IS NOT NULL
    GROUP BY lsh.lead_id
  ),
  gaps AS (
    SELECT EXTRACT(EPOCH FROM (fm.first_moved_at - COALESCE(il.occurred_at, il.created_at))) / 60.0 AS mins
    FROM first_move fm
    JOIN inbound_leads il ON il.id = fm.lead_id
    WHERE COALESCE(il.spam_flag, false) = false
      AND (p_start IS NULL OR public.mt_date(fm.first_moved_at) >= p_start)
      AND (p_end   IS NULL OR public.mt_date(fm.first_moved_at) <= p_end)
  ),
  binned AS (
    SELECT CASE
      WHEN GREATEST(mins, 0) <= 5 THEN 1
      WHEN mins <= 30            THEN 2
      WHEN mins <= 60            THEN 3
      WHEN mins <= 240           THEN 4
      WHEN mins <= 1440          THEN 5
      ELSE 6
    END AS b
    FROM gaps
  ),
  counts AS (SELECT b, COUNT(*) AS c FROM binned GROUP BY b),
  defs(sort_order, label, within_sla) AS (
    VALUES (1, '≤5 min', true), (2, '5–30 min', false), (3, '30–60 min', false),
           (4, '1–4 hr', false), (5, '4–24 hr', false), (6, '>24 hr', false)
  )
  SELECT json_build_object(
    'bucket',     defs.label,
    'sort_order', defs.sort_order,
    'within_sla', defs.within_sla,
    'count',      COALESCE(counts.c, 0),
    'data_since', v_since
  )
  FROM defs
  LEFT JOIN counts ON counts.b = defs.sort_order
  ORDER BY defs.sort_order;
END;
$$;


--
-- Name: get_stalled_materials(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stalled_materials(p_job_id uuid) RETURNS TABLE(room_id uuid, room_name text, material public.material_type, latest_mc numeric, latest_reading_at timestamp with time zone, mc_36h_ago numeric, drying_goal_pct numeric, days_stalled integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH latest_per_pair AS (
    SELECT DISTINCT ON (mr.room_id, mr.material)
           mr.id, mr.room_id, mr.material,
           mr.mc_pct AS latest_mc, mr.drying_goal_pct AS latest_goal,
           mr.taken_at AS latest_taken_at
      FROM moisture_readings mr
     WHERE mr.job_id = p_job_id
     ORDER BY mr.room_id, mr.material, mr.taken_at DESC
  ),
  prior_per_pair AS (
    SELECT lpp.id AS latest_id,
           (SELECT prior.mc_pct FROM moisture_readings prior
             WHERE prior.job_id = p_job_id
               AND prior.room_id IS NOT DISTINCT FROM lpp.room_id
               AND prior.material = lpp.material
               AND prior.id <> lpp.id
               AND prior.taken_at <= lpp.latest_taken_at - interval '36 hours'
               AND prior.mc_pct IS NOT NULL
             ORDER BY prior.taken_at DESC LIMIT 1) AS prior_mc,
           (SELECT prior.taken_at FROM moisture_readings prior
             WHERE prior.job_id = p_job_id
               AND prior.room_id IS NOT DISTINCT FROM lpp.room_id
               AND prior.material = lpp.material
               AND prior.id <> lpp.id
               AND prior.taken_at <= lpp.latest_taken_at - interval '36 hours'
               AND prior.mc_pct IS NOT NULL
             ORDER BY prior.taken_at DESC LIMIT 1) AS prior_taken_at
      FROM latest_per_pair lpp
  )
  SELECT lpp.room_id, r.name AS room_name, lpp.material,
         lpp.latest_mc, lpp.latest_taken_at AS latest_reading_at,
         ppp.prior_mc AS mc_36h_ago, lpp.latest_goal AS drying_goal_pct,
         EXTRACT(DAY FROM (lpp.latest_taken_at - ppp.prior_taken_at))::INT AS days_stalled
    FROM latest_per_pair lpp
    LEFT JOIN rooms r ON r.id = lpp.room_id
    LEFT JOIN prior_per_pair ppp ON ppp.latest_id = lpp.id
   WHERE lpp.latest_mc IS NOT NULL
     AND lpp.latest_goal IS NOT NULL
     AND lpp.latest_mc > lpp.latest_goal
     AND ppp.prior_mc IS NOT NULL
     AND (ppp.prior_mc - lpp.latest_mc) < 1.0
   ORDER BY lpp.latest_taken_at DESC;
END;
$$;


--
-- Name: get_stalled_materials_for_employee(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stalled_materials_for_employee(p_employee_id uuid) RETURNS TABLE(job_id uuid, job_number text, appointment_id uuid, appointment_date date, room_id uuid, room_name text, material public.material_type, latest_mc numeric, latest_reading_at timestamp with time zone, mc_36h_ago numeric, drying_goal_pct numeric, days_stalled integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH emp_jobs AS (
    SELECT DISTINCT a.job_id,
                    (array_agg(a.id ORDER BY a.date DESC))[1] AS latest_appt_id,
                    max(a.date) AS latest_appt_date
      FROM appointments a
      JOIN appointment_crew ac ON ac.appointment_id = a.id
     WHERE ac.employee_id = p_employee_id
       AND a.job_id IS NOT NULL
       AND a.date >= (public.mt_today() - interval '30 days')
     GROUP BY a.job_id
  )
  SELECT
    ej.job_id,
    j.job_number,
    ej.latest_appt_id AS appointment_id,
    ej.latest_appt_date AS appointment_date,
    sm.room_id,
    sm.room_name,
    sm.material,
    sm.latest_mc,
    sm.latest_reading_at,
    sm.mc_36h_ago,
    sm.drying_goal_pct,
    sm.days_stalled
  FROM emp_jobs ej
  JOIN jobs j ON j.id = ej.job_id
  CROSS JOIN LATERAL get_stalled_materials(ej.job_id) AS sm
  ORDER BY sm.latest_reading_at DESC;
END;
$$;


--
-- Name: get_table_stats(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_table_stats(p_table text) RETURNS TABLE(row_count bigint, latest_created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY EXECUTE format(
    'SELECT COUNT(*)::BIGINT, MAX(created_at) FROM %I', p_table
  );
END;
$$;


--
-- Name: get_tasks_for_appointment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tasks_for_appointment(p_appointment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', jt.id,
      'title', jt.title,
      'description', jt.description,
      'phase_name', jt.phase_name,
      'phase_color', jt.phase_color,
      'is_required', jt.is_required,
      'is_completed', jt.is_completed,
      'completed_by', jt.completed_by,
      'completed_at', jt.completed_at,
      'completed_by_name', e.display_name,
      'display_order', jt.display_order
    ) ORDER BY jt.phase_name, jt.display_order
  ), '[]'::jsonb) INTO result
  FROM job_tasks jt
  LEFT JOIN employees e ON e.id = jt.completed_by
  WHERE jt.appointment_id = p_appointment_id;

  RETURN result;
END;
$$;


--
-- Name: get_tech_claims(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tech_claims(p_employee_id uuid) RETURNS TABLE(id uuid, claim_number text, insurance_claim_number text, insurance_carrier text, policy_number text, date_of_loss date, loss_type text, loss_city text, loss_state text, loss_address text, status text, deductible numeric, created_at timestamp with time zone, last_activity_at timestamp with time zone, insured_name text, client_phone text, job_count bigint, primary_division text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    c.id, c.claim_number, c.insurance_claim_number, c.insurance_carrier,
    c.policy_number, c.date_of_loss, c.loss_type, c.loss_city, c.loss_state,
    c.loss_address, c.status, c.deductible, c.created_at,
    GREATEST(
      (SELECT MAX(a2.updated_at) FROM appointments a2 JOIN jobs jj ON jj.id = a2.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) AS last_activity_at,
    ct.name  AS insured_name,
    ct.phone AS client_phone,
    COUNT(DISTINCT j.id) AS job_count,
    (SELECT j2.division FROM jobs j2 WHERE j2.claim_id = c.id ORDER BY j2.created_at ASC LIMIT 1) AS primary_division
  FROM claims c
  JOIN jobs j ON j.claim_id = c.id
  JOIN appointments a ON a.job_id = j.id
  JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
  LEFT JOIN contacts ct ON ct.id = c.contact_id
  WHERE c.status IS DISTINCT FROM 'deleted'
  GROUP BY c.id, ct.name, ct.phone
  ORDER BY
    GREATEST(
      (SELECT MAX(a2.updated_at) FROM appointments a2 JOIN jobs jj ON jj.id = a2.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) DESC NULLS LAST,
    c.created_at DESC;
$$;


--
-- Name: get_tech_conversations(integer, timestamp with time zone, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tech_conversations(p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_conversation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_limit  int  := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_search text := NULLIF(btrim(COALESCE(p_search, '')), '');
  v_like   text;
  v_convs  jsonb;
  v_unread int;
  v_counts jsonb;
BEGIN
  IF v_search IS NOT NULL THEN
    v_like := '%' || replace(replace(replace(v_search, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  WITH base AS (
    SELECT c.*, COALESCE(c.last_message_at, c.created_at) AS sort_key
    FROM public.conversations c
  ),
  matched AS (
    SELECT b.* FROM base b
    WHERE
      (p_conversation_id IS NOT NULL AND b.id = p_conversation_id)
      OR (
        p_conversation_id IS NULL
        AND (
          p_status IS NULL OR p_status = 'all'
          OR (p_status = 'unread' AND b.unread_count > 0)
          OR (p_status NOT IN ('all', 'unread') AND b.status = p_status)
        )
        AND (
          v_like IS NULL
          OR b.title ILIKE v_like
          OR b.last_message_preview ILIKE v_like
          OR EXISTS (
            SELECT 1
            FROM public.conversation_participants cp
            LEFT JOIN public.contacts ct ON ct.id = cp.contact_id
            WHERE cp.conversation_id = b.id
              AND (cp.phone ILIKE v_like OR ct.name ILIKE v_like OR ct.phone ILIKE v_like)
          )
        )
        AND (
          p_before IS NULL
          OR b.sort_key < p_before
          OR (b.sort_key = p_before AND b.id < p_before_id)
        )
      )
  ),
  paged AS (
    SELECT * FROM matched
    ORDER BY sort_key DESC, id DESC
    LIMIT v_limit
  ),
  page_rows AS (
    SELECT
      p.sort_key,
      p.id,
      (to_jsonb(p) - 'email_reply_token') || jsonb_build_object(
        'conversation_participants',
        COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'contact_id', cp.contact_id,
              'phone',      cp.phone,
              'role',       cp.role,
              'contacts',   CASE WHEN ct.id IS NULL THEN NULL ELSE jsonb_build_object(
                'id', ct.id, 'name', ct.name, 'phone', ct.phone, 'email', ct.email,
                'company', ct.company, 'role', ct.role, 'dnd', ct.dnd, 'dnd_at', ct.dnd_at
              ) END
            )
            ORDER BY cp.added_at
          )
          FROM public.conversation_participants cp
          LEFT JOIN public.contacts ct ON ct.id = cp.contact_id
          WHERE cp.conversation_id = p.id
        ), '[]'::jsonb)
      ) AS row_json
    FROM paged p
  )
  SELECT COALESCE(jsonb_agg(row_json ORDER BY sort_key DESC, id DESC), '[]'::jsonb)
    INTO v_convs
  FROM page_rows;

  SELECT COALESCE(SUM(unread_count), 0)::int INTO v_unread FROM public.conversations;

  WITH scope AS (
    SELECT c.* FROM public.conversations c
    WHERE
      v_like IS NULL
      OR c.title ILIKE v_like
      OR c.last_message_preview ILIKE v_like
      OR EXISTS (
        SELECT 1
        FROM public.conversation_participants cp
        LEFT JOIN public.contacts ct ON ct.id = cp.contact_id
        WHERE cp.conversation_id = c.id
          AND (cp.phone ILIKE v_like OR ct.name ILIKE v_like OR ct.phone ILIKE v_like)
      )
  )
  SELECT jsonb_build_object(
    'all',               count(*),
    'unread',            count(*) FILTER (WHERE unread_count > 0),
    'needs_response',    count(*) FILTER (WHERE status = 'needs_response'),
    'waiting_on_client', count(*) FILTER (WHERE status = 'waiting_on_client'),
    'resolved',          count(*) FILTER (WHERE status = 'resolved')
  ) INTO v_counts
  FROM scope;

  RETURN jsonb_build_object(
    'conversations', COALESCE(v_convs, '[]'::jsonb),
    'unread_total',  COALESCE(v_unread, 0),
    'status_counts', v_counts
  );
END;
$$;


--
-- Name: get_tech_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tech_dashboard(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_now         timestamptz := now();
  v_today       date := (v_now AT TIME ZONE 'America/Denver')::date;
  v_week_start  date := (date_trunc('week', ((v_now AT TIME ZONE 'America/Denver')::date)::timestamp))::date;
  v_today_appts jsonb;
  v_upcoming    jsonb;
  v_open        job_time_entries%ROWTYPE;
  v_open_json   jsonb;
  v_photos      integer;
  v_hours_today jsonb;
  v_hours_week  jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'time_start')), '[]'::jsonb)
  INTO v_today_appts
  FROM (
    SELECT jsonb_build_object(
      'id', a.id, 'job_id', a.job_id, 'title', a.title, 'date', a.date,
      'time_start', a.time_start, 'time_end', a.time_end, 'type', a.type,
      'status', a.status, 'notes', a.notes,
      'color', a.color, 'kind', a.kind, 'duration_days', a.duration_days, 'is_milestone', a.is_milestone,
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true),
      'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
        'id', j.id, 'job_number', j.job_number, 'insured_name', j.insured_name, 'address', j.address,
        'city', j.city, 'division', j.division, 'phase', j.phase, 'client_phone', j.client_phone
      ) ELSE NULL END,
      'appointment_crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', ac2.id, 'employee_id', ac2.employee_id, 'role', ac2.role,
          'employees', jsonb_build_object('id', e2.id, 'display_name', e2.display_name, 'full_name', e2.full_name, 'color', e2.color, 'avatar_url', e2.avatar_url)
        ))
        FROM appointment_crew ac2 JOIN employees e2 ON e2.id = ac2.employee_id
        WHERE ac2.appointment_id = a.id
      ), '[]'::jsonb)
    ) AS row_data
    FROM appointments a
    JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
    LEFT JOIN jobs j ON j.id = a.job_id
    WHERE a.date = v_today AND a.status <> 'cancelled'
  ) sub;

  SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'date'), (row_data->>'time_start')), '[]'::jsonb)
  INTO v_upcoming
  FROM (
    SELECT jsonb_build_object(
      'id', a.id, 'job_id', a.job_id, 'title', a.title, 'date', a.date,
      'time_start', a.time_start, 'time_end', a.time_end, 'type', a.type,
      'status', a.status, 'notes', a.notes,
      'color', a.color, 'kind', a.kind, 'duration_days', a.duration_days, 'is_milestone', a.is_milestone,
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true),
      'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
        'id', j.id, 'job_number', j.job_number, 'insured_name', j.insured_name, 'address', j.address,
        'city', j.city, 'division', j.division, 'phase', j.phase, 'client_phone', j.client_phone
      ) ELSE NULL END,
      'appointment_crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', ac2.id, 'employee_id', ac2.employee_id, 'role', ac2.role,
          'employees', jsonb_build_object('id', e2.id, 'display_name', e2.display_name, 'full_name', e2.full_name, 'color', e2.color, 'avatar_url', e2.avatar_url)
        ))
        FROM appointment_crew ac2 JOIN employees e2 ON e2.id = ac2.employee_id
        WHERE ac2.appointment_id = a.id
      ), '[]'::jsonb)
    ) AS row_data
    FROM appointments a
    JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
    LEFT JOIN jobs j ON j.id = a.job_id
    WHERE a.date > v_today AND a.date <= v_today + 7 AND a.status <> 'cancelled'
  ) sub;

  SELECT * INTO v_open FROM job_time_entries
  WHERE employee_id = p_employee_id AND clock_out IS NULL
  ORDER BY created_at DESC LIMIT 1;
  v_open_json := CASE WHEN v_open.id IS NOT NULL THEN to_jsonb(v_open) ELSE NULL END;

  SELECT COUNT(*) INTO v_photos FROM job_documents d
  WHERE d.uploaded_by = p_employee_id AND d.category = 'photo'
    AND (d.created_at AT TIME ZONE 'America/Denver')::date = v_today;

  v_hours_today := tech_hours_bucket(p_employee_id, v_today, v_today, v_now, v_open);
  v_hours_week  := tech_hours_bucket(p_employee_id, v_week_start, v_today, v_now, v_open);

  RETURN jsonb_build_object(
    'server_now', v_now, 'today', v_today, 'week_start', v_week_start,
    'appointments', COALESCE(v_today_appts, '[]'::jsonb),
    'upcoming', COALESCE(v_upcoming, '[]'::jsonb),
    'open_entry', v_open_json,
    'hours_today', v_hours_today, 'hours_week', v_hours_week,
    'photos_today', COALESCE(v_photos, 0)
  );
END;
$$;


--
-- Name: get_tech_feedback(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tech_feedback() RETURNS TABLE(id uuid, employee_id uuid, employee_name text, type text, title text, description text, screenshots jsonb, status text, admin_notes text, created_at timestamp with time zone, attachments jsonb, source text, resolved_at timestamp with time zone, attachments_purged_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- New columns are appended: the live AdminFeedback.jsx caller reads JSON
  -- objects by key and simply ignores the extra keys.
  RETURN QUERY
    SELECT
      f.id, f.employee_id,
      e.full_name AS employee_name,
      f.type, f.title, f.description,
      f.screenshots, f.status, f.admin_notes,
      f.created_at,
      f.attachments, f.source, f.resolved_at, f.attachments_purged_at
    FROM tech_feedback f
    JOIN employees e ON e.id = f.employee_id
    ORDER BY f.created_at DESC;
END;
$$;


--
-- Name: get_tech_status_board(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tech_status_board() RETURNS TABLE(employee_id uuid, full_name text, default_division text, status text, status_since timestamp with time zone, entry_id uuid, appointment_id uuid, appointment_title text, job_id uuid, job_number text, client_name text, address text, division text, next_appt_time timestamp with time zone, next_appt_title text, travel_start timestamp with time zone, clock_in timestamp with time zone, paused_at timestamp with time zone, total_paused_minutes numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH open_entry AS (
    SELECT DISTINCT ON (jte.employee_id)
      jte.employee_id, jte.id AS entry_id, jte.appointment_id, jte.job_id,
      jte.travel_start, jte.clock_in, jte.paused_at, jte.total_paused_minutes
    FROM job_time_entries jte
    WHERE jte.clock_out IS NULL
      AND (jte.travel_start IS NOT NULL OR jte.clock_in IS NOT NULL)
    ORDER BY jte.employee_id, jte.created_at DESC
  ),
  today_appt AS (
    SELECT DISTINCT ON (ac.employee_id)
      ac.employee_id,
      a.id          AS appointment_id,
      a.title       AS appointment_title,
      a.job_id,
      ((a.date + a.time_start) AT TIME ZONE 'America/Denver') AS appt_ts
    FROM appointment_crew ac
    JOIN appointments a ON a.id = ac.appointment_id
    WHERE a.date = (NOW() AT TIME ZONE 'America/Denver')::date
    ORDER BY ac.employee_id,
      (((a.date + a.time_start) AT TIME ZONE 'America/Denver') >= NOW()) DESC,
      ((a.date + a.time_start) AT TIME ZONE 'America/Denver') ASC
  )
  SELECT
    e.id                                        AS employee_id,
    e.full_name,
    e.default_division,
    CASE
      WHEN oe.paused_at IS NOT NULL                THEN 'paused'
      WHEN oe.clock_in IS NOT NULL                 THEN 'on_site'
      WHEN oe.travel_start IS NOT NULL             THEN 'omw'
      WHEN ta.appointment_id IS NOT NULL           THEN 'scheduled'
      ELSE 'idle'
    END                                         AS status,
    CASE
      WHEN oe.paused_at IS NOT NULL    THEN oe.paused_at
      WHEN oe.clock_in IS NOT NULL     THEN oe.clock_in
      WHEN oe.travel_start IS NOT NULL THEN oe.travel_start
      ELSE NULL
    END                                         AS status_since,
    oe.entry_id,
    COALESCE(oe.appointment_id, ta.appointment_id)  AS appointment_id,
    COALESCE(a_open.title, ta.appointment_title)    AS appointment_title,
    COALESCE(oe.job_id, ta.job_id)                  AS job_id,
    j.job_number,
    j.insured_name                              AS client_name,
    NULLIF(CONCAT_WS(', ',
      NULLIF(j.address, ''),
      NULLIF(j.city, ''),
      NULLIF(j.state, '') || CASE WHEN j.zip IS NOT NULL AND j.zip <> '' THEN ' ' || j.zip ELSE '' END
    ), '')                                      AS address,
    j.division,
    CASE WHEN oe.entry_id IS NULL AND ta.appt_ts >= NOW() THEN ta.appt_ts ELSE NULL END AS next_appt_time,
    CASE WHEN oe.entry_id IS NULL AND ta.appt_ts >= NOW() THEN ta.appointment_title ELSE NULL END AS next_appt_title,
    oe.travel_start,
    oe.clock_in,
    oe.paused_at,
    oe.total_paused_minutes
  FROM employees e
  LEFT JOIN open_entry oe       ON oe.employee_id = e.id
  LEFT JOIN today_appt ta       ON ta.employee_id = e.id
  LEFT JOIN appointments a_open ON a_open.id = oe.appointment_id
  LEFT JOIN jobs j              ON j.id = COALESCE(oe.job_id, ta.job_id)
  WHERE e.is_active = TRUE
    AND (e.role IN ('field_tech', 'supervisor')
         OR e.show_on_status_board
         OR oe.entry_id IS NOT NULL
         OR ta.appointment_id IS NOT NULL)
  ORDER BY
    CASE
      WHEN oe.paused_at IS NOT NULL    THEN 1
      WHEN oe.clock_in IS NOT NULL     THEN 2
      WHEN oe.travel_start IS NOT NULL THEN 3
      WHEN ta.appointment_id IS NOT NULL THEN 4
      ELSE 5
    END,
    e.full_name;
$$;


--
-- Name: get_timesheet_entries(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_timesheet_entries(p_start_date date DEFAULT (date_trunc('week'::text, (public.mt_today())::timestamp with time zone))::date, p_end_date date DEFAULT ((date_trunc('week'::text, (public.mt_today())::timestamp with time zone) + '6 days'::interval))::date, p_employee_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, job_id uuid, employee_id uuid, employee_name text, job_number text, insured_name text, division text, work_date date, hours numeric, hourly_rate numeric, total_cost numeric, work_type text, description text, approved boolean, approved_by uuid, clock_in timestamp with time zone, clock_out timestamp with time zone, appointment_id uuid, notes text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    t.id,
    t.job_id,
    t.employee_id,
    e.full_name AS employee_name,
    j.job_number,
    j.insured_name,
    j.division,
    t.work_date,
    t.hours,
    t.hourly_rate,
    t.total_cost,
    t.work_type,
    t.description,
    t.approved,
    t.approved_by,
    t.clock_in,
    t.clock_out,
    t.appointment_id,
    t.notes,
    t.created_at
  FROM job_time_entries t
  JOIN employees e ON e.id = t.employee_id
  JOIN jobs j ON j.id = t.job_id
  WHERE t.work_date BETWEEN p_start_date AND p_end_date
    AND (p_employee_id IS NULL OR t.employee_id = p_employee_id)
  ORDER BY t.work_date DESC, e.full_name, t.clock_in;
$$;


--
-- Name: get_timesheet_entries_admin(date, date, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_timesheet_entries_admin(p_start_date date DEFAULT (date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone))::date, p_end_date date DEFAULT ((date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone) + '6 days'::interval))::date, p_employee_id uuid DEFAULT NULL::uuid, p_job_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_division text DEFAULT NULL::text) RETURNS TABLE(id uuid, job_id uuid, employee_id uuid, employee_name text, job_number text, insured_name text, division text, work_date date, hours numeric, hourly_rate numeric, total_cost numeric, work_type text, description text, approved boolean, approved_by uuid, travel_start timestamp with time zone, clock_in timestamp with time zone, on_site_end timestamp with time zone, clock_out timestamp with time zone, travel_minutes numeric, total_paused_minutes numeric, auto_continued boolean, appointment_id uuid, notes text, created_at timestamp with time zone, duration_minutes numeric, is_open boolean, is_overlong boolean, has_pending_change boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select * from (
    select t.id, t.job_id, t.employee_id, e.full_name as employee_name, j.job_number, j.insured_name, j.division::text as division,
      t.work_date, t.hours, t.hourly_rate, t.total_cost, t.work_type, t.description, t.approved, t.approved_by,
      t.travel_start, t.clock_in, t.on_site_end, t.clock_out, t.travel_minutes, t.total_paused_minutes, t.auto_continued,
      t.appointment_id, t.notes, t.created_at,
      round(coalesce(t.travel_minutes, 0) + coalesce(t.hours, 0) * 60, 1) as duration_minutes,
      (t.clock_out is null and t.travel_start is not null) as is_open,
      ((coalesce(t.hours, 0) + coalesce(t.travel_minutes, 0) / 60.0) > 12) as is_overlong,
      exists (select 1 from time_entry_change_requests cr where cr.entry_id = t.id and cr.status = 'pending') as has_pending_change
    from job_time_entries t join employees e on e.id = t.employee_id join jobs j on j.id = t.job_id
    where t.work_date between p_start_date and p_end_date
      and (p_employee_id is null or t.employee_id = p_employee_id) and (p_job_id is null or t.job_id = p_job_id)
      and (p_division is null or j.division::text = p_division)
  ) q
  where (p_status is null or (p_status='open' and q.is_open) or (p_status='approved' and q.approved)
    or (p_status='unapproved' and not coalesce(q.approved,false)) or (p_status='overlong' and q.is_overlong))
  order by q.work_date desc, q.employee_name, q.clock_in;
$$;


--
-- Name: get_tracking_numbers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tracking_numbers() RETURNS TABLE(tracking_number text, label text, call_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT il.tracking_number, tn.label, count(*) AS call_count
  FROM inbound_leads il
  LEFT JOIN crm_tracking_numbers tn ON tn.tracking_number = il.tracking_number
  WHERE il.tracking_number IS NOT NULL
  GROUP BY il.tracking_number, tn.label
  ORDER BY count(*) DESC;
$$;


--
-- Name: get_unassigned_tasks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unassigned_tasks(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(phase_group ORDER BY phase_group->>'phase_name'), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'phase_name', jt.phase_name,
      'phase_color', jt.phase_color,
      'tasks', jsonb_agg(
        jsonb_build_object(
          'id', jt.id,
          'title', jt.title,
          'description', jt.description,
          'is_required', jt.is_required,
          'display_order', jt.display_order
        ) ORDER BY jt.display_order
      )
    ) as phase_group
    FROM job_tasks jt
    WHERE jt.job_id = p_job_id
      AND jt.appointment_id IS NULL
      AND jt.is_completed = false
    GROUP BY jt.phase_name, jt.phase_color
  ) sub;

  RETURN result;
END;
$$;


--
-- Name: get_unread_notification_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_notification_count(p_employee_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  IF v_is_service_role THEN
    RETURN (
      SELECT count(*)::integer
      FROM public.notifications notification
      WHERE notification.read_at IS NULL
        AND (
          notification.recipient_id IS NULL
          OR notification.recipient_id = p_employee_id
        )
    );
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active = true
    AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  IF p_employee_id IS NOT NULL AND p_employee_id <> v_actor THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;

  RETURN (
    SELECT count(*)::integer
    FROM public.notifications notification
    LEFT JOIN public.notification_reads receipt
      ON receipt.notification_id = notification.id
     AND receipt.employee_id = v_actor
     AND notification.recipient_id IS NULL
    WHERE (
            notification.recipient_id IS NULL
            OR notification.recipient_id = p_employee_id
          )
      AND CASE
            WHEN notification.recipient_id IS NULL
              THEN COALESCE(notification.read_at, receipt.read_at)
            ELSE notification.read_at
          END IS NULL
  );
END;
$$;


