    mc_pct numeric,
    rh_pct numeric,
    temp_f numeric,
    gpp numeric,
    dew_point_f numeric,
    dry_standard_pct numeric,
    drying_goal_pct numeric,
    is_affected boolean DEFAULT true NOT NULL,
    taken_by uuid,
    taken_at timestamp with time zone DEFAULT now() NOT NULL,
