--
-- Name: insert_reading(uuid, uuid, public.material_type, text, numeric, numeric, numeric, numeric, numeric, boolean, uuid, uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_reading(p_job_id uuid, p_room_id uuid, p_material public.material_type, p_location text, p_mc numeric, p_rh numeric, p_temp_f numeric, p_gpp numeric, p_dew_point numeric, p_is_affected boolean, p_equipment_id uuid, p_taken_by uuid, p_notes text, p_client_id uuid, p_taken_at timestamp with time zone DEFAULT now()) RETURNS public.moisture_readings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_existing_standard NUMERIC;
  v_existing_goal     NUMERIC;
  v_dry_standard      NUMERIC;
  v_drying_goal       NUMERIC;
  result              moisture_readings;
BEGIN
  SELECT mr.dry_standard_pct, mr.drying_goal_pct
    INTO v_existing_standard, v_existing_goal
    FROM moisture_readings mr
   WHERE mr.job_id = p_job_id AND mr.material = p_material
     AND mr.dry_standard_pct IS NOT NULL
   ORDER BY mr.taken_at ASC LIMIT 1;

  IF p_is_affected = false AND v_existing_standard IS NULL AND p_mc IS NOT NULL THEN
    v_dry_standard := p_mc;
    v_drying_goal  := p_mc + 2;
  ELSIF v_existing_standard IS NOT NULL THEN
    v_dry_standard := v_existing_standard;
    v_drying_goal  := COALESCE(v_existing_goal, v_existing_standard + 2);
  ELSE
    v_dry_standard := NULL;
    v_drying_goal  := NULL;
  END IF;

  INSERT INTO moisture_readings (
    job_id, room_id, equipment_id, material, location_description,
    mc_pct, rh_pct, temp_f, gpp, dew_point_f,
    dry_standard_pct, drying_goal_pct,
    is_affected, taken_by, taken_at, notes, client_id
  )
  VALUES (
    p_job_id, p_room_id, p_equipment_id, p_material, p_location,
    p_mc, p_rh, p_temp_f, p_gpp, p_dew_point,
    v_dry_standard, v_drying_goal,
    p_is_affected, p_taken_by, p_taken_at, p_notes, p_client_id
  )
  ON CONFLICT (client_id) DO UPDATE
    SET room_id=EXCLUDED.room_id, equipment_id=EXCLUDED.equipment_id,
        material=EXCLUDED.material, location_description=EXCLUDED.location_description,
        mc_pct=EXCLUDED.mc_pct, rh_pct=EXCLUDED.rh_pct, temp_f=EXCLUDED.temp_f,
        gpp=EXCLUDED.gpp, dew_point_f=EXCLUDED.dew_point_f,
        dry_standard_pct=EXCLUDED.dry_standard_pct, drying_goal_pct=EXCLUDED.drying_goal_pct,
        is_affected=EXCLUDED.is_affected, notes=EXCLUDED.notes
  RETURNING * INTO result;

  IF p_is_affected = false AND v_existing_standard IS NULL AND v_dry_standard IS NOT NULL THEN
    UPDATE moisture_readings
       SET dry_standard_pct = v_dry_standard, drying_goal_pct = v_drying_goal
     WHERE job_id = p_job_id AND material = p_material
       AND dry_standard_pct IS NULL AND id <> result.id;
  END IF;

  RETURN result;
END;
$$;


--
-- Name: tech_feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tech_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    type text NOT NULL,
    title text NOT NULL,
    description text,
    screenshots jsonb DEFAULT '[]'::jsonb,
    status text DEFAULT 'new'::text NOT NULL,
    admin_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    source text DEFAULT 'tech'::text NOT NULL,
    resolved_at timestamp with time zone,
    attachments_purged_at timestamp with time zone,
    CONSTRAINT tech_feedback_source_check CHECK ((source = ANY (ARRAY['tech'::text, 'desktop'::text]))),
    CONSTRAINT tech_feedback_status_check CHECK ((status = ANY (ARRAY['new'::text, 'reviewed'::text, 'resolved'::text, 'dismissed'::text]))),
    CONSTRAINT tech_feedback_type_check CHECK ((type = ANY (ARRAY['bug'::text, 'feature'::text])))
);


--
-- Name: insert_tech_feedback(uuid, text, text, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_tech_feedback(p_employee_id uuid, p_type text, p_title text, p_description text DEFAULT NULL::text, p_screenshots jsonb DEFAULT '[]'::jsonb, p_attachments jsonb DEFAULT '[]'::jsonb, p_source text DEFAULT 'tech'::text) RETURNS public.tech_feedback
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_screenshots jsonb := COALESCE(p_screenshots, '[]'::jsonb);
  v_attachments jsonb := COALESCE(p_attachments, '[]'::jsonb);
  result        tech_feedback;
BEGIN
  -- The live TechFeedback.jsx sends p_screenshots as JSON.stringify(paths):
  -- PostgREST delivers a jsonb STRING scalar containing serialized JSON.
  -- Decode it so old-caller screenshots are stored as real arrays (and
  -- actually render in AdminFeedback — see header). Anything still not an
  -- array after decoding is dropped defensively.
  IF jsonb_typeof(v_screenshots) = 'string' THEN
    BEGIN
      v_screenshots := (v_screenshots #>> '{}')::jsonb;
    EXCEPTION WHEN others THEN
      v_screenshots := '[]'::jsonb;
    END;
  END IF;
  IF jsonb_typeof(v_attachments) = 'string' THEN
    BEGIN
      v_attachments := (v_attachments #>> '{}')::jsonb;
    EXCEPTION WHEN others THEN
      v_attachments := '[]'::jsonb;
    END;
  END IF;
  IF jsonb_typeof(v_screenshots) <> 'array' THEN v_screenshots := '[]'::jsonb; END IF;
  IF jsonb_typeof(v_attachments) <> 'array' THEN v_attachments := '[]'::jsonb; END IF;

  IF v_attachments = '[]'::jsonb AND jsonb_array_length(v_screenshots) > 0 THEN
    -- Old caller (live TechFeedback.jsx): mirror screenshots → attachments as
    -- {path}-only records, bucket prefix stripped.
    SELECT COALESCE(
             jsonb_agg(jsonb_build_object('path', regexp_replace(elem, '^job-files/', ''))),
             '[]'::jsonb)
    INTO v_attachments
    FROM jsonb_array_elements_text(v_screenshots) AS elem;
  ELSIF v_screenshots = '[]'::jsonb AND jsonb_array_length(v_attachments) > 0 THEN
    -- New caller: mirror IMAGE attachments → screenshots with the bucket
    -- prefix, so the live AdminFeedback.jsx keeps rendering them. Videos are
    -- not screenshots and are deliberately not mirrored.
    SELECT COALESCE(
             jsonb_agg('job-files/' || regexp_replace(att->>'path', '^job-files/', '')),
             '[]'::jsonb)
    INTO v_screenshots
    FROM jsonb_array_elements(v_attachments) AS att
    WHERE att->>'mime' LIKE 'image/%';
  END IF;

  INSERT INTO tech_feedback (employee_id, type, title, description, screenshots, attachments, source)
  VALUES (p_employee_id, p_type, p_title, p_description,
          v_screenshots, v_attachments, COALESCE(p_source, 'tech'))
  RETURNING * INTO result;
  RETURN result;
END;
$$;


--
-- Name: is_active_internal_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_internal_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM employees e
    WHERE e.auth_user_id = auth.uid()
      AND e.is_active
      AND NOT e.is_external
      AND e.role::text = 'admin'
  );
$$;


