--
-- Name: link_contact_to_job(uuid, uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_contact_to_job(p_contact_id uuid, p_job_id uuid, p_role text DEFAULT 'other'::text, p_is_primary boolean DEFAULT false, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_link_id uuid;
BEGIN
  INSERT INTO contact_jobs (contact_id, job_id, role, is_primary, notes)
  VALUES (p_contact_id, p_job_id, p_role, p_is_primary, p_notes)
  ON CONFLICT (contact_id, job_id, role) DO UPDATE SET
    is_primary = EXCLUDED.is_primary,
    notes = COALESCE(EXCLUDED.notes, contact_jobs.notes)
  RETURNING id INTO v_link_id;

  IF p_is_primary THEN
    UPDATE contact_jobs SET is_primary = false
    WHERE job_id = p_job_id AND id != v_link_id AND is_primary = true;
    UPDATE jobs SET primary_contact_id = p_contact_id WHERE id = p_job_id;
  END IF;

  RETURN jsonb_build_object('link_id', v_link_id, 'success', true);
END;
$$;


