--
-- Name: log_phase_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_phase_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.phase IS DISTINCT FROM NEW.phase THEN
    INSERT INTO job_phase_history (job_id, from_phase, to_phase, changed_at, duration_hours)
    VALUES (
      NEW.id, OLD.phase, NEW.phase, now(),
      EXTRACT(EPOCH FROM (now() - COALESCE(OLD.phase_entered_at, OLD.updated_at))) / 3600.0
    );
    NEW.phase_entered_at = now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_system_event(text, text, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_system_event(p_event_type text, p_entity_type text, p_entity_id uuid, p_job_id uuid, p_actor_id uuid, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_event_id UUID;
BEGIN
  INSERT INTO system_events (event_type, entity_type, entity_id, job_id, actor_id, payload)
  VALUES (p_event_type, p_entity_type, p_entity_id, p_job_id, p_actor_id, p_payload)
  RETURNING id INTO v_event_id;
  RETURN v_event_id;
END;
$$;


--
-- Name: mark_all_notifications_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_notifications_read(p_employee_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  IF v_is_service_role THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE read_at IS NULL
       AND (
         recipient_id IS NULL
         OR recipient_id = p_employee_id
       );
    RETURN;
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active = true
    AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  IF p_employee_id IS NOT NULL AND p_employee_id <> v_actor THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;

  INSERT INTO public.notification_reads (
    notification_id,
    employee_id,
    read_at
  )
  SELECT notification.id, v_actor, now()
  FROM public.notifications notification
  WHERE notification.recipient_id IS NULL
    AND notification.read_at IS NULL
  ON CONFLICT (notification_id, employee_id) DO NOTHING;

  IF p_employee_id IS NOT NULL THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE recipient_id = p_employee_id
       AND read_at IS NULL;
  END IF;
END;
$$;


--
-- Name: mark_feedback_attachments_purged(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_feedback_attachments_purged(p_id uuid) RETURNS public.tech_feedback
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result tech_feedback;
BEGIN
  UPDATE tech_feedback
  SET attachments_purged_at = COALESCE(attachments_purged_at, now())  -- first stamp wins
  WHERE id = p_id
  RETURNING * INTO result;
  RETURN result;
END;
$$;


--
-- Name: mark_job_real(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_job_real(p_job_id uuid, p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_job_id IS NULL THEN RETURN; END IF;
  UPDATE public.jobs
     SET is_real_job        = true,
         real_job_source    = COALESCE(real_job_source, p_source),
         real_job_marked_at = COALESCE(real_job_marked_at, now())
   WHERE id = p_job_id
     AND is_real_job = false;
END; $$;


--
-- Name: mark_notification_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_read(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_recipient uuid;
  v_existing_read_at timestamptz;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  -- Trusted server callers retain the old exact behavior. Browser callers never
  -- reach this branch because a signed service-role JWT cannot be minted by them.
  IF v_is_service_role THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE id = p_id
       AND read_at IS NULL;
    RETURN;
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
    WHERE employee.auth_user_id = (SELECT auth.uid())
      AND employee.is_active = true
      AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  SELECT notification.recipient_id, notification.read_at
    INTO v_recipient, v_existing_read_at
  FROM public.notifications notification
  WHERE notification.id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_recipient IS NULL THEN
    IF v_existing_read_at IS NULL THEN
      INSERT INTO public.notification_reads (
        notification_id,
        employee_id,
        read_at
      )
      VALUES (p_id, v_actor, now())
      ON CONFLICT (notification_id, employee_id) DO NOTHING;
    END IF;
  ELSIF v_recipient = v_actor THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE id = p_id
       AND read_at IS NULL;
  ELSE
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;
END;
$$;


--
-- Name: materialize_message_send_attempt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.materialize_message_send_attempt(p_attempt_id uuid) RETURNS TABLE(outcome text, message_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_attempt public.message_send_attempts%ROWTYPE;
  v_message public.messages%ROWTYPE;
  v_message_id uuid;
  v_status text;
  v_inserted boolean := false;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'materialize_message_send_attempt is service-role only'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_attempt
  FROM public.message_send_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_attempt.parent_attempt_id IS NULL AND v_attempt.recipient_contact_id IS NULL
        AND v_attempt.client_request_id IS NULL
     OR v_attempt.provider_message_id IS NULL
     OR v_attempt.conversation_id IS NULL
     OR v_attempt.state NOT IN ('accepted', 'ambiguous', 'confirmed') THEN
    RAISE EXCEPTION 'Message attempt is not materializable'
      USING ERRCODE = '22023';
  END IF;

  IF v_attempt.actual_channel IS NOT NULL
     AND v_attempt.actual_channel <> v_attempt.requested_channel THEN
    RAISE EXCEPTION 'Cross-channel fallback cannot be materialized'
      USING ERRCODE = '22023';
  END IF;

  IF v_attempt.message_id IS NOT NULL THEN
    RETURN QUERY SELECT 'message_already_materialized'::text, v_attempt.message_id;
    RETURN;
  END IF;

  SELECT *
  INTO v_message
  FROM public.messages m
  WHERE (m.provider = v_attempt.provider
      AND m.provider_message_id = v_attempt.provider_message_id)
     OR (v_attempt.client_request_id IS NOT NULL
      AND m.client_request_id = v_attempt.client_request_id)
  ORDER BY
    (m.provider = v_attempt.provider
      AND m.provider_message_id = v_attempt.provider_message_id) DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    IF v_message.provider IS DISTINCT FROM v_attempt.provider
       OR v_message.provider_message_id IS DISTINCT FROM v_attempt.provider_message_id
       OR v_message.conversation_id IS DISTINCT FROM v_attempt.conversation_id
       OR v_message.recipient_address IS DISTINCT FROM v_attempt.recipient_address
       OR v_message.body IS DISTINCT FROM v_attempt.canonical_body THEN
      RAISE EXCEPTION 'Existing message conflicts with provider attempt identity'
        USING ERRCODE = '23505';
    END IF;
    v_message_id := v_message.id;
  ELSE
    v_status := CASE
      WHEN v_attempt.state = 'confirmed' THEN 'sent'
      ELSE COALESCE(NULLIF(v_attempt.provider_status, ''), 'queued')
    END;

    INSERT INTO public.messages (
      conversation_id,
      type,
      channel,
      body,
      status,
      twilio_sid,
      sent_by,
      media_urls,
      provider,
      provider_message_id,
      provider_conversation_id,
      client_request_id,
      sender_address,
      recipient_address,
      direction
    )
    VALUES (
      v_attempt.conversation_id,
      'sms_outbound',
      COALESCE(v_attempt.actual_channel, v_attempt.requested_channel),
      v_attempt.canonical_body,
      v_status,
      CASE WHEN v_attempt.provider = 'twilio'
        THEN v_attempt.provider_message_id ELSE NULL END,
      v_attempt.actor_employee_id,
      CASE WHEN jsonb_array_length(v_attempt.media_urls) > 0
        THEN v_attempt.media_urls ELSE NULL END,
      v_attempt.provider,
      v_attempt.provider_message_id,
      v_attempt.provider_conversation_id,
      v_attempt.client_request_id,
      v_attempt.sender_address,
      v_attempt.recipient_address,
      'outbound'
    )
    RETURNING id INTO v_message_id;
    v_inserted := true;
  END IF;

  UPDATE public.message_send_attempts
  SET message_id = v_message_id, updated_at = now()
  WHERE id = v_attempt.id;

  RETURN QUERY
  SELECT
    CASE WHEN v_inserted
      THEN 'message_materialized'::text
      ELSE 'message_already_materialized'::text
    END,
    v_message_id;
END;
$$;


--
-- Name: FUNCTION materialize_message_send_attempt(p_attempt_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.materialize_message_send_attempt(p_attempt_id uuid) IS 'Service-role-only, provider-free recovery of one accepted attempt into exactly one canonical outbound message row.';


--
-- Name: merge_claims(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_claims(p_keep_id uuid, p_merge_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_keep claims;
  v_merge claims;
  v_jobs_moved INT;
BEGIN
  IF p_keep_id = p_merge_id THEN
    RAISE EXCEPTION 'Cannot merge a claim with itself';
  END IF;

  SELECT * INTO v_keep FROM claims WHERE id = p_keep_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Keep claim not found'; END IF;

  SELECT * INTO v_merge FROM claims WHERE id = p_merge_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Merge claim not found'; END IF;

  UPDATE claims SET
    insurance_carrier = COALESCE(insurance_carrier, v_merge.insurance_carrier),
    insurance_claim_number = COALESCE(insurance_claim_number, v_merge.insurance_claim_number),
    policy_number = COALESCE(policy_number, v_merge.policy_number),
    date_of_loss = COALESCE(date_of_loss, v_merge.date_of_loss),
    loss_address = COALESCE(loss_address, v_merge.loss_address),
    loss_city = COALESCE(loss_city, v_merge.loss_city),
    loss_state = COALESCE(loss_state, v_merge.loss_state),
    loss_zip = COALESCE(loss_zip, v_merge.loss_zip),
    loss_type = COALESCE(loss_type, v_merge.loss_type),
    contact_id = COALESCE(contact_id, v_merge.contact_id),
    adjuster_contact_id = COALESCE(adjuster_contact_id, v_merge.adjuster_contact_id),
    notes = CASE
      WHEN notes IS NULL THEN v_merge.notes
      WHEN v_merge.notes IS NOT NULL THEN notes || E'\n---\n' || v_merge.notes
      ELSE notes
    END,
    updated_at = now()
  WHERE id = p_keep_id;

  UPDATE jobs SET claim_id = p_keep_id WHERE claim_id = p_merge_id;
  GET DIAGNOSTICS v_jobs_moved = ROW_COUNT;

  INSERT INTO system_events (event_type, entity_type, entity_id, job_id, payload)
  VALUES ('claim.merged', 'claim', p_keep_id, NULL, jsonb_build_object(
    'kept_id', p_keep_id,
    'merged_id', p_merge_id,
    'merged_claim_number', v_merge.claim_number,
    'jobs_moved', v_jobs_moved
  ));

  DELETE FROM claims WHERE id = p_merge_id;

  RETURN jsonb_build_object(
    'ok', true,
    'kept_id', p_keep_id,
    'kept_claim_number', v_keep.claim_number,
    'merged_id', p_merge_id,
    'merged_claim_number', v_merge.claim_number,
    'jobs_moved', v_jobs_moved
  );
END;
$$;


--
-- Name: merge_contacts(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_contacts(p_keep_id uuid, p_merge_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_keep contacts; v_merge contacts;
  v_claims_moved INT := 0; v_jobs_moved INT := 0; v_conversations_moved INT := 0;
BEGIN
  IF p_keep_id = p_merge_id THEN RAISE EXCEPTION 'Cannot merge a contact with itself'; END IF;
  SELECT * INTO v_keep FROM contacts WHERE id = p_keep_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Keep contact not found'; END IF;
  SELECT * INTO v_merge FROM contacts WHERE id = p_merge_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Merge contact not found'; END IF;

  UPDATE contacts SET
    name = COALESCE(name, v_merge.name),
    email = COALESCE(email, v_merge.email),
    phone_secondary = COALESCE(phone_secondary, v_merge.phone_secondary),
    billing_address = COALESCE(billing_address, v_merge.billing_address),
    billing_city = COALESCE(billing_city, v_merge.billing_city),
    billing_state = COALESCE(billing_state, v_merge.billing_state),
    billing_zip = COALESCE(billing_zip, v_merge.billing_zip),
    insurance_carrier = COALESCE(insurance_carrier, v_merge.insurance_carrier),
    policy_number = COALESCE(policy_number, v_merge.policy_number),
    claim_number = COALESCE(claim_number, v_merge.claim_number),
    referral_source = COALESCE(referral_source, v_merge.referral_source),
    preferred_language = COALESCE(preferred_language, v_merge.preferred_language),
    desk_phone = COALESCE(desk_phone, v_merge.desk_phone),
    desk_extension = COALESCE(desk_extension, v_merge.desk_extension),
    territory = COALESCE(territory, v_merge.territory),
    trade_specialty = COALESCE(trade_specialty, v_merge.trade_specialty),
    notes = CASE WHEN notes IS NULL THEN v_merge.notes WHEN v_merge.notes IS NOT NULL THEN notes || E'\n---\n' || v_merge.notes ELSE notes END,
    relationship_notes = CASE WHEN relationship_notes IS NULL THEN v_merge.relationship_notes WHEN v_merge.relationship_notes IS NOT NULL THEN relationship_notes || E'\n---\n' || v_merge.relationship_notes ELSE relationship_notes END,
    dnd = COALESCE(dnd, false) OR COALESCE(v_merge.dnd, false),
    dnd_at = COALESCE(dnd_at, v_merge.dnd_at),
    opt_in_status = CASE WHEN opt_in_status = false OR v_merge.opt_in_status = false THEN false ELSE COALESCE(opt_in_status, v_merge.opt_in_status) END,
    opt_out_at = COALESCE(opt_out_at, v_merge.opt_out_at),
    opt_out_reason = COALESCE(opt_out_reason, v_merge.opt_out_reason),
    updated_at = now()
  WHERE id = p_keep_id;

  UPDATE claims SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  GET DIAGNOSTICS v_claims_moved = ROW_COUNT;
  UPDATE claims SET adjuster_contact_id = p_keep_id WHERE adjuster_contact_id = p_merge_id;
  UPDATE jobs SET primary_contact_id = p_keep_id WHERE primary_contact_id = p_merge_id;
  GET DIAGNOSTICS v_jobs_moved = ROW_COUNT;
  DELETE FROM contact_jobs WHERE contact_id = p_merge_id AND (job_id, role) IN (SELECT job_id, role FROM contact_jobs WHERE contact_id = p_keep_id);
  UPDATE contact_jobs SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE contact_addresses SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM contact_tags WHERE contact_id = p_merge_id AND tag IN (SELECT tag FROM contact_tags WHERE contact_id = p_keep_id);
  UPDATE contact_tags SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM conversation_participants WHERE contact_id = p_merge_id AND conversation_id IN (SELECT conversation_id FROM conversation_participants WHERE contact_id = p_keep_id);
  UPDATE conversation_participants SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  GET DIAGNOSTICS v_conversations_moved = ROW_COUNT;
  UPDATE messages SET sender_contact_id = p_keep_id WHERE sender_contact_id = p_merge_id;
  UPDATE invoices SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE payments SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE sign_requests SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE campaign_recipients SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE sms_consent_log SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE sub_confirmations SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE lead_attribution SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM email_campaign_recipients WHERE contact_id = p_merge_id AND campaign_id IN (SELECT campaign_id FROM email_campaign_recipients WHERE contact_id = p_keep_id);
  UPDATE email_campaign_recipients SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM email_campaign_exclusions WHERE contact_id = p_merge_id AND campaign_id IN (SELECT campaign_id FROM email_campaign_exclusions WHERE contact_id = p_keep_id);
  UPDATE email_campaign_exclusions SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE inbound_leads SET contact_id = p_keep_id WHERE contact_id = p_merge_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('contact.merged', 'contact', p_keep_id, jsonb_build_object('kept_id', p_keep_id, 'merged_id', p_merge_id, 'merged_name', v_merge.name, 'merged_phone', v_merge.phone, 'claims_moved', v_claims_moved, 'jobs_moved', v_jobs_moved, 'conversations_moved', v_conversations_moved));
  DELETE FROM contacts WHERE id = p_merge_id;
  RETURN jsonb_build_object('ok', true, 'kept_id', p_keep_id, 'merged_id', p_merge_id, 'claims_moved', v_claims_moved, 'jobs_moved', v_jobs_moved, 'conversations_moved', v_conversations_moved);
END;
$$;


--
-- Name: merge_jobs(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_jobs(p_keep_id uuid, p_merge_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_keep jobs;
  v_merge jobs;
  v_keep_has_payments BOOLEAN;
  v_merge_has_payments BOOLEAN;
  v_docs_moved INT := 0;
  v_time_entries_moved INT := 0;
  v_tmp INT;
BEGIN
  IF p_keep_id = p_merge_id THEN
    RAISE EXCEPTION 'Cannot merge a job with itself';
  END IF;

  SELECT * INTO v_keep FROM jobs WHERE id = p_keep_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Keep job not found'; END IF;

  SELECT * INTO v_merge FROM jobs WHERE id = p_merge_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Merge job not found'; END IF;

  SELECT EXISTS(SELECT 1 FROM payments WHERE job_id = p_keep_id) INTO v_keep_has_payments;
  SELECT EXISTS(SELECT 1 FROM payments WHERE job_id = p_merge_id) INTO v_merge_has_payments;
  IF v_keep_has_payments AND v_merge_has_payments THEN
    RAISE EXCEPTION 'Both jobs have payment records. Manual reconciliation required — choose the job with the correct payment history as the keeper.';
  END IF;

  UPDATE jobs SET
    insured_name = COALESCE(insured_name, v_merge.insured_name),
    address = COALESCE(address, v_merge.address),
    city = COALESCE(city, v_merge.city),
    state = COALESCE(state, v_merge.state),
    zip = COALESCE(zip, v_merge.zip),
    client_email = COALESCE(client_email, v_merge.client_email),
    client_phone = COALESCE(client_phone, v_merge.client_phone),
    insurance_company = COALESCE(insurance_company, v_merge.insurance_company),
    claim_number = COALESCE(claim_number, v_merge.claim_number),
    adjuster_name = COALESCE(adjuster_name, v_merge.adjuster_name),
    adjuster_phone = COALESCE(adjuster_phone, v_merge.adjuster_phone),
    adjuster_email = COALESCE(adjuster_email, v_merge.adjuster_email),
    policy_number = COALESCE(policy_number, v_merge.policy_number),
    cat_code = COALESCE(cat_code, v_merge.cat_code),
    date_of_loss = COALESCE(date_of_loss, v_merge.date_of_loss),
    type_of_loss = COALESCE(type_of_loss, v_merge.type_of_loss),
    broker_agent = COALESCE(broker_agent, v_merge.broker_agent),
    project_manager = COALESCE(project_manager, v_merge.project_manager),
    encircle_summary = COALESCE(encircle_summary, v_merge.encircle_summary),
    encircle_claim_id = COALESCE(encircle_claim_id, v_merge.encircle_claim_id),
    carrier_identifier = COALESCE(carrier_identifier, v_merge.carrier_identifier),
    assignment_identifier = COALESCE(assignment_identifier, v_merge.assignment_identifier),
    claim_id = COALESCE(claim_id, v_merge.claim_id),
    primary_contact_id = COALESCE(primary_contact_id, v_merge.primary_contact_id),
    lead_source = COALESCE(lead_source, v_merge.lead_source),
    lead_source_detail = COALESCE(lead_source_detail, v_merge.lead_source_detail),
    estimator = COALESCE(estimator, v_merge.estimator),
    lead_tech = COALESCE(lead_tech, v_merge.lead_tech),
    supervisor = COALESCE(supervisor, v_merge.supervisor),
    internal_notes = CASE
      WHEN internal_notes IS NULL THEN v_merge.internal_notes
      WHEN v_merge.internal_notes IS NOT NULL THEN internal_notes || E'\n---\nMerged from ' || COALESCE(v_merge.job_number, v_merge.id::text) || E':\n' || v_merge.internal_notes
      ELSE internal_notes
    END,
    estimated_value = COALESCE(estimated_value, 0) + COALESCE(v_merge.estimated_value, 0),
    approved_value = COALESCE(approved_value, 0) + COALESCE(v_merge.approved_value, 0),
    invoiced_value = COALESCE(invoiced_value, 0) + COALESCE(v_merge.invoiced_value, 0),
    collected_value = COALESCE(collected_value, 0) + COALESCE(v_merge.collected_value, 0),
    supplement_value = COALESCE(supplement_value, 0) + COALESCE(v_merge.supplement_value, 0),
    total_labor_cost = COALESCE(total_labor_cost, 0) + COALESCE(v_merge.total_labor_cost, 0),
    total_material_cost = COALESCE(total_material_cost, 0) + COALESCE(v_merge.total_material_cost, 0),
    total_equipment_cost = COALESCE(total_equipment_cost, 0) + COALESCE(v_merge.total_equipment_cost, 0),
    total_sub_cost = COALESCE(total_sub_cost, 0) + COALESCE(v_merge.total_sub_cost, 0),
    total_other_cost = COALESCE(total_other_cost, 0) + COALESCE(v_merge.total_other_cost, 0),
    updated_at = now()
  WHERE id = p_keep_id;

  -- Financial
  UPDATE payments SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE invoices SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE estimates SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE job_costs SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE job_supplements SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE vendor_invoices SET job_id = p_keep_id WHERE job_id = p_merge_id;

  -- Documentation
  UPDATE job_documents SET job_id = p_keep_id WHERE job_id = p_merge_id;
  GET DIAGNOSTICS v_docs_moved = ROW_COUNT;
  UPDATE job_notes SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE job_checklists SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE forms SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE sign_requests SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE document_requests SET job_id = p_keep_id WHERE job_id = p_merge_id;

  -- Operations
  UPDATE appointments SET job_id = p_keep_id WHERE job_id = p_merge_id;

  DELETE FROM job_assignments WHERE job_id = p_merge_id
    AND (employee_id, scheduled_date) IN (
      SELECT employee_id, scheduled_date FROM job_assignments WHERE job_id = p_keep_id
    );
  UPDATE job_assignments SET job_id = p_keep_id WHERE job_id = p_merge_id;

  UPDATE job_schedules SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE schedule_blocks SET job_id = p_keep_id WHERE job_id = p_merge_id;

  UPDATE job_time_entries SET job_id = p_keep_id WHERE job_id = p_merge_id;
  GET DIAGNOSTICS v_time_entries_moved = ROW_COUNT;

  UPDATE job_equipment SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE job_tasks SET job_id = p_keep_id WHERE job_id = p_merge_id;

  -- Communications
  UPDATE conversations SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE notification_queue SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE selection_dispatches SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE selection_responses SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE sub_confirmations SET job_id = p_keep_id WHERE job_id = p_merge_id;

  -- Tracking
  UPDATE job_phase_history SET job_id = p_keep_id WHERE job_id = p_merge_id;
  UPDATE system_events SET job_id = p_keep_id WHERE job_id = p_merge_id;

  DELETE FROM dispatch_board_jobs WHERE job_id = p_merge_id;

  DELETE FROM contact_jobs WHERE job_id = p_merge_id
    AND (contact_id, role) IN (SELECT contact_id, role FROM contact_jobs WHERE job_id = p_keep_id);
  UPDATE contact_jobs SET job_id = p_keep_id WHERE job_id = p_merge_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, job_id, payload)
  VALUES ('job.merged', 'job', p_keep_id, p_keep_id, jsonb_build_object(
    'kept_id', p_keep_id,
    'kept_job_number', v_keep.job_number,
    'merged_id', p_merge_id,
    'merged_job_number', v_merge.job_number,
    'docs_moved', v_docs_moved,
    'time_entries_moved', v_time_entries_moved
  ));

  DELETE FROM jobs WHERE id = p_merge_id;

  RETURN jsonb_build_object(
    'ok', true,
    'kept_id', p_keep_id,
    'kept_job_number', v_keep.job_number,
    'merged_id', p_merge_id,
    'merged_job_number', v_merge.job_number,
    'docs_moved', v_docs_moved,
    'time_entries_moved', v_time_entries_moved
  );
END;
$$;


--
-- Name: messaging_can_access_conversations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.messaging_can_access_conversations() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH actor AS (
    SELECT id, role
    FROM public.employees
    WHERE auth_user_id = auth.uid()
      AND is_active = true
      AND COALESCE(is_external, false) = false
    LIMIT 1
  ),
  employee_override AS (
    SELECT epa.can_view
    FROM public.employee_page_access epa
    JOIN actor ON actor.id = epa.employee_id
    WHERE epa.nav_key = 'conversations'
    LIMIT 1
  )
  SELECT EXISTS (
    SELECT 1
    FROM actor
    WHERE NOT COALESCE((
      SELECT force_disabled
      FROM public.feature_flags
      WHERE key = 'page:conversations'
      LIMIT 1
    ), false)
      AND CASE
        WHEN EXISTS (SELECT 1 FROM employee_override)
          THEN (SELECT can_view FROM employee_override)
        WHEN actor.role = 'admin' THEN true
        ELSE COALESCE((
          SELECT np.can_view
          FROM public.nav_permissions np
          WHERE np.role = actor.role::text
            AND np.nav_key = 'conversations'
          LIMIT 1
        ), false)
      END
  );
$$;


--
-- Name: FUNCTION messaging_can_access_conversations(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.messaging_can_access_conversations() IS 'Trusted boolean caller contract for company-wide conversation visibility: active non-external employee plus force-disable/override/admin/role permission precedence.';


