END;
$$;


--
-- Name: qbo_payments_sync_poll(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.qbo_payments_sync_poll() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_worker_url text;
  v_secret     text;
BEGIN
  SELECT value INTO v_worker_url FROM public.integration_config WHERE key = 'qbo_payments_sync_worker_url';
  SELECT value INTO v_secret     FROM public.integration_config WHERE key = 'qbo_webhook_secret';

  IF v_worker_url IS NULL OR v_worker_url NOT IN (
    'https://dev.utahpros.app/api/qbo-payments-sync',
    'https://utahpros.app/api/qbo-payments-sync'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_worker_url,
    headers := jsonb_build_object(
      'Content-Type',    'application/json',
      'x-webhook-secret', v_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );
END;
$$;


--
-- Name: queue_email_campaign(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_email_campaign(p_campaign_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_campaign email_campaigns;
  v_count    int;
BEGIN
  SELECT * INTO v_campaign FROM email_campaigns WHERE id = p_campaign_id;
  IF v_campaign IS NULL THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF v_campaign.status NOT IN ('draft', 'sending') THEN
    RAISE EXCEPTION 'Campaign already % — cannot (re)queue', v_campaign.status;
  END IF;

  INSERT INTO email_campaign_recipients (campaign_id, contact_id, email)
  SELECT p_campaign_id, a.contact_id, a.email
  FROM preview_email_audience(v_campaign.audience_filter, v_campaign.org_id) a
  WHERE NOT EXISTS (
    SELECT 1 FROM email_campaign_exclusions ex
    WHERE ex.campaign_id = p_campaign_id AND ex.contact_id = a.contact_id
  )
  ON CONFLICT (campaign_id, contact_id) DO NOTHING;

  SELECT count(*) INTO v_count FROM email_campaign_recipients WHERE campaign_id = p_campaign_id;

  UPDATE email_campaigns SET status = 'sending', audience_count = v_count, updated_at = now() WHERE id = p_campaign_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_email_campaign_queued', 'email_campaign', p_campaign_id, jsonb_build_object('recipient_count', v_count));

  RETURN v_count;
END;
$$;


--
-- Name: rearm_callrail_provider_event(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_callrail_provider_event(p_event_id uuid, p_expect_error_code text, p_now timestamp with time zone DEFAULT now()) RETURNS SETOF public.message_provider_events
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'rearm_callrail_provider_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  IF p_expect_error_code IS NULL OR btrim(p_expect_error_code) = '' THEN
    RAISE EXCEPTION 'rearm_callrail_provider_event requires the expected error_code'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  UPDATE public.message_provider_events AS event
  SET
    processing_state    = 'received',
    processing_attempts = 0,
    next_attempt_at     = NULL,
    claimed_at          = NULL,
    updated_at          = p_now
  WHERE event.id = p_event_id
    AND event.provider = 'callrail'
    AND event.message_type IN ('sms', 'mms')
    AND event.processing_state = 'failed'
    AND event.error_code = p_expect_error_code
  RETURNING event.*;
END;
$$;


--
-- Name: FUNCTION rearm_callrail_provider_event(p_event_id uuid, p_expect_error_code text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rearm_callrail_provider_event(p_event_id uuid, p_expect_error_code text, p_now timestamp with time zone) IS 'Service-role only. Moves ONE terminally-failed CallRail sms/mms event back to received so the recovery worker retries it. Requires the exact event id AND its current error_code, so it cannot be used to bulk-reset failures. Preserves error_code/error_message as the audit trail. Returns only the row it changed.';


--
-- Name: recompute_estimate_from_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_estimate_from_lines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  target uuid;
  sub    numeric;
BEGIN
  target := CASE WHEN TG_OP = 'DELETE' THEN OLD.estimate_id ELSE NEW.estimate_id END;
  IF target IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT COALESCE(SUM(line_total), 0) INTO sub FROM estimate_line_items WHERE estimate_id = target;
  UPDATE estimates
     SET subtotal   = sub,
         amount     = sub,
         updated_at = now()
   WHERE id = target;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recompute_invoice_from_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_invoice_from_lines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  target uuid;
  sub    numeric;
BEGIN
  target := CASE WHEN TG_OP = 'DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END;
  IF target IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT COALESCE(SUM(line_total), 0) INTO sub FROM invoice_line_items WHERE invoice_id = target;
  UPDATE invoices
     SET subtotal   = sub,
         total      = sub + COALESCE(tax, 0),
         updated_at = now()
   WHERE id = target;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: record_email_campaign_send(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_email_campaign_send(p_recipient_id uuid, p_status text, p_resend_id text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_campaign_id uuid;
  v_pending     int;
  v_sent        int;
  v_suppressed  int;
  v_failed      int;
BEGIN
  IF p_status NOT IN ('sent', 'suppressed', 'failed') THEN
    RAISE EXCEPTION 'invalid recipient status: %', p_status;
  END IF;
  UPDATE email_campaign_recipients
     SET status = p_status,
         resend_id = p_resend_id,
         error_message = p_error_message,
         sent_at = CASE WHEN p_status = 'sent' THEN now() ELSE sent_at END
   WHERE id = p_recipient_id
   RETURNING campaign_id INTO v_campaign_id;
  IF v_campaign_id IS NULL THEN
    RAISE EXCEPTION 'Recipient row not found';
  END IF;
  UPDATE email_campaigns SET
    total_sent       = (SELECT count(*) FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'sent'),
    total_suppressed = (SELECT count(*) FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'suppressed'),
    total_failed      = (SELECT count(*) FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'failed'),
    updated_at = now()
  WHERE id = v_campaign_id;
  SELECT count(*) INTO v_pending FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'pending';
  IF v_pending = 0 THEN
    UPDATE email_campaigns SET status = 'sent', sent_at = now(), updated_at = now()
     WHERE id = v_campaign_id AND status = 'sending'
     RETURNING total_sent, total_suppressed, total_failed INTO v_sent, v_suppressed, v_failed;
    IF FOUND THEN
      INSERT INTO system_events (event_type, entity_type, entity_id, payload)
      VALUES ('crm_email_campaign_sent', 'email_campaign', v_campaign_id,
        jsonb_build_object(
          'sent', v_sent, 'suppressed', v_suppressed, 'failed', v_failed,
          'total', COALESCE(v_sent, 0) + COALESCE(v_suppressed, 0) + COALESCE(v_failed, 0)));
    END IF;
  END IF;
END;
$$;


--
-- Name: record_email_open(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_email_open(p_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
