--
-- Name: request_account_deletion(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_deletion(p_notes text DEFAULT NULL::text) RETURNS public.account_deletion_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp public.employees%ROWTYPE;
  v_row public.account_deletion_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_emp
  FROM public.employees
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_emp.id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: no employee for caller' USING errcode = '42501';
  END IF;

  SELECT * INTO v_row
  FROM public.account_deletion_requests
  WHERE employee_id = v_emp.id AND status = 'pending'
  ORDER BY requested_at DESC
  LIMIT 1;

  IF v_row.id IS NOT NULL THEN
    RETURN v_row;
  END IF;

  BEGIN
    INSERT INTO public.account_deletion_requests (employee_id, notes)
    VALUES (v_emp.id, NULLIF(btrim(p_notes), ''))
    RETURNING * INTO v_row;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_row
    FROM public.account_deletion_requests
    WHERE employee_id = v_emp.id AND status = 'pending'
    ORDER BY requested_at DESC
    LIMIT 1;
    RETURN v_row;
  END;

  INSERT INTO public.notifications (type, title, body, entity_type, entity_id, recipient_id)
  SELECT
    'account_deletion_requested',
    'Account deletion requested',
    COALESCE(v_emp.full_name, 'An employee')
      || ' requested that their account be deleted. Deactivate their access and handle data retention per policy.',
    'employee',
    v_emp.id,
    a.id
  FROM public.employees a
  WHERE a.role = 'admin' AND a.is_active;

  RETURN v_row;
END;
$$;


--
-- Name: resolve_provider_event(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_provider_event(p_event_id uuid, p_resolved_by uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now()) RETURNS SETOF public.message_provider_events
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'resolve_provider_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  UPDATE public.message_provider_events AS event
  SET
    resolved_at = p_now,
    resolved_by = p_resolved_by,
    updated_at  = p_now
  WHERE event.id = p_event_id
    AND event.processing_state = 'failed'
    AND event.resolved_at IS NULL
  RETURNING event.*;
END;
$$;


--
-- Name: FUNCTION resolve_provider_event(p_event_id uuid, p_resolved_by uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_provider_event(p_event_id uuid, p_resolved_by uuid, p_now timestamp with time zone) IS 'Service-role only. Marks ONE terminally-failed event acknowledged so ops-health stops alerting on it. Only touches processing_state=failed rows that are not already resolved, so it is idempotent and cannot silence an in-flight event. Returns only the row it changed.';


--
-- Name: time_entry_change_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.time_entry_change_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entry_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    proposed jsonb NOT NULL,
    tech_note text,
    status text DEFAULT 'pending'::text NOT NULL,
    reviewed_by uuid,
    review_note text,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT time_entry_change_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: review_time_entry_change_request(uuid, boolean, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_time_entry_change_request(p_request_id uuid, p_approve boolean, p_actor_id uuid, p_review_note text DEFAULT NULL::text) RETURNS public.time_entry_change_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_req time_entry_change_requests%ROWTYPE; v_e job_time_entries%ROWTYPE; v_p jsonb;
begin
  if not is_time_admin(p_actor_id) then raise exception 'NOT_AUTHORIZED' using errcode='P0001'; end if;
  select * into v_req from time_entry_change_requests where id=p_request_id;
  if v_req.id is null then raise exception 'REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if v_req.status <> 'pending' then raise exception 'REQUEST_ALREADY_REVIEWED' using errcode='P0001'; end if;
  if p_approve then
    select * into v_e from job_time_entries where id=v_req.entry_id;
    if v_e.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
    v_p := v_req.proposed;
    perform admin_upsert_time_entry(p_actor_id=>p_actor_id, p_id=>v_e.id, p_employee_id=>v_e.employee_id, p_job_id=>v_e.job_id,
      p_work_date=>coalesce((v_p->>'work_date')::date, v_e.work_date), p_hours=>coalesce((v_p->>'hours')::numeric, v_e.hours),
      p_clock_in=>coalesce((v_p->>'clock_in')::timestamptz, v_e.clock_in), p_clock_out=>coalesce((v_p->>'clock_out')::timestamptz, v_e.clock_out),
      p_travel_start=>v_e.travel_start, p_on_site_end=>v_e.on_site_end, p_travel_minutes=>coalesce((v_p->>'travel_minutes')::numeric, v_e.travel_minutes),
      p_total_paused_minutes=>v_e.total_paused_minutes, p_work_type=>v_e.work_type, p_description=>coalesce(v_p->>'description', v_e.description),
      p_notes=>coalesce(v_p->>'notes', v_e.notes), p_override_approved=>true);
  end if;
  update time_entry_change_requests set status=case when p_approve then 'approved' else 'rejected' end, reviewed_by=p_actor_id, review_note=p_review_note, reviewed_at=now() where id=p_request_id returning * into v_req;
  perform notify_emit('timesheet.change_reviewed', jsonb_build_object(
    'employee_id', v_req.requested_by,
    'title', case when p_approve then 'Timesheet change approved' else 'Timesheet change rejected' end,
    'body', coalesce(nullif(p_review_note,''), case when p_approve then 'Your requested correction was approved.' else 'Your requested correction was declined.' end),
    'link', '/time-tracking',
    'entity_type', 'time_entry_change_request',
    'entity_id', v_req.id,
    'payload', jsonb_build_object('entry_id', v_req.entry_id, 'approved', p_approve)
  ));
  insert into system_events (event_type, entity_type, entity_id, actor_id, job_id, payload) values ('time_entry.change_reviewed','time_entry_change_request', v_req.id, p_actor_id, null, jsonb_build_object('approved', p_approve, 'entry_id', v_req.entry_id));
  return v_req;
end; $$;


--
-- Name: save_dashboard_layout(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_dashboard_layout(p_layout jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_emp uuid;
BEGIN
  SELECT id INTO v_emp FROM public.employees WHERE auth_user_id = auth.uid() LIMIT 1;
  IF v_emp IS NULL THEN RETURN; END IF;
  INSERT INTO public.dashboard_layouts (employee_id, layout, updated_at)
  VALUES (v_emp, p_layout, now())
  ON CONFLICT (employee_id) DO UPDATE SET layout = EXCLUDED.layout, updated_at = now();
END;
$$;


--
-- Name: save_demo_sheet(uuid, jsonb, date, uuid, text, text, text, text, text, text, uuid, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_demo_sheet(p_id uuid, p_data jsonb, p_job_date date, p_tech_id uuid, p_job_number text, p_address text, p_insured_name text, p_encircle_claim_id text, p_status text DEFAULT 'draft'::text, p_encircle_note_id text DEFAULT NULL::text, p_job_id uuid DEFAULT NULL::uuid, p_summary jsonb DEFAULT NULL::jsonb, p_email_sent boolean DEFAULT NULL::boolean, p_schema_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_tech_name TEXT;
  v_schema_id UUID;
BEGIN
  IF p_tech_id IS NOT NULL THEN
    SELECT COALESCE(display_name, full_name) INTO v_tech_name
    FROM employees WHERE id = p_tech_id;
  END IF;

  IF p_id IS NULL THEN
    v_schema_id := p_schema_id;
    IF v_schema_id IS NULL THEN
      SELECT id INTO v_schema_id FROM demo_sheet_schemas WHERE is_active = true LIMIT 1;
    END IF;

    INSERT INTO forms (
      form_type, form_data, summary, form_date, technician_name,
      submitted_by, status, encircle_claim_id, encircle_note_id,
      encircle_synced_at, email_sent, email_sent_at, job_id, schema_id
    )
    VALUES (
      'demo_sheet', p_data, COALESCE(p_summary, '{}'::jsonb), p_job_date, v_tech_name,
      p_tech_id, p_status, p_encircle_claim_id, p_encircle_note_id,
      CASE WHEN p_encircle_note_id IS NOT NULL THEN now() ELSE NULL END,
      COALESCE(p_email_sent, false),
      CASE WHEN p_email_sent THEN now() ELSE NULL END,
      p_job_id, v_schema_id
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE forms SET
      form_data = p_data,
      summary   = COALESCE(p_summary, summary),
      form_date = p_job_date,
      technician_name = COALESCE(v_tech_name, technician_name),
      submitted_by = COALESCE(p_tech_id, submitted_by),
      status = p_status,
      encircle_claim_id = p_encircle_claim_id,
      encircle_note_id = COALESCE(p_encircle_note_id, encircle_note_id),
      encircle_synced_at = CASE
        WHEN p_encircle_note_id IS NOT NULL AND encircle_synced_at IS NULL THEN now()
        ELSE encircle_synced_at
      END,
      email_sent = CASE
        WHEN p_email_sent IS NOT NULL THEN p_email_sent
        ELSE email_sent
      END,
      email_sent_at = CASE
        WHEN p_email_sent = true AND email_sent_at IS NULL THEN now()
        ELSE email_sent_at
      END,
      job_id = COALESCE(p_job_id, job_id),
      updated_at = now()
    WHERE id = p_id AND form_type = 'demo_sheet'
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: save_estimate_lines(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_estimate_lines(p_id uuid, p_lines jsonb DEFAULT '[]'::jsonb, p_kind text DEFAULT 'estimate'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'save_estimate_lines: p_id is required';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('estimate', 'invoice') THEN
    RAISE EXCEPTION 'save_estimate_lines: p_kind must be ''estimate'' or ''invoice'' (got %)', p_kind;
  END IF;

  IF p_kind = 'estimate' THEN
    DELETE FROM public.estimate_line_items WHERE estimate_id = p_id;

    INSERT INTO public.estimate_line_items
      (estimate_id, description, xactimate_code, quantity, unit, unit_price,
       qbo_item_id, qbo_item_name, qbo_class_id, qbo_class_name, sort_order)
    SELECT
      p_id,
      COALESCE(elem->>'description', ''),
      elem->>'xactimate_code',
      COALESCE(NULLIF(elem->>'quantity', '')::numeric, 1),
      elem->>'unit',
      COALESCE(NULLIF(elem->>'unit_price', '')::numeric, 0),
      elem->>'qbo_item_id',
      elem->>'qbo_item_name',
      elem->>'qbo_class_id',
      elem->>'qbo_class_name',
      COALESCE(NULLIF(elem->>'sort_order', '')::int, (n - 1)::int)
    FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb)) WITH ORDINALITY AS arr(elem, n);

    SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.sort_order, e.created_at), '[]'::jsonb)
      INTO v_result
      FROM public.estimate_line_items e
     WHERE e.estimate_id = p_id;
  ELSE
    DELETE FROM public.invoice_line_items WHERE invoice_id = p_id;

    INSERT INTO public.invoice_line_items
      (invoice_id, description, xactimate_code, quantity, unit, unit_price,
       qbo_item_id, qbo_item_name, qbo_class_id, qbo_class_name, sort_order)
    SELECT
      p_id,
      COALESCE(elem->>'description', ''),
      elem->>'xactimate_code',
      COALESCE(NULLIF(elem->>'quantity', '')::numeric, 1),
      elem->>'unit',
      COALESCE(NULLIF(elem->>'unit_price', '')::numeric, 0),
      elem->>'qbo_item_id',
      elem->>'qbo_item_name',
      elem->>'qbo_class_id',
      elem->>'qbo_class_name',
      COALESCE(NULLIF(elem->>'sort_order', '')::int, (n - 1)::int)
    FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb)) WITH ORDINALITY AS arr(elem, n);

    SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.sort_order, e.created_at), '[]'::jsonb)
      INTO v_result
      FROM public.invoice_line_items e
     WHERE e.invoice_id = p_id;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: save_homebuilding_build_project(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_homebuilding_build_project(p_id uuid, p_label text, p_region text, p_spec jsonb, p_plan jsonb) RETURNS public.homebuilding_build_projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.homebuilding_build_projects;
begin
  if p_id is null then
    insert into public.homebuilding_build_projects(label, region, spec, plan)
    values (coalesce(nullif(trim(p_label), ''), 'Untitled build'), coalesce(p_region, 'wasatch'),
            coalesce(p_spec, '{}'::jsonb), coalesce(p_plan, '{}'::jsonb))
    returning * into r;
  else
    update public.homebuilding_build_projects
       set label = coalesce(nullif(trim(p_label), ''), label),
           region = coalesce(p_region, region),
           spec = coalesce(p_spec, spec),
           plan = coalesce(p_plan, plan),
           updated_at = now()
     where id = p_id
    returning * into r;
  end if;
  return r;
end; $$;


