--
-- Name: scan_abandoned_clocks(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scan_abandoned_clocks(p_now timestamp with time zone DEFAULT now(), p_threshold_minutes integer DEFAULT 600) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_count int := 0; v_emp text; v_mins int;
BEGIN
  FOR r IN
    SELECT e.id, e.employee_id, e.job_id, e.travel_start
    FROM job_time_entries e
    WHERE e.clock_out IS NULL
      AND e.travel_start IS NOT NULL
      AND e.travel_start <= p_now - make_interval(mins => p_threshold_minutes)
      AND NOT EXISTS (
        SELECT 1 FROM system_events se
        WHERE se.event_type = 'clock.abandoned'
          AND se.entity_type = 'job_time_entry'
          AND se.entity_id = e.id
      )
  LOOP
    SELECT full_name INTO v_emp FROM employees WHERE id = r.employee_id;
    v_mins := floor(extract(epoch FROM (p_now - r.travel_start)) / 60);
    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, job_id, payload)
    VALUES ('clock.abandoned', 'job_time_entry', r.id, NULL, r.job_id,
            jsonb_build_object('employee_id', r.employee_id, 'minutes', v_mins));
    PERFORM notify_emit('clock.abandoned', jsonb_build_object(
      'title', coalesce(v_emp, 'A tech') || ' may have forgotten to clock out',
      'body', 'On the clock for ' || round(v_mins / 60.0, 1) || 'h with no clock-out.',
      'link', '/time-tracking',
      'entity_type', 'job_time_entry',
      'entity_id', r.id,
      'job_id', r.job_id,
      'payload', jsonb_build_object('employee_id', r.employee_id, 'minutes', v_mins)
    ));
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END; $$;


--
-- Name: score_lead(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.score_lead(p_lead_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead        inbound_leads;
  v_channel     text;
  v_first_touch numeric;
  v_source_pts  int;
  v_engage_pts  int;
  v_speed_pts   int;
  v_sent_pts    int;
  v_topic_pts   int;
  v_label       text;
  v_urgent      boolean;
  v_total       int;
BEGIN
  SELECT * INTO v_lead FROM inbound_leads WHERE id = p_lead_id;
  IF v_lead.id IS NULL THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  DELETE FROM lead_score_factors WHERE lead_id = p_lead_id;

  IF COALESCE(v_lead.spam_flag, false) THEN
    INSERT INTO lead_score_factors (lead_id, org_id, factor, points, detail)
    VALUES (p_lead_id, v_lead.org_id, 'spam', 0, jsonb_build_object('spam', true));
    UPDATE inbound_leads SET lead_score = 0, updated_at = now() WHERE id = p_lead_id;
    RETURN 0;
  END IF;

  v_channel := crm_channel_for_source(v_lead.source);
  v_source_pts := CASE v_channel
    WHEN 'referral'   THEN 20
    WHEN 'insurance'  THEN 18
    WHEN 'google_ads' THEN 15
    WHEN 'organic'    THEN 10
    WHEN 'meta_ads'   THEN 8
    ELSE 5
  END;

  IF v_lead.source_type = 'call' THEN
    v_engage_pts := CASE
      WHEN COALESCE(v_lead.duration_sec, 0) >= 120 THEN 20
      WHEN COALESCE(v_lead.duration_sec, 0) >= 60  THEN 12
      WHEN COALESCE(v_lead.duration_sec, 0) >= 20  THEN 6
      ELSE 0
    END;
  ELSIF v_lead.source_type = 'form' THEN
    v_engage_pts := 10;
  ELSE
    v_engage_pts := 5;
  END IF;

  IF v_lead.source_type = 'call' AND COALESCE(v_lead.duration_sec, 0) > 0 THEN
    v_first_touch := 0;
  ELSE
    BEGIN
      SELECT EXTRACT(EPOCH FROM (MIN(m.created_at) - COALESCE(v_lead.occurred_at, v_lead.created_at))) / 60.0
        INTO v_first_touch
      FROM messages m
      JOIN conversation_participants cp ON cp.conversation_id = m.conversation_id
      WHERE cp.contact_id = v_lead.contact_id
        AND m.sender_contact_id IS NULL
        AND m.created_at >= COALESCE(v_lead.occurred_at, v_lead.created_at);
    EXCEPTION WHEN OTHERS THEN
      v_first_touch := NULL;
    END;
  END IF;

  v_speed_pts := CASE
    WHEN v_first_touch IS NULL OR v_first_touch < 0 THEN 0
    WHEN v_first_touch <= 5    THEN 15
    WHEN v_first_touch <= 30   THEN 10
    WHEN v_first_touch <= 120  THEN 5
    WHEN v_first_touch <= 1440 THEN 2
    ELSE 0
  END;

  v_label := v_lead.transcript_analysis -> 'sentiment' ->> 'label';
  v_sent_pts := CASE v_label WHEN 'positive' THEN 15 WHEN 'neutral' THEN 5 ELSE 0 END;

  v_urgent := EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(COALESCE(v_lead.transcript_analysis -> 'topics', '[]'::jsonb)) AS t(topic)
    WHERE t.topic ~* '(water|flood|fire|smoke|mold|sewage|storm|leak|burst|emergenc|damage|restorat|asbestos|hail|wind)'
  );
  v_topic_pts := CASE WHEN v_urgent THEN 15 ELSE 0 END;

  INSERT INTO lead_score_factors (lead_id, org_id, factor, points, detail) VALUES
    (p_lead_id, v_lead.org_id, 'source', v_source_pts,
       jsonb_build_object('channel', v_channel, 'source', v_lead.source)),
    (p_lead_id, v_lead.org_id, 'engagement', v_engage_pts,
       jsonb_build_object('source_type', v_lead.source_type, 'duration_sec', v_lead.duration_sec)),
    (p_lead_id, v_lead.org_id, 'speed_to_first_touch', v_speed_pts,
       jsonb_build_object('first_touch_minutes', v_first_touch)),
    (p_lead_id, v_lead.org_id, 'sentiment', v_sent_pts,
       jsonb_build_object('label', v_label)),
    (p_lead_id, v_lead.org_id, 'topics', v_topic_pts,
       jsonb_build_object('urgent', v_urgent));

  v_total := GREATEST(0, LEAST(100, v_source_pts + v_engage_pts + v_speed_pts + v_sent_pts + v_topic_pts));
  UPDATE inbound_leads SET lead_score = v_total, updated_at = now() WHERE id = p_lead_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_scored', 'inbound_lead', p_lead_id,
          jsonb_build_object('score', v_total, 'channel', v_channel));

  RETURN v_total;
END;
$$;


--
-- Name: search_contacts_for_job(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_contacts_for_job(p_query text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  q text;
BEGIN
  q := '%' || lower(trim(p_query)) || '%';

  SELECT jsonb_agg(to_jsonb(r))
  INTO result
  FROM (
    SELECT
      c.id, c.name, c.phone, c.email, c.company, c.role,
      c.billing_address, c.billing_city, c.billing_state, c.billing_zip,
      c.insurance_carrier, c.policy_number,
      (SELECT count(*) FROM contact_jobs cj WHERE cj.contact_id = c.id)::int AS job_count
    FROM contacts c
    WHERE c.role IN ('homeowner', 'tenant', 'property_manager')
      AND (
        lower(c.name) LIKE q
        OR c.phone LIKE q
        OR lower(COALESCE(c.email, '')) LIKE q
        OR lower(COALESCE(c.billing_address, '')) LIKE q
        OR lower(COALESCE(c.company, '')) LIKE q
      )
    ORDER BY c.name ASC
    LIMIT 20
  ) r;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: crm_automations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_automations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    trigger_event_type text NOT NULL,
    conditions jsonb DEFAULT '[]'::jsonb NOT NULL,
    actions jsonb DEFAULT '[]'::jsonb NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: set_automation_enabled(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_automation_enabled(p_id uuid, p_enabled boolean) RETURNS public.crm_automations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row crm_automations;
BEGIN
  SELECT * INTO v_row FROM crm_automations WHERE id = p_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'automation % not found', p_id; END IF;
  IF COALESCE(p_enabled, false) AND crm_fixed_automation_conflict(v_row.org_id, v_row.trigger_event_type) THEN
    RAISE EXCEPTION 'trigger "%" is already handled by an enabled fixed automation — disable one of them first (S1 collision guard)', v_row.trigger_event_type;
  END IF;
  UPDATE crm_automations SET enabled = COALESCE(p_enabled, enabled), updated_at = now()
  WHERE id = p_id RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: set_automation_setting(text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_automation_setting(p_key text, p_value boolean, p_org_id uuid DEFAULT NULL::uuid) RETURNS public.automation_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_row automation_settings;
  v_actor uuid;
BEGIN
  IF p_key NOT IN (
    'sms_sending_enabled', 'speed_to_lead_enabled', 'missed_call_textback_enabled',
    'no_response_followup_enabled', 'review_request_enabled'
  ) THEN
    RAISE EXCEPTION 'set_automation_setting: invalid key %', p_key;
  END IF;

  IF p_key = 'sms_sending_enabled' THEN
    IF NOT EXISTS (
      SELECT 1 FROM employees
      WHERE auth_user_id = auth.uid()
        AND role = 'admin'
        AND is_active
        AND NOT is_external
    ) THEN
      RAISE EXCEPTION 'NOT_AUTHORIZED: sms_sending_enabled is admin only'
        USING errcode = '42501';
    END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM employees
      WHERE auth_user_id = auth.uid()
        AND role IN ('admin', 'office')
        AND is_active
        AND NOT is_external
    ) THEN
      RAISE EXCEPTION 'NOT_AUTHORIZED: admin or office only'
        USING errcode = '42501';
    END IF;
  END IF;

  v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'set_automation_setting: no org resolved';
  END IF;

  INSERT INTO automation_settings (org_id) VALUES (v_org) ON CONFLICT (org_id) DO NOTHING;

  EXECUTE format(
    'UPDATE automation_settings SET %I = $1, updated_at = now() WHERE org_id = $2 RETURNING *', p_key
  ) INTO v_row USING p_value, v_org;

  SELECT e.id INTO v_actor FROM employees e WHERE e.auth_user_id = auth.uid();

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES (
    'automation_setting_changed',
    'automation_settings',
    v_org,
    v_actor,
    jsonb_build_object(
      'key', p_key,
      'value', p_value,
      'org_id', v_org,
      'actor_auth_uid', auth.uid(),
      'armed_state', CASE
        WHEN p_key = 'sms_sending_enabled' AND p_value THEN to_jsonb(v_row)
        ELSE NULL
      END
    )
  );

  RETURN v_row;
END;
$_$;


--
-- Name: set_billing_setting(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_billing_setting(p_key text, p_value text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.p9_assert_admin();

  IF p_key NOT IN (
    'accept_card','accept_ach','default_terms','surcharge_enabled','surcharge_pct',
    'qbo_stripe_clearing_account_id','qbo_stripe_clearing_account_name',
    'qbo_fee_expense_account_id','qbo_fee_expense_account_name',
    'qbo_bank_account_id','qbo_bank_account_name'
  ) THEN
    RAISE EXCEPTION 'Not an editable billing setting: %', p_key;
  END IF;
  INSERT INTO integration_config (key, value, updated_at)
  VALUES (p_key, p_value, now())
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
END;
$$;


--
-- Name: set_campaign_exclusions(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_campaign_exclusions(p_campaign_id uuid, p_contact_ids uuid[] DEFAULT ARRAY[]::uuid[]) RETURNS public.email_campaigns
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_campaign email_campaigns;
  v_count    int;
  v_row      email_campaigns;
BEGIN
  SELECT * INTO v_campaign FROM email_campaigns WHERE id = p_campaign_id;
  IF v_campaign IS NULL THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF v_campaign.status <> 'draft' THEN
    RAISE EXCEPTION 'Campaign is % — exclusions can only be set on a draft', v_campaign.status;
  END IF;
  DELETE FROM email_campaign_exclusions WHERE campaign_id = p_campaign_id;
  INSERT INTO email_campaign_exclusions (campaign_id, contact_id)
  SELECT p_campaign_id, x FROM unnest(p_contact_ids) x
  ON CONFLICT (campaign_id, contact_id) DO NOTHING;
  SELECT count(*) INTO v_count
  FROM preview_email_audience(v_campaign.audience_filter, v_campaign.org_id) a
  WHERE NOT EXISTS (
    SELECT 1 FROM email_campaign_exclusions ex
    WHERE ex.campaign_id = p_campaign_id AND ex.contact_id = a.contact_id
  );
  UPDATE email_campaigns SET audience_count = v_count, updated_at = now()
    WHERE id = p_campaign_id
    RETURNING * INTO v_row;
  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_email_campaign_exclusions_set', 'email_campaign', p_campaign_id,
    jsonb_build_object(
      'campaign_id', p_campaign_id,
      'excluded_count', COALESCE(array_length(p_contact_ids, 1), 0),
      'audience_count', v_count));
  RETURN v_row;
END;
$$;


--
-- Name: set_contact_lifecycle(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contact_lifecycle(p_contact_id uuid, p_lifecycle_status text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_prev text; v_row contacts; v_status text;
BEGIN
  v_status := NULLIF(btrim(COALESCE(p_lifecycle_status, '')), '');
  IF v_status IS NOT NULL AND v_status NOT IN ('lead', 'prospect', 'customer', 'past_customer', 'archived') THEN
    RAISE EXCEPTION 'Invalid lifecycle_status: %', v_status;
  END IF;
  SELECT lifecycle_status INTO v_prev FROM contacts WHERE id = p_contact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contact not found'; END IF;
  UPDATE contacts SET lifecycle_status = v_status, updated_at = now()
    WHERE id = p_contact_id RETURNING * INTO v_row;
  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_contact_lifecycle_set', 'contact', p_contact_id, p_actor_id,
    jsonb_build_object('lifecycle_status', v_status, 'previous_status', v_prev));
  RETURN v_row;
END;
$$;


--
-- Name: set_contact_owner(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contact_owner(p_contact_id uuid, p_owner_id uuid, p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_prev uuid; v_row contacts;
BEGIN
  SELECT owner_id INTO v_prev FROM contacts WHERE id = p_contact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contact not found'; END IF;
  IF p_owner_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM employees WHERE id = p_owner_id) THEN
    RAISE EXCEPTION 'Owner (employee) not found: %', p_owner_id;
  END IF;
  UPDATE contacts SET owner_id = p_owner_id, updated_at = now()
    WHERE id = p_contact_id RETURNING * INTO v_row;
  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_contact_owner_set', 'contact', p_contact_id, p_actor_id,
    jsonb_build_object('owner_id', p_owner_id, 'previous_owner_id', v_prev));
  RETURN v_row;
END;
$$;


--
-- Name: crm_build_phases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_build_phases (
    phase_key text NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'planned'::text NOT NULL,
    shipped_at timestamp with time zone,
    sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT crm_build_phases_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'in_progress'::text, 'shipped'::text])))
);


--
-- Name: set_crm_phase_status(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_crm_phase_status(p_phase_key text, p_status text) RETURNS public.crm_build_phases
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row crm_build_phases;
BEGIN
  IF p_status NOT IN ('planned', 'in_progress', 'shipped') THEN
    RAISE EXCEPTION 'invalid crm phase status: %', p_status;
  END IF;

  UPDATE crm_build_phases
     SET status     = p_status,
         shipped_at = CASE WHEN p_status = 'shipped' THEN now() ELSE shipped_at END
   WHERE phase_key = p_phase_key
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown crm phase_key: %', p_phase_key;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: crm_build_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_build_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    phase_key text NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'todo'::text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT crm_build_stages_status_check CHECK ((status = ANY (ARRAY['todo'::text, 'in_progress'::text, 'done'::text])))
);


--
-- Name: set_crm_stage_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_crm_stage_status(p_stage_id uuid, p_status text) RETURNS public.crm_build_stages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row crm_build_stages;
BEGIN
  IF p_status NOT IN ('todo', 'in_progress', 'done') THEN
    RAISE EXCEPTION 'invalid crm stage status: %', p_status;
  END IF;

  UPDATE crm_build_stages
     SET status = p_status
   WHERE id = p_stage_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown crm stage id: %', p_stage_id;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: notification_employee_overrides; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_employee_overrides (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    type_key text NOT NULL,
    channel text NOT NULL,
    enabled boolean NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT notification_employee_overrides_channel_check CHECK ((channel = ANY (ARRAY['bell'::text, 'push'::text, 'email'::text])))
);


--
-- Name: set_employee_notification_override(uuid, text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_employee_notification_override(p_employee_id uuid, p_type_key text, p_channel text, p_enabled boolean, p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.notification_employee_overrides
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.notification_employee_overrides;
  v_actor uuid;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  SELECT e.id INTO v_actor FROM public.employees e WHERE e.auth_user_id = auth.uid();

  INSERT INTO public.notification_employee_overrides
    (employee_id, type_key, channel, enabled, updated_at, updated_by)
  VALUES
    (p_employee_id, p_type_key, p_channel, p_enabled, now(), COALESCE(v_actor, p_actor_id))
  ON CONFLICT (employee_id, type_key, channel) DO UPDATE
    SET enabled    = EXCLUDED.enabled,
        updated_at = now(),
        updated_by = COALESCE(v_actor, p_actor_id)
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: set_integration_secret(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_integration_secret(p_provider text, p_secret text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.p9_assert_admin();

  IF p_provider NOT IN ('stripe', 'twilio', 'resend') THEN
    RAISE EXCEPTION 'INVALID_PROVIDER: %', p_provider USING errcode = '22023';
  END IF;
  IF p_secret IS NULL OR btrim(p_secret) = '' THEN
    RAISE EXCEPTION 'EMPTY_SECRET' USING errcode = '22023';
  END IF;

  INSERT INTO integration_credentials (provider, access_token, environment,
                                       connected_by, connected_at, updated_at)
  VALUES (p_provider, p_secret, 'production',
          (SELECT id FROM employees WHERE auth_user_id = auth.uid() LIMIT 1),
          now(), now())
  ON CONFLICT (provider) DO UPDATE
    SET access_token = EXCLUDED.access_token,
        connected_by = EXCLUDED.connected_by,
        connected_at = COALESCE(integration_credentials.connected_at, EXCLUDED.connected_at),
        updated_at   = now();
END;
$$;


