--
-- Name: set_job_real_job(uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_job_real_job(p_job_id uuid, p_is_real boolean, p_actor uuid DEFAULT NULL::uuid) RETURNS public.jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE r public.jobs;
BEGIN
  IF p_is_real THEN
    UPDATE public.jobs
       SET is_real_job        = true,
           real_job_source    = 'manual',
           real_job_marked_at = now(),
           updated_by         = COALESCE(p_actor, updated_by)
     WHERE id = p_job_id
     RETURNING * INTO r;
  ELSE
    UPDATE public.jobs
       SET is_real_job = false,
           updated_by  = COALESCE(p_actor, updated_by)
     WHERE id = p_job_id
     RETURNING * INTO r;
  END IF;
  RETURN r;
END; $$;


--
-- Name: set_lead_caller_name(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lead_caller_name(p_lead_id uuid, p_name text, p_allow_upgrade boolean DEFAULT false) RETURNS public.inbound_leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row       inbound_leads;
  v_touched   inbound_leads;
  v_name      text := NULLIF(btrim(p_name), '');
  v_current   text;
  v_upgrade   boolean;
  v_canonical uuid;
  v_merged    uuid;
  v_hops      integer := 0;
  v_targets   uuid[];
  v_target    uuid;
BEGIN
  IF v_name IS NULL THEN
    SELECT * INTO v_row FROM inbound_leads WHERE id = p_lead_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
    END IF;
    RETURN v_row;
  END IF;

  PERFORM 1 FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  -- Resolve the canonical root: the AI names the row whose recording it read,
  -- but only the canonical owns a pipeline card. Bounded walk, identical to
  -- crm_advance_lead_if_forward's.
  v_canonical := p_lead_id;
  LOOP
    SELECT merged_into_lead_id INTO v_merged FROM inbound_leads WHERE id = v_canonical;
    EXIT WHEN v_merged IS NULL OR v_hops >= 5;
    v_canonical := v_merged;
    v_hops := v_hops + 1;
  END LOOP;

  v_targets := ARRAY[p_lead_id];
  IF v_canonical <> p_lead_id THEN
    v_targets := v_targets || v_canonical;
  END IF;

  FOREACH v_target IN ARRAY v_targets LOOP
    SELECT caller_name INTO v_current FROM inbound_leads WHERE id = v_target;

    v_upgrade := p_allow_upgrade
      AND v_current IS NOT NULL AND btrim(v_current) <> ''
      AND left(lower(v_name), length(btrim(v_current)) + 1) = lower(btrim(v_current)) || ' '
      AND lower(v_name) <> lower(btrim(v_current));

    IF v_upgrade THEN
      UPDATE inbound_leads
         SET caller_name = v_name,
             updated_at  = now()
       WHERE id = v_target
       RETURNING * INTO v_touched;
    ELSE
      UPDATE inbound_leads
         SET caller_name = COALESCE(NULLIF(btrim(caller_name), ''), v_name),
             updated_at  = now()
       WHERE id = v_target
       RETURNING * INTO v_touched;
    END IF;

    IF v_touched.contact_id IS NOT NULL THEN
      IF v_upgrade THEN
        UPDATE contacts
           SET name = v_name
         WHERE id = v_touched.contact_id
           AND COALESCE(NULLIF(btrim(name), ''), '') <> ''
           AND left(lower(v_name), length(btrim(name)) + 1) = lower(btrim(name)) || ' ';
      ELSE
        UPDATE contacts
           SET name = v_name
         WHERE id = v_touched.contact_id
           AND COALESCE(NULLIF(btrim(name), ''), '') = '';
      END IF;
    END IF;

    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
    VALUES ('crm_lead_caller_named', 'inbound_lead', v_touched.id, NULL,
            jsonb_build_object('name', v_name, 'contact_id', v_touched.contact_id,
                               'upgraded', v_upgrade,
                               'via_merge', v_target <> p_lead_id));

    IF v_target = p_lead_id THEN
      v_row := v_touched;
    END IF;
  END LOOP;

  RETURN v_row;
END;
$$;


--
-- Name: set_lead_contact_details(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lead_contact_details(p_lead_id uuid, p_email text DEFAULT NULL::text, p_address text DEFAULT NULL::text) RETURNS public.contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact_id uuid;
  v_row        contacts;
  v_email      text := NULLIF(btrim(p_email), '');
  v_address    text := NULLIF(btrim(p_address), '');
BEGIN
  IF v_email IS NULL AND v_address IS NULL THEN
    SELECT contact_id INTO v_contact_id FROM inbound_leads WHERE id = p_lead_id;
    IF v_contact_id IS NOT NULL THEN
      SELECT * INTO v_row FROM contacts WHERE id = v_contact_id;
    END IF;
    RETURN v_row;
  END IF;

  SELECT contact_id INTO v_contact_id FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  IF v_contact_id IS NULL THEN
    RETURN NULL; -- no linked contact yet — nowhere to write this, never create one
  END IF;

  UPDATE contacts
     SET email          = COALESCE(NULLIF(btrim(email), ''), v_email),
         billing_address = COALESCE(NULLIF(btrim(billing_address), ''), v_address),
         updated_at      = now()
   WHERE id = v_contact_id
   RETURNING * INTO v_row;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_contact_details_backfilled', 'contact', v_contact_id, NULL,
          jsonb_build_object('lead_id', p_lead_id, 'email_provided', v_email IS NOT NULL, 'address_provided', v_address IS NOT NULL));

  RETURN v_row;
END;
$$;


--
-- Name: set_lead_details(uuid, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lead_details(p_lead_id uuid, p_notes text, p_value numeric, p_updated_by uuid DEFAULT NULL::uuid) RETURNS public.inbound_leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row inbound_leads;
BEGIN
  UPDATE inbound_leads
     SET notes      = NULLIF(btrim(p_notes), ''),
         value      = p_value,
         updated_at = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_details_updated', 'inbound_lead', v_row.id, p_updated_by,
          jsonb_build_object('value', v_row.value, 'has_notes', (v_row.notes IS NOT NULL)));

  RETURN v_row;
END;
$$;


--
-- Name: set_lead_spam_flag(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lead_spam_flag(p_lead_id uuid, p_spam boolean, p_reason text DEFAULT NULL::text) RETURNS public.inbound_leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row  inbound_leads;
  v_prev boolean;
BEGIN
  SELECT spam_flag INTO v_prev FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  UPDATE inbound_leads
     SET spam_flag  = p_spam,
         updated_at = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF COALESCE(v_prev, false) IS DISTINCT FROM p_spam THEN
    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
    VALUES ('crm_lead_spam_flag_set', 'inbound_lead', v_row.id, NULL,
            jsonb_build_object('spam_flag', p_spam, 'reason', p_reason));
  END IF;

  IF p_spam THEN
    DELETE FROM lead_pipeline_stage WHERE lead_id = p_lead_id;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: set_lead_transcription(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lead_transcription(p_lead_id uuid, p_transcription text, p_source text DEFAULT 'deepgram'::text, p_analysis jsonb DEFAULT NULL::jsonb) RETURNS public.inbound_leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row inbound_leads;
BEGIN
  UPDATE inbound_leads
     SET transcription        = p_transcription,
         transcription_source = p_source,
         transcript_analysis  = COALESCE(p_analysis, transcript_analysis),
         transcribed_at       = now(),
         updated_at           = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_call_transcribed', 'inbound_lead', v_row.id, NULL,
          jsonb_build_object(
            'source', p_source,
            'chars', length(COALESCE(p_transcription, '')),
            'has_analysis', (p_analysis IS NOT NULL)
          ));

  RETURN v_row;
END;
$$;


--
-- Name: notification_prefs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_prefs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    type_key text NOT NULL,
    channel text NOT NULL,
    enabled boolean NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notification_prefs_channel_check CHECK ((channel = ANY (ARRAY['bell'::text, 'push'::text, 'email'::text])))
);

ALTER TABLE ONLY public.notification_prefs FORCE ROW LEVEL SECURITY;


--
-- Name: set_my_notification_pref(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_notification_pref(p_employee_id uuid, p_type_key text, p_channel text, p_enabled boolean) RETURNS public.notification_prefs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_customizable boolean;
  v_row public.notification_prefs;
BEGIN
  IF NOT COALESCE(
       (SELECT auth.jwt() ->> 'role' = 'service_role'),
       false
     )
     AND NOT public.is_current_native_push_preferences_employee(p_employee_id) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: own notification preferences only'
      USING errcode = '42501';
  END IF;

  IF p_channel NOT IN ('bell', 'push', 'email') THEN
    RAISE EXCEPTION 'invalid channel: %', p_channel;
  END IF;

  SELECT employee.role::text
  INTO v_role
  FROM public.employees employee
  WHERE employee.id = p_employee_id;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'unknown employee: %', p_employee_id;
  END IF;

  SELECT role_default.user_customizable
  INTO v_customizable
  FROM public.notification_role_defaults role_default
  WHERE role_default.role = v_role
    AND role_default.type_key = p_type_key
    AND role_default.channel = p_channel;

  IF v_customizable IS FALSE THEN
    RAISE EXCEPTION
      'notification preference locked by an administrator (% / %)',
      p_type_key,
      p_channel;
  END IF;

  INSERT INTO public.notification_prefs (
    employee_id,
    type_key,
    channel,
    enabled
  )
  VALUES (
    p_employee_id,
    p_type_key,
    p_channel,
    p_enabled
  )
  ON CONFLICT (employee_id, type_key, channel)
  DO UPDATE SET
    enabled = EXCLUDED.enabled,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: notification_role_defaults; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_role_defaults (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    role text NOT NULL,
    type_key text NOT NULL,
    channel text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    user_customizable boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT notification_role_defaults_channel_check CHECK ((channel = ANY (ARRAY['bell'::text, 'push'::text, 'email'::text])))
);


--
-- Name: set_notification_default(text, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notification_default(p_role text, p_type_key text, p_channel text, p_enabled boolean, p_user_customizable boolean DEFAULT NULL::boolean) RETURNS public.notification_role_defaults
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.notification_role_defaults;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  INSERT INTO public.notification_role_defaults
    (role, type_key, channel, enabled, user_customizable, updated_at)
  VALUES
    (p_role, p_type_key, p_channel, p_enabled, COALESCE(p_user_customizable, true), now())
  ON CONFLICT (role, type_key, channel) DO UPDATE
    SET enabled           = EXCLUDED.enabled,
        user_customizable = COALESCE(p_user_customizable,
                                     public.notification_role_defaults.user_customizable),
        updated_at        = now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: crm_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    title text NOT NULL,
    notes text,
    status text DEFAULT 'open'::text NOT NULL,
    due_at timestamp with time zone,
    remind_at timestamp with time zone,
    assignee_id uuid,
    contact_id uuid,
    lead_id uuid,
    completed_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text])))
);


--
-- Name: set_task_status(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_task_status(p_task_id uuid, p_status text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.crm_tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text := lower(btrim(p_status));
  v_row    crm_tasks;
BEGIN
  IF v_status NOT IN ('open', 'done') THEN
    RAISE EXCEPTION 'invalid task status: % (expected open or done)', p_status;
  END IF;
  UPDATE crm_tasks SET
    status = v_status,
    completed_at = CASE WHEN v_status = 'done' THEN now() ELSE NULL END,
    updated_at = now()
  WHERE id = p_task_id
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'unknown crm_tasks id: %', p_task_id; END IF;
  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_task_status_changed', 'crm_task', v_row.id, p_actor_id, jsonb_build_object('status', v_status));
  RETURN v_row;
END;
$$;


--
-- Name: crm_tracking_numbers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_tracking_numbers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    tracking_number text NOT NULL,
    label text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: set_tracking_number_label(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tracking_number_label(p_tracking_number text, p_label text) RETURNS public.crm_tracking_numbers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := (SELECT id FROM crm_orgs ORDER BY created_at LIMIT 1);
  v_row crm_tracking_numbers;
BEGIN
  IF NULLIF(btrim(p_tracking_number), '') IS NULL THEN
    RAISE EXCEPTION 'tracking_number is required';
  END IF;

  INSERT INTO crm_tracking_numbers (org_id, tracking_number, label)
  VALUES (v_org, btrim(p_tracking_number), NULLIF(btrim(p_label), ''))
  ON CONFLICT (org_id, tracking_number)
  DO UPDATE SET label = EXCLUDED.label, updated_at = now()
  RETURNING * INTO v_row;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_tracking_number_labeled', 'crm_tracking_number', v_row.id, NULL,
          jsonb_build_object('tracking_number', v_row.tracking_number, 'label', v_row.label));

  RETURN v_row;
END;
$$;


--
-- Name: set_twilio_config(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_twilio_config(p_account_sid text DEFAULT NULL::text, p_messaging_service_sid text DEFAULT NULL::text, p_phone_number text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.p9_assert_admin();

  IF p_account_sid IS NOT NULL THEN
    INSERT INTO integration_config (key, value) VALUES ('twilio_account_sid', NULLIF(btrim(p_account_sid), ''))
    ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  END IF;
  IF p_messaging_service_sid IS NOT NULL THEN
    INSERT INTO integration_config (key, value) VALUES ('twilio_messaging_service_sid', NULLIF(btrim(p_messaging_service_sid), ''))
    ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  END IF;
  IF p_phone_number IS NOT NULL THEN
    INSERT INTO integration_config (key, value) VALUES ('twilio_phone_number', NULLIF(btrim(p_phone_number), ''))
    ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  END IF;
END;
$$;


--
-- Name: submit_time_entry_change_request(uuid, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_time_entry_change_request(p_entry_id uuid, p_proposed jsonb, p_tech_note text, p_actor_id uuid) RETURNS public.time_entry_change_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_e job_time_entries%ROWTYPE; v_req time_entry_change_requests%ROWTYPE; v_emp text;
begin
  select * into v_e from job_time_entries where id=p_entry_id;
  if v_e.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
  if v_e.employee_id <> p_actor_id then raise exception 'NOT_OWNER' using errcode='P0001'; end if;
  insert into time_entry_change_requests (entry_id, requested_by, proposed, tech_note) values (p_entry_id, p_actor_id, coalesce(p_proposed,'{}'::jsonb), p_tech_note) returning * into v_req;
  select full_name into v_emp from employees where id=p_actor_id;
  perform notify_emit('timesheet.change_requested', jsonb_build_object(
    'title', 'Timesheet change requested',
    'body', coalesce(v_emp,'A tech')||' requested a correction to a time entry.',
    'link', '/time-tracking',
    'entity_type', 'time_entry_change_request',
    'entity_id', v_req.id,
    'job_id', v_e.job_id,
    'payload', jsonb_build_object('entry_id', p_entry_id, 'proposed', coalesce(p_proposed,'{}'::jsonb))
  ));
  return v_req;
end; $$;


--
-- Name: appointment_crew; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.appointment_crew (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    appointment_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    role public.crew_role DEFAULT 'tech'::public.crew_role NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: sync_appointment_crew(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_appointment_crew(p_appointment_id uuid, p_crew jsonb DEFAULT '[]'::jsonb) RETURNS SETOF public.appointment_crew
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_appointment_id IS NULL THEN
    RAISE EXCEPTION 'sync_appointment_crew: p_appointment_id is required';
  END IF;

  DELETE FROM public.appointment_crew WHERE appointment_id = p_appointment_id;

  RETURN QUERY
  INSERT INTO public.appointment_crew (appointment_id, employee_id, role)
  SELECT DISTINCT ON ((elem->>'employee_id')::uuid)
         p_appointment_id,
         (elem->>'employee_id')::uuid,
         NULLIF(elem->>'role', '')
  FROM jsonb_array_elements(COALESCE(p_crew, '[]'::jsonb)) AS elem
  WHERE COALESCE(elem->>'employee_id', '') <> ''
  RETURNING *;
END;
$$;


--
-- Name: sync_job_invoiced_from_invoices(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_job_invoiced_from_invoices(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
  v_sum   numeric;
  v_date  timestamptz;
BEGIN
  IF p_job_id IS NULL THEN RETURN; END IF;

  SELECT count(*),
         COALESCE(sum(COALESCE(adjusted_total, total)), 0),
         min(qbo_synced_at)
    INTO v_count, v_sum, v_date
    FROM invoices
   WHERE job_id = p_job_id
     AND qbo_invoice_id IS NOT NULL;

  -- Only write when the job actually has pushed invoices; never zero legacy values.
  IF v_count > 0 THEN
    UPDATE jobs
       SET invoiced_value = v_sum,
           invoiced_date  = COALESCE(invoiced_date, v_date::date),
           updated_at     = now()
     WHERE id = p_job_id;
  END IF;
END;
$$;


--
-- Name: sync_job_to_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_job_to_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Only sync if claim_id exists
  IF NEW.claim_id IS NULL THEN RETURN NEW; END IF;

  -- Sync insurance_company → claim.insurance_carrier (if claim's is null or job changed)
  IF NEW.insurance_company IS DISTINCT FROM OLD.insurance_company AND NEW.insurance_company IS NOT NULL THEN
    UPDATE claims SET insurance_carrier = NEW.insurance_company, updated_at = now()
    WHERE id = NEW.claim_id AND (insurance_carrier IS NULL OR insurance_carrier = OLD.insurance_company);
  END IF;

  -- Sync date_of_loss → claim.date_of_loss
  IF NEW.date_of_loss IS DISTINCT FROM OLD.date_of_loss AND NEW.date_of_loss IS NOT NULL THEN
    UPDATE claims SET date_of_loss = NEW.date_of_loss, updated_at = now()
    WHERE id = NEW.claim_id AND (date_of_loss IS NULL OR date_of_loss = OLD.date_of_loss);
  END IF;

  -- Sync address → claim loss_address
  IF NEW.address IS DISTINCT FROM OLD.address AND NEW.address IS NOT NULL THEN
    UPDATE claims SET loss_address = NEW.address, loss_city = NEW.city, loss_state = NEW.state, loss_zip = NEW.zip, updated_at = now()
    WHERE id = NEW.claim_id AND (loss_address IS NULL OR loss_address = OLD.address);
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: tech_hours_bucket(uuid, date, date, timestamp with time zone, public.job_time_entries); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tech_hours_bucket(p_employee_id uuid, p_start date, p_end date, p_now timestamp with time zone, p_open public.job_time_entries) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_onsite_stored numeric;
  v_travel_stored numeric;
  v_live_onsite   numeric := 0;
  v_live_travel   numeric := 0;
  v_onsite        numeric;
  v_travel        numeric;
BEGIN
  SELECT COALESCE(SUM(hours), 0), COALESCE(SUM(travel_minutes), 0) / 60.0
  INTO v_onsite_stored, v_travel_stored
  FROM job_time_entries
  WHERE employee_id = p_employee_id AND work_date BETWEEN p_start AND p_end;

  IF p_open.id IS NOT NULL AND p_open.work_date BETWEEN p_start AND p_end THEN
    IF p_open.clock_in IS NOT NULL THEN
      v_live_onsite := GREATEST(0,
        EXTRACT(EPOCH FROM (p_now - p_open.clock_in)) / 3600.0
        - COALESCE(p_open.total_paused_minutes, 0) / 60.0
        - CASE WHEN p_open.paused_at IS NOT NULL
               THEN EXTRACT(EPOCH FROM (p_now - p_open.paused_at)) / 3600.0 ELSE 0 END);
    ELSIF p_open.travel_start IS NOT NULL THEN
      v_live_travel := GREATEST(0, EXTRACT(EPOCH FROM (p_now - p_open.travel_start)) / 3600.0);
    END IF;
  END IF;

  v_onsite := ROUND((v_onsite_stored + v_live_onsite)::numeric, 2);
  v_travel := ROUND((v_travel_stored + v_live_travel)::numeric, 2);

  RETURN jsonb_build_object(
    'on_site', v_onsite,
    'travel', v_travel,
    'total', ROUND((v_onsite + v_travel)::numeric, 2)
  );
END;
$$;


--
-- Name: toggle_appointment_task(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_appointment_task(p_task_id uuid, p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_current boolean;
  result jsonb;
BEGIN
  SELECT is_completed INTO v_current FROM job_tasks WHERE id = p_task_id;

  IF v_current THEN
    UPDATE job_tasks SET is_completed = false, completed_by = NULL, completed_at = NULL
    WHERE id = p_task_id;
  ELSE
    UPDATE job_tasks SET is_completed = true, completed_by = p_employee_id, completed_at = now()
    WHERE id = p_task_id;
  END IF;

  SELECT jsonb_build_object(
    'id', jt.id, 'is_completed', jt.is_completed,
    'completed_by', jt.completed_by, 'completed_at', jt.completed_at,
    'completed_by_name', e.display_name
  ) INTO result
  FROM job_tasks jt
  LEFT JOIN employees e ON e.id = jt.completed_by
  WHERE jt.id = p_task_id;

  RETURN result;
END;
$$;


--
-- Name: toggle_job_task(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_job_task(p_task_id uuid, p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_current boolean;
  result jsonb;
BEGIN
  SELECT is_completed INTO v_current FROM job_tasks WHERE id = p_task_id;

  IF v_current THEN
    -- Un-complete: also unassign from appointment so it returns to pool
    UPDATE job_tasks SET is_completed = false, completed_by = NULL, completed_at = NULL, appointment_id = NULL
    WHERE id = p_task_id;
  ELSE
    UPDATE job_tasks SET is_completed = true, completed_by = p_employee_id, completed_at = now()
    WHERE id = p_task_id;
  END IF;

  SELECT jsonb_build_object(
    'id', jt.id, 'is_completed', jt.is_completed,
    'completed_by', jt.completed_by, 'completed_at', jt.completed_at,
    'completed_by_name', e.display_name
  ) INTO result
  FROM job_tasks jt
  LEFT JOIN employees e ON e.id = jt.completed_by
  WHERE jt.id = p_task_id;

  RETURN result;
END;
$$;


--
-- Name: trg_appt_calendar_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_appt_calendar_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email  TEXT;
  v_name   TEXT;
  v_cancel JSONB;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Tell the client only if they were actually confirmed for this appointment.
    IF OLD.kind = 'job' AND OLD.notify_client AND OLD.client_notified_at IS NOT NULL AND OLD.job_id IS NOT NULL THEN
      SELECT j.client_email, j.insured_name INTO v_email, v_name FROM jobs j WHERE j.id = OLD.job_id;
      IF v_email IS NOT NULL AND btrim(v_email) <> '' THEN
        v_cancel := jsonb_build_object('email', v_email, 'name', v_name,
          'date', OLD.date, 'time_start', OLD.time_start, 'time_end', OLD.time_end);
      END IF;
    END IF;
    PERFORM notify_google_calendar_sync(OLD.id, 'delete', v_cancel);
    RETURN OLD;
  END IF;

  -- Skip when nothing sync-relevant changed (e.g. the worker only stamped
  -- client_notified_at / client_time_sig, or notify_client was toggled).
  IF TG_OP = 'UPDATE' AND
     (NEW.title, NEW.date, NEW.time_start, NEW.time_end, NEW.notes, NEW.status, NEW.job_id, NEW.duration_days, NEW.is_private)
     IS NOT DISTINCT FROM
     (OLD.title, OLD.date, OLD.time_start, OLD.time_end, OLD.notes, OLD.status, OLD.job_id, OLD.duration_days, OLD.is_private)
  THEN
    RETURN NEW;
  END IF;

  PERFORM notify_google_calendar_sync(NEW.id, 'upsert', NULL);
  RETURN NEW;
END;
$$;


--
-- Name: trg_appt_crew_calendar_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_appt_crew_calendar_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM notify_google_calendar_sync(OLD.appointment_id, 'upsert');
    RETURN OLD;
  END IF;
  PERFORM notify_google_calendar_sync(NEW.appointment_id, 'upsert');
  RETURN NEW;
END;
$$;


--
-- Name: trg_appt_crew_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_appt_crew_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.notify_emit('appointment.assigned', jsonb_build_object(
    'appointment_id', NEW.appointment_id, 'employee_id', NEW.employee_id));
  RETURN NEW;
END; $$;


--
-- Name: trg_appt_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_appt_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM public.notify_emit('appointment.canceled', jsonb_build_object('appointment_id', NEW.id));
    RETURN NEW;
  END IF;
  IF (NEW.title, NEW.date, NEW.time_start, NEW.time_end, NEW.status, NEW.job_id)
     IS NOT DISTINCT FROM
     (OLD.title, OLD.date, OLD.time_start, OLD.time_end, OLD.status, OLD.job_id)
  THEN RETURN NEW; END IF;
  PERFORM public.notify_emit('appointment.updated', jsonb_build_object('appointment_id', NEW.id));
  RETURN NEW;
END; $$;


--
