--
-- Name: update_lead_status(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_lead_status(p_lead_id uuid, p_status text, p_notes text DEFAULT NULL::text, p_updated_by uuid DEFAULT NULL::uuid) RETURNS public.inbound_leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row inbound_leads;
BEGIN
  UPDATE inbound_leads
     SET lead_status = p_status,
         notes       = COALESCE(p_notes, notes),
         updated_at  = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_status_updated', 'inbound_lead', v_row.id, p_updated_by, jsonb_build_object('status', p_status));

  RETURN v_row;
END;
$$;


--
-- Name: update_reading(uuid, public.material_type, text, numeric, numeric, numeric, numeric, numeric, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_reading(p_reading_id uuid, p_material public.material_type, p_location text, p_mc numeric, p_rh numeric, p_temp_f numeric, p_gpp numeric, p_dew_point numeric, p_is_affected boolean, p_notes text, p_edited_by uuid) RETURNS public.moisture_readings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_taken_at TIMESTAMPTZ;
  result     moisture_readings;
BEGIN
  SELECT taken_at INTO v_taken_at FROM moisture_readings WHERE id = p_reading_id;
  IF v_taken_at IS NULL THEN
    RAISE EXCEPTION 'update_reading: reading % not found', p_reading_id;
  END IF;
  IF v_taken_at <= now() - interval '10 minutes' THEN
    RAISE EXCEPTION 'update_reading: edit window closed (readings are immutable after 10 minutes)';
  END IF;
  UPDATE moisture_readings
     SET material=p_material, location_description=p_location,
         mc_pct=p_mc, rh_pct=p_rh, temp_f=p_temp_f,
         gpp=p_gpp, dew_point_f=p_dew_point,
         is_affected=p_is_affected, notes=p_notes,
         edited_at=now(), edited_by=p_edited_by
   WHERE id = p_reading_id
  RETURNING * INTO result;
  RETURN result;
END;
$$;


