--
-- Name: update_tech_feedback(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_tech_feedback(p_id uuid, p_status text, p_admin_notes text DEFAULT NULL::text) RETURNS public.tech_feedback
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result tech_feedback;
BEGIN
  UPDATE tech_feedback
  SET status      = p_status,
      admin_notes = COALESCE(p_admin_notes, admin_notes),
      -- First transition into resolved/dismissed stamps resolved_at;
      -- terminal↔terminal keeps the original stamp (COALESCE); reopening
      -- NULLs it. attachments_purged_at is deliberately never touched here.
      resolved_at = CASE
        WHEN p_status IN ('resolved', 'dismissed') THEN COALESCE(resolved_at, now())
        ELSE NULL
      END
  WHERE id = p_id
  RETURNING * INTO result;
  RETURN result;
END;
$$;


