--
-- Name: upsert_ad_spend(text, text, text, date, numeric, integer, integer, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_ad_spend(p_platform text, p_campaign_id text, p_campaign_name text DEFAULT NULL::text, p_date date DEFAULT NULL::date, p_spend numeric DEFAULT 0, p_impressions integer DEFAULT NULL::integer, p_clicks integer DEFAULT NULL::integer, p_platform_conversions numeric DEFAULT NULL::numeric, p_org_id uuid DEFAULT NULL::uuid) RETURNS public.ad_spend
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_row    ad_spend;
BEGIN
  IF p_platform NOT IN ('google', 'meta') THEN
    RAISE EXCEPTION 'invalid ad_spend platform: %', p_platform;
  END IF;
  IF p_date IS NULL THEN
    RAISE EXCEPTION 'ad_spend date is required';
  END IF;

  -- Defaults to the real Utah Pros org; the dedicated "Utah Pros — TEST" org
  -- (Test-data isolation) is passed explicitly by tests/dev-mode syncs.
  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  INSERT INTO ad_spend (
    org_id, platform, campaign_id, campaign_name, date,
    spend, impressions, clicks, platform_conversions
  ) VALUES (
    v_org_id, p_platform, p_campaign_id, p_campaign_name, p_date,
    p_spend, p_impressions, p_clicks, p_platform_conversions
  )
  ON CONFLICT (platform, campaign_id, date) DO UPDATE SET
    campaign_name        = COALESCE(EXCLUDED.campaign_name, ad_spend.campaign_name),
    spend                = EXCLUDED.spend,
    impressions          = EXCLUDED.impressions,
    clicks               = EXCLUDED.clicks,
    platform_conversions = EXCLUDED.platform_conversions,
    updated_at           = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: upsert_appointment_task(uuid, uuid, text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_appointment_task(p_id uuid DEFAULT NULL::uuid, p_appointment_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_is_required boolean DEFAULT false, p_display_order integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb; task_id uuid;
BEGIN
  IF p_id IS NOT NULL THEN
    UPDATE appointment_tasks SET title = COALESCE(p_title, title), description = COALESCE(p_description, description),
      is_required = p_is_required, display_order = p_display_order WHERE id = p_id RETURNING id INTO task_id;
  ELSE
    INSERT INTO appointment_tasks (appointment_id, title, description, is_required, display_order)
    VALUES (p_appointment_id, p_title, p_description, p_is_required, p_display_order) RETURNING id INTO task_id;
  END IF;
  SELECT row_to_json(at2.*)::jsonb INTO result FROM appointment_tasks at2 WHERE at2.id = task_id;
  RETURN result;
END; $$;


--
-- Name: upsert_contact_address(uuid, uuid, text, text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_contact_address(p_contact_id uuid, p_address_id uuid DEFAULT NULL::uuid, p_label text DEFAULT 'service'::text, p_address text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_zip text DEFAULT NULL::text, p_is_billing boolean DEFAULT false, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  -- If marking as billing, unmark others first
  IF p_is_billing THEN
    UPDATE contact_addresses SET is_billing = false
    WHERE contact_id = p_contact_id AND is_billing = true;
  END IF;

  IF p_address_id IS NOT NULL THEN
    -- Update existing
    UPDATE contact_addresses SET
      label = COALESCE(p_label, label),
      address = COALESCE(p_address, address),
      city = p_city, state = p_state, zip = p_zip,
      is_billing = p_is_billing,
      notes = p_notes
    WHERE id = p_address_id AND contact_id = p_contact_id
    RETURNING id INTO v_id;
  ELSE
    -- Insert new
    INSERT INTO contact_addresses (contact_id, label, address, city, state, zip, is_billing, notes)
    VALUES (p_contact_id, p_label, p_address, p_city, p_state, p_zip, p_is_billing, p_notes)
    RETURNING id INTO v_id;
  END IF;

  -- Sync billing address back to contacts table for backward compat
  IF p_is_billing THEN
    UPDATE contacts SET
      billing_address = p_address, billing_city = p_city,
      billing_state = p_state, billing_zip = p_zip, updated_at = now()
    WHERE id = p_contact_id;
  END IF;

  RETURN jsonb_build_object('id', v_id, 'success', true);
END; $$;


--
-- Name: upsert_crm_automation(uuid, text, text, text, jsonb, jsonb, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_crm_automation(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_trigger_event_type text DEFAULT NULL::text, p_conditions jsonb DEFAULT '[]'::jsonb, p_actions jsonb DEFAULT '[]'::jsonb, p_enabled boolean DEFAULT NULL::boolean, p_org_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS public.crm_automations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id   uuid := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_name     text := nullif(btrim(p_name), '');
  v_trigger  text;
  v_enabled  boolean;
  v_existing crm_automations;
  v_row      crm_automations;
BEGIN
  IF p_id IS NULL THEN
    IF v_name IS NULL THEN RAISE EXCEPTION 'an automation name is required'; END IF;
    v_trigger := nullif(btrim(p_trigger_event_type), '');
    IF v_trigger IS NULL THEN RAISE EXCEPTION 'a trigger event type is required'; END IF;
    v_enabled := COALESCE(p_enabled, false);
    IF v_enabled AND crm_fixed_automation_conflict(v_org_id, v_trigger) THEN
      RAISE EXCEPTION 'trigger "%" is already handled by an enabled fixed automation — disable one of them first (S1 collision guard)', v_trigger;
    END IF;
    INSERT INTO crm_automations (org_id, name, description, trigger_event_type, conditions, actions, enabled, created_by)
    VALUES (v_org_id, v_name, nullif(btrim(p_description), ''), v_trigger,
            COALESCE(p_conditions, '[]'::jsonb), COALESCE(p_actions, '[]'::jsonb), v_enabled, p_created_by)
    RETURNING * INTO v_row;
  ELSE
    SELECT * INTO v_existing FROM crm_automations WHERE id = p_id;
    IF v_existing.id IS NULL THEN RAISE EXCEPTION 'automation % not found', p_id; END IF;
    v_trigger := COALESCE(nullif(btrim(p_trigger_event_type), ''), v_existing.trigger_event_type);
    v_enabled := COALESCE(p_enabled, v_existing.enabled);
    IF v_enabled AND crm_fixed_automation_conflict(v_existing.org_id, v_trigger) THEN
      RAISE EXCEPTION 'trigger "%" is already handled by an enabled fixed automation — disable one of them first (S1 collision guard)', v_trigger;
    END IF;
    UPDATE crm_automations SET
      name               = COALESCE(v_name, name),
      description        = nullif(btrim(p_description), ''),
      trigger_event_type = v_trigger,
      conditions        = COALESCE(p_conditions, conditions),
      actions           = COALESCE(p_actions, actions),
      enabled           = v_enabled,
      updated_at        = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
  END IF;
  RETURN v_row;
END;
$$;


--
-- Name: upsert_crm_task(uuid, text, text, timestamp with time zone, timestamp with time zone, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_crm_task(p_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_remind_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_assignee_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_lead_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS public.crm_tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_title text := nullif(btrim(p_title), '');
  v_row   crm_tasks;
BEGIN
  IF p_id IS NULL THEN
    IF v_title IS NULL THEN RAISE EXCEPTION 'a task title is required'; END IF;
    v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
    INSERT INTO crm_tasks (org_id, title, notes, due_at, remind_at, assignee_id, contact_id, lead_id, created_by)
    VALUES (v_org, v_title, p_notes, p_due_at, p_remind_at, p_assignee_id, p_contact_id, p_lead_id, p_created_by)
    RETURNING * INTO v_row;
    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
    VALUES ('crm_task_created', 'crm_task', v_row.id, p_created_by,
            jsonb_build_object('title', v_row.title, 'due_at', v_row.due_at, 'assignee_id', v_row.assignee_id));
  ELSE
    IF v_title IS NULL THEN RAISE EXCEPTION 'a task title is required'; END IF;
    UPDATE crm_tasks SET
      title = v_title, notes = p_notes, due_at = p_due_at, remind_at = p_remind_at,
      assignee_id = p_assignee_id, contact_id = p_contact_id, lead_id = p_lead_id, updated_at = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'unknown crm_tasks id: %', p_id; END IF;
  END IF;
  RETURN v_row;
END;
$$;


--
-- Name: upsert_demo_schema(uuid, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_demo_schema(p_id uuid, p_name text, p_definition jsonb, p_notes text, p_created_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_version INT;
BEGIN
  IF p_id IS NULL THEN
    SELECT COALESCE(MAX(version), 0) + 1 INTO v_version FROM demo_sheet_schemas;
    INSERT INTO demo_sheet_schemas (version, name, is_active, definition, notes, created_by)
    VALUES (v_version, p_name, false, p_definition, p_notes, p_created_by)
    RETURNING id INTO v_id;
  ELSE
    UPDATE demo_sheet_schemas
       SET name = p_name,
           definition = p_definition,
           notes = COALESCE(p_notes, notes)
     WHERE id = p_id
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;


