--
-- Name: upsert_employee_commission(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_employee_commission(p_employee_id uuid, p_percent numeric DEFAULT NULL::numeric, p_flat numeric DEFAULT NULL::numeric) RETURNS public.employees
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_is_service boolean := COALESCE(
    auth.jwt() ->> 'role' = 'service_role',
    false
  );
  v_stored public.employees;
  v_result public.employees;
BEGIN
  IF NOT v_is_service
     AND NOT public.can_current_employee_access_settings() THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: commission settings access required'
      USING errcode = '42501';
  END IF;

  IF p_employee_id IS NULL THEN
    RAISE EXCEPTION 'INVALID_COMMISSION: employee is required'
      USING errcode = '22023';
  END IF;

  IF p_percent IS NOT NULL AND p_flat IS NOT NULL THEN
    RAISE EXCEPTION
      'INVALID_COMMISSION: percent and flat are mutually exclusive'
      USING errcode = '22023';
  END IF;

  IF p_percent IS NOT NULL
     AND (
       p_percent::text IN ('NaN', 'Infinity', '-Infinity')
       OR p_percent < 0
       OR p_percent > 100
     ) THEN
    RAISE EXCEPTION
      'INVALID_COMMISSION: percent must be between 0 and 100'
      USING errcode = '22023';
  END IF;

  IF p_flat IS NOT NULL
     AND (
       p_flat::text IN ('NaN', 'Infinity', '-Infinity')
       OR p_flat < 0
     ) THEN
    RAISE EXCEPTION
      'INVALID_COMMISSION: flat amount must be nonnegative'
      USING errcode = '22023';
  END IF;

  UPDATE public.employees employee
     SET commission_percent = p_percent,
         commission_flat = p_flat,
         updated_at = now()
   WHERE employee.id = p_employee_id
   RETURNING employee.* INTO v_stored;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVALID_COMMISSION: employee not found'
      USING errcode = '22023';
  END IF;

  IF v_is_service THEN
    RETURN v_stored;
  END IF;

  -- Preserve the employees composite result contract while returning only the
  -- fields this browser capability legitimately owns.
  v_result.id := v_stored.id;
  v_result.full_name := v_stored.full_name;
  v_result.display_name := v_stored.display_name;
  v_result.role := v_stored.role;
  v_result.is_active := v_stored.is_active;
  v_result.commission_percent := v_stored.commission_percent;
  v_result.commission_flat := v_stored.commission_flat;
  v_result.updated_at := v_stored.updated_at;
  RETURN v_result;
END;
$$;


--
-- Name: upsert_employee_page_access(uuid, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_employee_page_access(p_employee_id uuid, p_nav_key text, p_can_view boolean, p_updated_by uuid DEFAULT NULL::uuid) RETURNS public.employee_page_access
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_row employee_page_access;
  v_actor uuid;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  SELECT e.id INTO v_actor FROM employees e WHERE e.auth_user_id = auth.uid();

  INSERT INTO employee_page_access (employee_id, nav_key, can_view, updated_by, updated_at)
  VALUES (p_employee_id, p_nav_key, p_can_view, COALESCE(v_actor, p_updated_by), now())
  ON CONFLICT (employee_id, nav_key) DO UPDATE SET
    can_view = EXCLUDED.can_view,
    updated_by = EXCLUDED.updated_by,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


