--

CREATE TABLE public.form_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    public_id text NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    published_version_id uuid,
    theme jsonb DEFAULT '{}'::jsonb NOT NULL,
    turnstile_enabled boolean DEFAULT false NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT form_definitions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text])))
);


--
-- Name: upsert_form(uuid, text, jsonb, jsonb, text, boolean, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_form(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_schema jsonb DEFAULT '{}'::jsonb, p_theme jsonb DEFAULT '{}'::jsonb, p_status text DEFAULT NULL::text, p_publish boolean DEFAULT false, p_turnstile_enabled boolean DEFAULT false, p_org_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS public.form_definitions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org        uuid;
  v_form       form_definitions;
  v_public_id  text;
  v_latest     form_definition_versions;
  v_draft      form_definition_versions;
  v_has_schema boolean := (p_schema IS NOT NULL AND p_schema <> '{}'::jsonb);
BEGIN
  v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  IF p_id IS NULL THEN
    LOOP
      v_public_id := lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
      EXIT WHEN NOT EXISTS (SELECT 1 FROM form_definitions WHERE public_id = v_public_id);
    END LOOP;

    INSERT INTO form_definitions (org_id, public_id, name, status, theme, turnstile_enabled, created_by)
    VALUES (v_org, v_public_id,
            COALESCE(nullif(btrim(p_name), ''), 'Untitled form'),
            'draft',
            CASE WHEN p_theme IS NULL OR p_theme = '{}'::jsonb THEN '{}'::jsonb ELSE p_theme END,
            COALESCE(p_turnstile_enabled, false), p_created_by)
    RETURNING * INTO v_form;

    INSERT INTO form_definition_versions (form_id, org_id, version, schema, is_published, created_by)
    VALUES (v_form.id, v_org, 1, COALESCE(p_schema, '{}'::jsonb), false, p_created_by)
    RETURNING * INTO v_draft;
  ELSE
    SELECT * INTO v_form FROM form_definitions WHERE id = p_id;
    IF v_form.id IS NULL THEN RAISE EXCEPTION 'form % not found', p_id; END IF;

    UPDATE form_definitions SET
      name  = COALESCE(nullif(btrim(p_name), ''), name),
      theme = CASE WHEN p_theme IS NULL OR p_theme = '{}'::jsonb THEN theme ELSE p_theme END,
      turnstile_enabled = CASE WHEN v_has_schema OR p_publish THEN COALESCE(p_turnstile_enabled, turnstile_enabled) ELSE turnstile_enabled END,
      updated_at = now()
    WHERE id = p_id
    RETURNING * INTO v_form;

    SELECT * INTO v_latest FROM form_definition_versions
      WHERE form_id = p_id ORDER BY version DESC LIMIT 1;

    IF v_has_schema THEN
      IF v_latest.id IS NULL THEN
        INSERT INTO form_definition_versions (form_id, org_id, version, schema, is_published, created_by)
        VALUES (p_id, v_form.org_id, 1, p_schema, false, p_created_by)
        RETURNING * INTO v_draft;
      ELSIF v_latest.is_published THEN
        INSERT INTO form_definition_versions (form_id, org_id, version, schema, is_published, created_by)
        VALUES (p_id, v_form.org_id, v_latest.version + 1, p_schema, false, p_created_by)
        RETURNING * INTO v_draft;
      ELSE
        UPDATE form_definition_versions SET schema = p_schema WHERE id = v_latest.id
        RETURNING * INTO v_draft;
      END IF;
    ELSE
      v_draft := v_latest;
    END IF;
  END IF;

  IF p_publish AND v_draft.id IS NOT NULL THEN
    UPDATE form_definition_versions SET is_published = true, published_at = now()
    WHERE id = v_draft.id
    RETURNING * INTO v_draft;

    UPDATE form_definitions SET
      published_version_id = v_draft.id, status = 'published', updated_at = now()
    WHERE id = v_form.id
    RETURNING * INTO v_form;
  ELSIF p_status IS NOT NULL AND p_status IN ('draft', 'published', 'archived') THEN
    UPDATE form_definitions SET status = p_status, updated_at = now()
    WHERE id = v_form.id
    RETURNING * INTO v_form;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES (CASE WHEN p_publish THEN 'crm_form_published' ELSE 'crm_form_saved' END,
          'form_definition', v_form.id, p_created_by,
          jsonb_build_object('status', v_form.status, 'version', COALESCE(v_draft.version, 1),
                             'public_id', v_form.public_id));

  RETURN v_form;
END;
$$;


--
-- Name: insurance_carriers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.insurance_carriers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    short_name text,
    carrier_type text DEFAULT 'property'::text,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 999,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: upsert_insurance_carrier(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_insurance_carrier(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_short_name text DEFAULT NULL::text, p_sort_order integer DEFAULT 999) RETURNS SETOF public.insurance_carriers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF p_id IS NOT NULL THEN
    RETURN QUERY UPDATE insurance_carriers SET name=COALESCE(p_name,name), short_name=COALESCE(p_short_name,short_name), sort_order=COALESCE(p_sort_order,sort_order) WHERE id=p_id RETURNING *;
  ELSE
    RETURN QUERY INSERT INTO insurance_carriers(name,short_name,sort_order) VALUES(p_name,p_short_name,p_sort_order) RETURNING *;
  END IF;
END;$$;


--
-- Name: lead_attribution; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_attribution (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    lead_id uuid,
    contact_id uuid,
    channel text NOT NULL,
    source text,
    campaign text,
    referral_source_id uuid,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_attribution_channel_check CHECK ((channel = ANY (ARRAY['google_ads'::text, 'meta_ads'::text, 'organic'::text, 'referral'::text, 'insurance'::text, 'other'::text])))
);


--
-- Name: upsert_lead_attribution(text, text, text, uuid, uuid, uuid, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_lead_attribution(p_channel text, p_source text DEFAULT NULL::text, p_campaign text DEFAULT NULL::text, p_lead_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_referral_source_id uuid DEFAULT NULL::uuid, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_created_by uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS public.lead_attribution
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_row lead_attribution;
BEGIN
  IF p_channel NOT IN ('google_ads','meta_ads','organic','referral','insurance','other') THEN
    RAISE EXCEPTION 'invalid attribution channel: %', p_channel;
  END IF;
  IF p_lead_id IS NULL AND p_contact_id IS NULL THEN
    RAISE EXCEPTION 'lead_attribution needs a lead_id or a contact_id';
  END IF;
  v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  INSERT INTO lead_attribution (
    org_id, lead_id, contact_id, channel, source, campaign,
    referral_source_id, occurred_at, created_by
  ) VALUES (
    v_org, p_lead_id, p_contact_id, p_channel, p_source, p_campaign,
    p_referral_source_id, COALESCE(p_occurred_at, now()), p_created_by
  )
  RETURNING * INTO v_row;
  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_attributed', 'lead_attribution', v_row.id, p_created_by,
          jsonb_build_object('channel', p_channel, 'campaign', p_campaign));
  RETURN v_row;
END;
$$;


--
-- Name: upsert_lead_from_callrail(text, text, text, text, integer, boolean, text, text, text, text, text, jsonb, text, numeric, text, timestamp with time zone, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_lead_from_callrail(p_callrail_id text, p_source_type text, p_tracking_number text DEFAULT NULL::text, p_caller_number text DEFAULT NULL::text, p_duration_sec integer DEFAULT NULL::integer, p_spam_flag boolean DEFAULT false, p_source text DEFAULT NULL::text, p_medium text DEFAULT NULL::text, p_campaign text DEFAULT NULL::text, p_recording_url text DEFAULT NULL::text, p_transcription text DEFAULT NULL::text, p_form_data jsonb DEFAULT NULL::jsonb, p_lead_status text DEFAULT 'new'::text, p_value numeric DEFAULT NULL::numeric, p_direction text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now(), p_raw_payload jsonb DEFAULT '{}'::jsonb, p_org_id uuid DEFAULT NULL::uuid) RETURNS public.inbound_leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id          uuid;
  v_contact_id      uuid;
  v_match_count     int;
  v_existed         boolean;
  v_row             inbound_leads;
  v_caller_digits   text;
  v_open_lead_id    uuid;
  v_missed_stage_id uuid;
BEGIN
  IF p_source_type NOT IN ('call', 'form') THEN
    RAISE EXCEPTION 'invalid inbound_leads source_type: %', p_source_type;
  END IF;

  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  IF p_caller_number IS NOT NULL THEN
    v_caller_digits := regexp_replace(p_caller_number, '\D', '', 'g');
    IF length(v_caller_digits) >= 10 THEN
      SELECT count(*) INTO v_match_count
      FROM contacts
      WHERE phone IS NOT NULL
        AND length(regexp_replace(phone, '\D', '', 'g')) >= 10
        AND right(regexp_replace(phone, '\D', '', 'g'), 10) = right(v_caller_digits, 10);

      IF v_match_count = 1 THEN
        SELECT id INTO v_contact_id
        FROM contacts
        WHERE phone IS NOT NULL
          AND length(regexp_replace(phone, '\D', '', 'g')) >= 10
          AND right(regexp_replace(phone, '\D', '', 'g'), 10) = right(v_caller_digits, 10);
      END IF;
    END IF;
  END IF;

  SELECT EXISTS (SELECT 1 FROM inbound_leads WHERE callrail_id = p_callrail_id) INTO v_existed;

  INSERT INTO inbound_leads (
    org_id, contact_id, source_type, callrail_id, tracking_number, caller_number,
    duration_sec, spam_flag, source, medium, campaign, recording_url, transcription,
    form_data, lead_status, value, direction, occurred_at, raw_payload
  ) VALUES (
    v_org_id, v_contact_id, p_source_type, p_callrail_id, p_tracking_number, p_caller_number,
    p_duration_sec, p_spam_flag, p_source, p_medium, p_campaign, p_recording_url, p_transcription,
    p_form_data, p_lead_status, p_value, p_direction, p_occurred_at, p_raw_payload
  )
  ON CONFLICT (callrail_id) DO UPDATE SET
    contact_id      = COALESCE(inbound_leads.contact_id, EXCLUDED.contact_id),
    tracking_number = COALESCE(EXCLUDED.tracking_number, inbound_leads.tracking_number),
    caller_number   = COALESCE(EXCLUDED.caller_number, inbound_leads.caller_number),
    duration_sec    = COALESCE(EXCLUDED.duration_sec, inbound_leads.duration_sec),
    spam_flag       = EXCLUDED.spam_flag,
    source          = COALESCE(EXCLUDED.source, inbound_leads.source),
    medium          = COALESCE(EXCLUDED.medium, inbound_leads.medium),
    campaign        = COALESCE(EXCLUDED.campaign, inbound_leads.campaign),
    recording_url   = COALESCE(EXCLUDED.recording_url, inbound_leads.recording_url),
    transcription   = COALESCE(EXCLUDED.transcription, inbound_leads.transcription),
    form_data       = COALESCE(EXCLUDED.form_data, inbound_leads.form_data),
    value           = COALESCE(EXCLUDED.value, inbound_leads.value),
    raw_payload     = EXCLUDED.raw_payload,
    updated_at      = now()
  RETURNING * INTO v_row;

  IF NOT v_existed AND p_caller_number IS NOT NULL AND v_caller_digits IS NOT NULL AND length(v_caller_digits) >= 10 THEN
    -- Repeat-caller merge, four explicit tiers (see header). When several
    -- candidates match, the most-alive one wins: open > recoverable-terminal
    -- (Missed Calls) > recently-won > recently-lost; oldest within a tier.
    SELECT il2.id INTO v_open_lead_id
    FROM inbound_leads il2
    LEFT JOIN lead_pipeline_stage lps2 ON lps2.lead_id = il2.id
    LEFT JOIN pipeline_stages ps2 ON ps2.id = lps2.stage_id
    WHERE il2.id <> v_row.id
      AND il2.org_id = v_org_id
      AND il2.merged_into_lead_id IS NULL
      AND COALESCE(il2.spam_flag, false) = false
      AND il2.caller_number IS NOT NULL
      AND length(regexp_replace(il2.caller_number, '\D', '', 'g')) >= 10
      AND right(regexp_replace(il2.caller_number, '\D', '', 'g'), 10) = right(v_caller_digits, 10)
      AND (
        (COALESCE(ps2.is_won, false) = false AND COALESCE(ps2.is_lost, false) = false)
        OR COALESCE(ps2.is_recoverable, false) = true
        OR (COALESCE(ps2.is_won, false) = true AND lps2.updated_at > p_occurred_at - interval '30 days')
        OR (COALESCE(ps2.is_lost, false) = true AND COALESCE(ps2.is_recoverable, false) = false
            AND il2.occurred_at > p_occurred_at - interval '3 hours')
      )
    ORDER BY CASE
               WHEN COALESCE(ps2.is_won, false) = false AND COALESCE(ps2.is_lost, false) = false THEN 0
               WHEN COALESCE(ps2.is_recoverable, false) = true THEN 1
               WHEN COALESCE(ps2.is_won, false) = true THEN 2
               ELSE 3
             END,
             il2.created_at ASC
    LIMIT 1;

    IF v_open_lead_id IS NOT NULL THEN
      UPDATE inbound_leads SET merged_into_lead_id = v_open_lead_id, updated_at = now()
      WHERE id = v_row.id;
      v_row.merged_into_lead_id := v_open_lead_id;
      v_row.updated_at := now();

      INSERT INTO system_events (event_type, entity_type, entity_id, payload)
      VALUES ('crm_lead_merged', 'inbound_lead', v_row.id,
              jsonb_build_object('merged_into_lead_id', v_open_lead_id, 'caller_number', p_caller_number));
    END IF;
  END IF;

  IF v_row.source_type = 'call'
     AND v_row.merged_into_lead_id IS NULL
     AND COALESCE(v_row.spam_flag, false) = false
     AND lower(COALESCE(v_row.raw_payload->>'answered', '')) IN ('false', 'f', '0')
     AND NOT EXISTS (SELECT 1 FROM lead_pipeline_stage lps3 WHERE lps3.lead_id = v_row.id)
  THEN
    SELECT id INTO v_missed_stage_id
    FROM pipeline_stages
    WHERE org_id = v_org_id AND name = 'Missed Calls'
    LIMIT 1;
    IF v_missed_stage_id IS NOT NULL THEN
      PERFORM move_lead_to_stage(v_row.id, v_missed_stage_id, NULL, NULL);
    END IF;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES (
    CASE WHEN v_existed THEN 'crm_lead_updated' ELSE 'crm_lead_created' END,
    'inbound_lead',
    v_row.id,
    jsonb_build_object('source_type', v_row.source_type, 'callrail_id', v_row.callrail_id, 'contact_id', v_row.contact_id)
  );

  RETURN v_row;
END;
$$;


--
-- Name: upsert_lead_from_form(uuid, text, jsonb, jsonb, boolean, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_lead_from_form(p_form_id uuid, p_submission_token text, p_data jsonb, p_utm jsonb DEFAULT '{}'::jsonb, p_consent boolean DEFAULT false, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_org_id uuid DEFAULT NULL::uuid) RETURNS public.inbound_leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_form        form_definitions;
  v_version     form_definition_versions;
  v_schema      jsonb;
  v_org         uuid;
  v_callrail_id text := 'form:' || COALESCE(p_submission_token, '');
  v_field       jsonb;
  v_phone_key   text;
  v_email_key   text;
  v_name_key    text;
  v_consent_lbl text := 'SMS consent';
  v_raw_phone   text;
  v_phone       text;
  v_digits      text;
  v_name        text;
  v_email       text;
  v_contact_id  uuid;
  v_source      text;
  v_medium      text;
  v_campaign    text;
  v_channel     text;
  v_row         inbound_leads;
BEGIN
  IF p_submission_token IS NULL OR btrim(p_submission_token) = '' THEN
    RAISE EXCEPTION 'submission_token is required';
  END IF;

  SELECT * INTO v_form FROM form_definitions WHERE id = p_form_id;
  IF v_form.id IS NULL THEN RAISE EXCEPTION 'form % not found', p_form_id; END IF;
  IF v_form.published_version_id IS NULL THEN RAISE EXCEPTION 'form % is not published', p_form_id; END IF;

  SELECT * INTO v_version FROM form_definition_versions WHERE id = v_form.published_version_id;
  v_schema := COALESCE(v_version.schema, '{}'::jsonb);
  v_org := COALESCE(p_org_id, v_form.org_id);

  SELECT * INTO v_row FROM inbound_leads WHERE callrail_id = v_callrail_id;
  IF v_row.id IS NOT NULL THEN
    RETURN v_row;
  END IF;

  FOR v_field IN SELECT * FROM jsonb_array_elements(COALESCE(v_schema->'fields', '[]'::jsonb)) LOOP
    IF v_field->>'type' = 'phone' AND v_phone_key IS NULL THEN v_phone_key := v_field->>'key'; END IF;
    IF v_field->>'type' = 'email' AND v_email_key IS NULL THEN v_email_key := v_field->>'key'; END IF;
    IF v_field->>'type' = 'consent' THEN v_consent_lbl := COALESCE(nullif(btrim(v_field->>'label'), ''), v_consent_lbl); END IF;
    IF v_field->>'type' = 'text' AND v_name_key IS NULL
       AND ((v_field->>'key') = 'name' OR lower(COALESCE(v_field->>'label', '')) LIKE '%name%')
    THEN v_name_key := v_field->>'key'; END IF;
  END LOOP;

  v_raw_phone := CASE WHEN v_phone_key IS NOT NULL THEN p_data->>v_phone_key ELSE NULL END;
  v_email     := CASE WHEN v_email_key IS NOT NULL THEN p_data->>v_email_key ELSE NULL END;
  v_name      := CASE WHEN v_name_key  IS NOT NULL THEN p_data->>v_name_key  ELSE NULL END;

  v_digits := regexp_replace(COALESCE(v_raw_phone, ''), '\D', '', 'g');
  IF length(v_digits) = 10 THEN v_digits := '1' || v_digits; END IF;
  IF length(v_digits) >= 10 THEN v_phone := '+' || v_digits; ELSE v_phone := NULL; END IF;

  IF v_phone IS NOT NULL THEN
    SELECT id INTO v_contact_id FROM contacts WHERE phone = v_phone LIMIT 1;
    IF v_contact_id IS NULL THEN
      INSERT INTO contacts (phone, name, email, opt_in_status)
      VALUES (v_phone, nullif(btrim(v_name), ''), nullif(btrim(v_email), ''), false)
      RETURNING id INTO v_contact_id;
    ELSE
      UPDATE contacts SET
        name  = COALESCE(name, nullif(btrim(v_name), '')),
        email = COALESCE(email, nullif(btrim(v_email), '')),
        updated_at = now()
      WHERE id = v_contact_id;
    END IF;
  END IF;

  v_source   := COALESCE(p_utm->>'utm_source', p_utm->>'source');
  v_medium   := COALESCE(p_utm->>'utm_medium', p_utm->>'medium');
  v_campaign := COALESCE(p_utm->>'utm_campaign', p_utm->>'campaign');
  v_channel  := crm_channel_for_source(v_source);

  INSERT INTO inbound_leads (
    org_id, contact_id, source_type, callrail_id, caller_number,
    spam_flag, source, medium, campaign, form_data, lead_status,
    direction, occurred_at, raw_payload
  ) VALUES (
    v_org, v_contact_id, 'form', v_callrail_id, v_phone,
    false, COALESCE(nullif(btrim(v_source), ''), v_form.name), v_medium, v_campaign, p_data, 'new',
    'inbound', now(),
    jsonb_build_object('form_id', v_form.id, 'public_id', v_form.public_id,
                       'utm', COALESCE(p_utm, '{}'::jsonb), 'user_agent', p_user_agent, 'ip', p_ip)
  )
  ON CONFLICT (callrail_id) DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row FROM inbound_leads WHERE callrail_id = v_callrail_id;
    RETURN v_row;
  END IF;

  INSERT INTO form_submissions (
    form_id, version_id, org_id, submission_token, data, utm,
    lead_id, contact_id, ip_address, user_agent, is_spam
  ) VALUES (
    v_form.id, v_form.published_version_id, v_org, p_submission_token, p_data, COALESCE(p_utm, '{}'::jsonb),
    v_row.id, v_contact_id, p_ip, p_user_agent, false
  )
  ON CONFLICT (submission_token) DO NOTHING;

  PERFORM upsert_lead_attribution(v_channel, v_source, v_campaign, v_row.id, v_contact_id, NULL, now(), NULL, v_org);

  IF p_consent AND v_contact_id IS NOT NULL AND v_phone IS NOT NULL THEN
    UPDATE contacts SET
      opt_in_status = true, opt_in_source = 'web_form', opt_in_at = now(),
      opt_out_at = NULL, opt_out_reason = NULL, updated_at = now()
    WHERE id = v_contact_id;

    INSERT INTO sms_consent_log (contact_id, phone, event_type, source, details, ip_address)
    VALUES (v_contact_id, v_phone, 'opt_in', 'web_form',
            'Web-form consent (form ' || v_form.public_id || ' v' || COALESCE(v_version.version, 1) || '): ' || v_consent_lbl,
            p_ip);
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_created', 'inbound_lead', v_row.id,
          jsonb_build_object('source_type', 'form', 'form_id', v_form.id, 'contact_id', v_contact_id));

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_form_submitted', 'form_definition', v_form.id,
          jsonb_build_object('submission_token', p_submission_token, 'lead_id', v_row.id,
                             'contact_id', v_contact_id, 'public_id', v_form.public_id));

  RETURN v_row;
END;
$$;


--
-- Name: upsert_my_native_device_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_my_native_device_token(p_token text, p_apns_environment text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_employee_id uuid;
  v_row public.device_tokens%ROWTYPE;
BEGIN
  IF NULLIF(btrim(p_token), '') IS NULL
     OR length(p_token) > 4096
     OR p_apns_environment IS NULL
     OR p_apns_environment NOT IN ('sandbox', 'production') THEN
    RAISE EXCEPTION
      'token and an exact APNs environment are required'
      USING errcode = '22023';
  END IF;

  SELECT employee.id
  INTO v_employee_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text IN (
      'admin',
      'office',
      'project_manager',
      'field_tech',
      'estimator',
      'supervisor'
    )
  LIMIT 1;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  INSERT INTO public.device_tokens (
    employee_id,
    token,
    platform,
    apns_environment
  )
  VALUES (
    v_employee_id,
    btrim(p_token),
    'ios',
    p_apns_environment
  )
  ON CONFLICT (token)
  DO UPDATE SET
    platform = 'ios',
    apns_environment = EXCLUDED.apns_environment,
    updated_at = now()
  WHERE device_tokens.employee_id = EXCLUDED.employee_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: device token belongs to another employee'
      USING errcode = '42501';
  END IF;

  -- Bound one employee/environment to the five newest installations. The
  -- delivery worker uses the same cap, so one account cannot hold a Worker open
  -- across an unbounded sequence of APNs calls.
  DELETE FROM public.device_tokens stale_token
  WHERE stale_token.id IN (
    SELECT ranked.id
    FROM (
      SELECT
        token_row.id,
        row_number() OVER (
          ORDER BY token_row.updated_at DESC, token_row.id DESC
        ) AS position
      FROM public.device_tokens token_row
      WHERE token_row.employee_id = v_employee_id
        AND token_row.platform = 'ios'
        AND token_row.apns_environment = p_apns_environment
    ) ranked
    WHERE ranked.position > 5
  );

  RETURN jsonb_build_object(
    'id', v_row.id,
    'platform', v_row.platform,
    'apns_environment', v_row.apns_environment,
    'updated_at', v_row.updated_at
  );
END;
$$;


--
-- Name: upsert_oop_quote(uuid, uuid, text, text, text, numeric, numeric, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, numeric, numeric, integer, numeric, numeric, numeric, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_oop_quote(p_id uuid, p_job_id uuid, p_job_type text, p_insured_name text, p_address text, p_tech_hours numeric, p_bill_rate numeric, p_air_mover_count integer, p_air_mover_days integer, p_lgr_count integer, p_lgr_days integer, p_xlgr_count integer, p_xlgr_days integer, p_air_scrubber_count integer, p_air_scrubber_days integer, p_neg_air_count integer, p_neg_air_days integer, p_materials_actual_cost numeric, p_antimicrobial_sqft numeric, p_disposal_trips integer, p_containment_linear_ft numeric, p_prv_invoice_cost numeric, p_quote_total numeric, p_net_margin_pct numeric, p_notes text, p_created_by uuid) RETURNS public.oop_quotes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row oop_quotes;
BEGIN
  IF p_id IS NULL THEN
    INSERT INTO oop_quotes (
      quote_number, job_id, job_type, insured_name, address,
      tech_hours, bill_rate,
      air_mover_count, air_mover_days,
      lgr_count, lgr_days,
      xlgr_count, xlgr_days,
      air_scrubber_count, air_scrubber_days,
      neg_air_count, neg_air_days,
      materials_actual_cost, antimicrobial_sqft, disposal_trips,
      containment_linear_ft, prv_invoice_cost,
      quote_total, net_margin_pct, notes, created_by
    ) VALUES (
      generate_oop_quote_number(), p_job_id, p_job_type, p_insured_name, p_address,
      COALESCE(p_tech_hours,0), COALESCE(p_bill_rate,92),
      COALESCE(p_air_mover_count,0), COALESCE(p_air_mover_days,0),
      COALESCE(p_lgr_count,0), COALESCE(p_lgr_days,0),
      COALESCE(p_xlgr_count,0), COALESCE(p_xlgr_days,0),
      COALESCE(p_air_scrubber_count,0), COALESCE(p_air_scrubber_days,0),
      COALESCE(p_neg_air_count,0), COALESCE(p_neg_air_days,0),
      COALESCE(p_materials_actual_cost,0), COALESCE(p_antimicrobial_sqft,0), COALESCE(p_disposal_trips,0),
      COALESCE(p_containment_linear_ft,0), COALESCE(p_prv_invoice_cost,0),
      p_quote_total, p_net_margin_pct, p_notes, p_created_by
    )
    RETURNING * INTO v_row;
  ELSE
    UPDATE oop_quotes SET
      job_id = p_job_id,
      job_type = p_job_type,
      insured_name = p_insured_name,
      address = p_address,
      tech_hours = COALESCE(p_tech_hours,0),
      bill_rate = COALESCE(p_bill_rate,92),
      air_mover_count = COALESCE(p_air_mover_count,0),
      air_mover_days = COALESCE(p_air_mover_days,0),
      lgr_count = COALESCE(p_lgr_count,0),
      lgr_days = COALESCE(p_lgr_days,0),
      xlgr_count = COALESCE(p_xlgr_count,0),
      xlgr_days = COALESCE(p_xlgr_days,0),
      air_scrubber_count = COALESCE(p_air_scrubber_count,0),
      air_scrubber_days = COALESCE(p_air_scrubber_days,0),
      neg_air_count = COALESCE(p_neg_air_count,0),
      neg_air_days = COALESCE(p_neg_air_days,0),
      materials_actual_cost = COALESCE(p_materials_actual_cost,0),
      antimicrobial_sqft = COALESCE(p_antimicrobial_sqft,0),
      disposal_trips = COALESCE(p_disposal_trips,0),
      containment_linear_ft = COALESCE(p_containment_linear_ft,0),
      prv_invoice_cost = COALESCE(p_prv_invoice_cost,0),
      quote_total = p_quote_total,
      net_margin_pct = p_net_margin_pct,
      notes = p_notes,
      updated_at = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: upsert_permission(text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_permission(p_role text, p_nav_key text, p_can_view boolean, p_can_edit boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result nav_permissions;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  INSERT INTO nav_permissions (role, nav_key, can_view, can_edit)
  VALUES (p_role, p_nav_key, p_can_view, p_can_edit)
  ON CONFLICT (role, nav_key)
  DO UPDATE SET can_view = p_can_view, can_edit = p_can_edit
  RETURNING * INTO result;

  RETURN row_to_json(result)::jsonb;
END;
$$;


--
-- Name: upsert_pipeline_stage(uuid, text, text, integer, boolean, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_pipeline_stage(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_color text DEFAULT '#6366f1'::text, p_sort_order integer DEFAULT NULL::integer, p_is_won boolean DEFAULT false, p_is_lost boolean DEFAULT false, p_org_id uuid DEFAULT NULL::uuid) RETURNS public.pipeline_stages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_row    pipeline_stages;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'pipeline stage name is required';
  END IF;
  IF p_is_won AND p_is_lost THEN
    RAISE EXCEPTION 'a pipeline stage cannot be both is_won and is_lost';
  END IF;

  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  IF p_id IS NULL THEN
    INSERT INTO pipeline_stages (org_id, name, color, sort_order, is_won, is_lost)
    VALUES (
      v_org_id, btrim(p_name), COALESCE(p_color, '#6366f1'),
      COALESCE(p_sort_order, (SELECT COALESCE(MAX(sort_order), -1) + 1 FROM pipeline_stages WHERE org_id = v_org_id)),
      p_is_won, p_is_lost
    )
    RETURNING * INTO v_row;
  ELSE
    UPDATE pipeline_stages
       SET name       = btrim(p_name),
           color      = COALESCE(p_color, color),
           sort_order = COALESCE(p_sort_order, sort_order),
           is_won     = p_is_won,
           is_lost    = p_is_lost,
           updated_at = now()
     WHERE id = p_id
     RETURNING * INTO v_row;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'unknown pipeline_stages id: %', p_id;
    END IF;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: property_meld_melds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_meld_melds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    meld_number text NOT NULL,
    meld_internal_id text,
    org_id text,
    vendor_account_id text NOT NULL,
    business text DEFAULT 'restoration'::text NOT NULL,
    pm_brand text,
    is_emergency boolean DEFAULT false NOT NULL,
    meld_type text,
    status text,
    due_date_text text,
    appointment_window text,
    address_street text,
    address_unit text,
    address_city_state_zip text,
    address_full text,
    description text,
    description_clipped boolean DEFAULT false NOT NULL,
    last_message_from text,
    last_message_text text,
    thread_reply_address text,
    portal_url text,
    state text DEFAULT 'open'::text NOT NULL,
    imported_job_id uuid,
    received_at timestamp with time zone,
    last_event text,
    last_event_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT property_meld_melds_state_check CHECK ((state = ANY (ARRAY['open'::text, 'canceled'::text, 'imported'::text, 'archived'::text])))
);


--
-- Name: upsert_property_meld_meld(text, text, text, text, text, text, text, boolean, text, text, text, text, text, text, text, text, text, boolean, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_property_meld_meld(p_meld_number text, p_event text, p_vendor_account_id text, p_business text DEFAULT 'restoration'::text, p_org_id text DEFAULT NULL::text, p_meld_internal_id text DEFAULT NULL::text, p_pm_brand text DEFAULT NULL::text, p_is_emergency boolean DEFAULT false, p_meld_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_due_date_text text DEFAULT NULL::text, p_appointment_window text DEFAULT NULL::text, p_address_street text DEFAULT NULL::text, p_address_unit text DEFAULT NULL::text, p_address_city_state_zip text DEFAULT NULL::text, p_address_full text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_description_clipped boolean DEFAULT false, p_message_from text DEFAULT NULL::text, p_message_text text DEFAULT NULL::text, p_thread_reply_address text DEFAULT NULL::text, p_portal_url text DEFAULT NULL::text, p_received_at timestamp with time zone DEFAULT now()) RETURNS public.property_meld_melds
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result property_meld_melds;
BEGIN
  INSERT INTO property_meld_melds (
    meld_number, meld_internal_id, org_id, vendor_account_id, business, pm_brand,
    is_emergency, meld_type, status, due_date_text, appointment_window,
    address_street, address_unit, address_city_state_zip, address_full,
    description, description_clipped,
    last_message_from, last_message_text, thread_reply_address, portal_url,
    state, received_at, last_event, last_event_at
  )
  VALUES (
    p_meld_number, p_meld_internal_id, p_org_id, p_vendor_account_id,
    COALESCE(p_business, 'restoration'), p_pm_brand,
    COALESCE(p_is_emergency, FALSE), p_meld_type, p_status, p_due_date_text, p_appointment_window,
    p_address_street, p_address_unit, p_address_city_state_zip, p_address_full,
    CASE WHEN p_event = 'message' THEN NULL ELSE p_description END,
    COALESCE(p_description_clipped, FALSE),
    CASE WHEN p_event = 'message' THEN p_message_from END,
    CASE WHEN p_event = 'message' THEN p_message_text END,
    p_thread_reply_address, p_portal_url,
    CASE WHEN p_event = 'canceled' THEN 'canceled' ELSE 'open' END,
    COALESCE(p_received_at, now()), p_event, COALESCE(p_received_at, now())
  )
  ON CONFLICT (meld_number) DO UPDATE SET
    meld_internal_id       = COALESCE(EXCLUDED.meld_internal_id, property_meld_melds.meld_internal_id),
    org_id                 = COALESCE(EXCLUDED.org_id, property_meld_melds.org_id),
    vendor_account_id      = COALESCE(EXCLUDED.vendor_account_id, property_meld_melds.vendor_account_id),
    pm_brand               = COALESCE(EXCLUDED.pm_brand, property_meld_melds.pm_brand),
    is_emergency           = property_meld_melds.is_emergency OR EXCLUDED.is_emergency,
    meld_type              = COALESCE(EXCLUDED.meld_type, property_meld_melds.meld_type),
    status                 = CASE WHEN p_event = 'canceled' THEN 'Canceled'
                                  ELSE COALESCE(EXCLUDED.status, property_meld_melds.status) END,
    due_date_text          = COALESCE(EXCLUDED.due_date_text, property_meld_melds.due_date_text),
    appointment_window     = COALESCE(EXCLUDED.appointment_window, property_meld_melds.appointment_window),
    address_street         = COALESCE(EXCLUDED.address_street, property_meld_melds.address_street),
    address_unit           = COALESCE(EXCLUDED.address_unit, property_meld_melds.address_unit),
    address_city_state_zip = COALESCE(EXCLUDED.address_city_state_zip, property_meld_melds.address_city_state_zip),
    address_full           = COALESCE(EXCLUDED.address_full, property_meld_melds.address_full),
    description            = CASE WHEN p_event = 'message' THEN property_meld_melds.description
                                  ELSE COALESCE(EXCLUDED.description, property_meld_melds.description) END,
    description_clipped    = CASE WHEN p_event = 'message' THEN property_meld_melds.description_clipped
                                  ELSE EXCLUDED.description_clipped END,
    last_message_from      = COALESCE(EXCLUDED.last_message_from, property_meld_melds.last_message_from),
    last_message_text      = COALESCE(EXCLUDED.last_message_text, property_meld_melds.last_message_text),
    thread_reply_address   = COALESCE(EXCLUDED.thread_reply_address, property_meld_melds.thread_reply_address),
    portal_url             = COALESCE(EXCLUDED.portal_url, property_meld_melds.portal_url),
    state                  = CASE
                               WHEN property_meld_melds.state = 'imported' THEN 'imported'
                               WHEN p_event = 'canceled' THEN 'canceled'
                               ELSE property_meld_melds.state
                             END,
    received_at            = LEAST(property_meld_melds.received_at, COALESCE(EXCLUDED.received_at, now())),
    last_event             = p_event,
    last_event_at          = COALESCE(EXCLUDED.received_at, now()),
    updated_at             = now()
  RETURNING * INTO result;

  RETURN result;
END;
$$;


--
-- Name: push_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.push_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    endpoint text NOT NULL,
    p256dh text NOT NULL,
    auth text NOT NULL,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: upsert_push_subscription(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_user_agent text DEFAULT NULL::text) RETURNS public.push_subscriptions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp uuid;
  v_row public.push_subscriptions;
BEGIN
  SELECT id INTO v_emp FROM public.employees WHERE auth_user_id = auth.uid() LIMIT 1;
  IF v_emp IS NULL THEN RETURN NULL; END IF;

  INSERT INTO public.push_subscriptions (employee_id, endpoint, p256dh, auth, user_agent)
  VALUES (v_emp, p_endpoint, p_p256dh, p_auth, p_user_agent)
  ON CONFLICT (endpoint) DO UPDATE
    SET employee_id = EXCLUDED.employee_id,
        p256dh      = EXCLUDED.p256dh,
        auth        = EXCLUDED.auth,
        user_agent  = EXCLUDED.user_agent,
        updated_at  = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: referral_sources; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.referral_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    category text DEFAULT 'other'::text,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 999,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: upsert_referral_source(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_referral_source(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_category text DEFAULT 'other'::text, p_sort_order integer DEFAULT 999) RETURNS SETOF public.referral_sources
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF p_id IS NOT NULL THEN
    RETURN QUERY UPDATE referral_sources SET name=COALESCE(p_name,name), category=COALESCE(p_category,category), sort_order=COALESCE(p_sort_order,sort_order) WHERE id=p_id RETURNING *;
  ELSE
    RETURN QUERY INSERT INTO referral_sources(name,category,sort_order) VALUES(p_name,p_category,p_sort_order) RETURNING *;
  END IF;
END;$$;


--
-- Name: upsert_segment(uuid, text, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_segment(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_filter jsonb DEFAULT '{}'::jsonb, p_org_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS public.crm_segments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_name   text := nullif(btrim(p_name), '');
  v_row    crm_segments;
BEGIN
  IF p_id IS NULL THEN
    IF v_name IS NULL THEN RAISE EXCEPTION 'a segment name is required'; END IF;
    INSERT INTO crm_segments (org_id, name, description, filter, created_by)
    VALUES (v_org_id, v_name, nullif(btrim(p_description), ''), COALESCE(p_filter, '{}'::jsonb), p_created_by)
    RETURNING * INTO v_row;
  ELSE
    UPDATE crm_segments SET
      name        = COALESCE(v_name, name),
      description  = nullif(btrim(p_description), ''),
      filter      = COALESCE(p_filter, filter),
      updated_at  = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'segment % not found', p_id; END IF;
  END IF;
  RETURN v_row;
END;
$$;


--
-- Name: crm_sequences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_sequences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    status text DEFAULT 'draft'::text NOT NULL,
    exit_on_reply boolean DEFAULT true NOT NULL,
    exit_on_conversion boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_sequences_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'paused'::text, 'archived'::text])))
);


--
-- Name: upsert_sequence(uuid, text, text, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_sequence(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_steps jsonb DEFAULT '[]'::jsonb, p_org_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS public.crm_sequences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_name   text := nullif(btrim(p_name), '');
  v_row    crm_sequences;
BEGIN
  IF p_id IS NULL THEN
    IF v_name IS NULL THEN RAISE EXCEPTION 'a sequence name is required'; END IF;
    INSERT INTO crm_sequences (org_id, name, description, status, created_by)
    VALUES (v_org_id, v_name, nullif(btrim(p_description), ''),
            COALESCE(nullif(btrim(p_status), ''), 'draft'), p_created_by)
    RETURNING * INTO v_row;
  ELSE
    UPDATE crm_sequences SET
      name        = COALESCE(v_name, name),
      description  = nullif(btrim(p_description), ''),
      status      = COALESCE(nullif(btrim(p_status), ''), status),
      updated_at  = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'sequence % not found', p_id; END IF;
  END IF;

  IF p_steps IS NOT NULL THEN
    DELETE FROM crm_sequence_steps WHERE sequence_id = v_row.id;
    INSERT INTO crm_sequence_steps (sequence_id, org_id, step_order, channel, delay_hours, subject, body, template_id)
    SELECT
      v_row.id, v_org_id,
      (row_number() OVER (ORDER BY COALESCE((e.elem->>'step_order')::int, (e.ord - 1)::int), e.ord) - 1)::int,
      e.elem->>'channel',
      GREATEST(COALESCE((e.elem->>'delay_hours')::int, 0), 0),
      nullif(e.elem->>'subject', ''),
      nullif(e.elem->>'body', ''),
      nullif(e.elem->>'template_id', '')::uuid
    FROM jsonb_array_elements(p_steps) WITH ORDINALITY AS e(elem, ord);
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: upsert_time_entry(uuid, uuid, uuid, date, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_time_entry(p_id uuid DEFAULT NULL::uuid, p_job_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid, p_work_date date DEFAULT NULL::date, p_hours numeric DEFAULT NULL::numeric, p_work_type text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_id IS NOT NULL THEN
    UPDATE job_time_entries SET
      job_id      = COALESCE(p_job_id, job_id),
      employee_id = COALESCE(p_employee_id, employee_id),
      work_date   = COALESCE(p_work_date, work_date),
      hours       = COALESCE(p_hours, hours),
      work_type   = COALESCE(p_work_type, work_type),
      description = COALESCE(p_description, description),
      notes       = COALESCE(p_notes, notes)
    WHERE id = p_id
    RETURNING id INTO v_id;
  ELSE
    INSERT INTO job_time_entries (job_id, employee_id, work_date, hours, work_type, description, notes)
    VALUES (p_job_id, p_employee_id, p_work_date, p_hours, p_work_type, p_description, p_notes)
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: wake_callrail_event_recovery_worker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wake_callrail_event_recovery_worker() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_worker_url text;
  v_secret text;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT value
  INTO v_worker_url
  FROM public.integration_config
  WHERE key = 'callrail_event_recovery_worker_url';

  SELECT value
  INTO v_secret
  FROM public.integration_config
  WHERE key = 'cron_worker_secret';

  IF v_worker_url IS NULL OR v_worker_url NOT IN (
    'https://dev.utahpros.app/api/process-callrail-events',
    'https://utahpros.app/api/process-callrail-events'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.message_provider_events e
    WHERE e.provider = 'callrail'
      AND e.message_type IN ('sms', 'mms')
      AND (
        e.processing_state = 'received'
        OR (
          e.processing_state = 'retryable'
          AND e.next_attempt_at <= v_now
        )
        OR (
          e.processing_state = 'claimed'
          AND e.claimed_at < v_now - interval '5 minutes'
        )
      )
  ) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );

  RETURN;
END;
$$;


--
-- Name: wake_message_notification_outbox_worker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wake_message_notification_outbox_worker() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_worker_url text;
  v_secret text;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT value
  INTO v_worker_url
  FROM public.integration_config
  WHERE key = 'message_notification_outbox_worker_url';

  SELECT value
  INTO v_secret
  FROM public.integration_config
  WHERE key = 'cron_worker_secret';

  IF v_worker_url IS NULL OR v_worker_url NOT IN (
    'https://dev.utahpros.app/api/process-message-notification-outbox',
    'https://utahpros.app/api/process-message-notification-outbox'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.message_notification_outbox o
    WHERE (
      o.delivery_state IN ('pending', 'retryable')
      AND o.next_attempt_at <= v_now
    ) OR (
      o.delivery_state = 'processing'
      AND o.claimed_at < v_now - interval '5 minutes'
    )
  ) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );

  RETURN;
END;
$$;


