    CONSTRAINT message_send_attempts_attempt_number_check CHECK ((attempt_number > 0)),
    CONSTRAINT message_send_attempts_media_urls_check CHECK ((jsonb_typeof(media_urls) = 'array'::text)),
    CONSTRAINT message_send_attempts_provider_check CHECK ((provider = ANY (ARRAY['twilio'::text, 'callrail'::text]))),
    CONSTRAINT message_send_attempts_requested_channel_check CHECK ((requested_channel = ANY (ARRAY['sms'::text, 'mms'::text, 'rcs'::text]))),
    CONSTRAINT message_send_attempts_state_check CHECK ((state = ANY (ARRAY['prepared'::text, 'submitting'::text, 'accepted'::text, 'ambiguous'::text, 'confirmed'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: TABLE message_send_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.message_send_attempts IS 'Service-only reservation and reconciliation ledger for provider submissions. message_id may be null before persistence or after the retained audit outlives a deleted message.';


--
-- Name: COLUMN message_send_attempts.parent_attempt_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_send_attempts.parent_attempt_id IS 'Parent request reservation for a multi-recipient action; every provider side effect is represented by one recipient child attempt.';


--
-- Name: COLUMN message_send_attempts.submitted_body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_send_attempts.submitted_body IS 'Exact body submitted to the provider, including any staff prefix; canonical messages.body remains the unprefixed customer-visible composition.';


--
-- Name: COLUMN message_send_attempts.canonical_body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_send_attempts.canonical_body IS 'Unprefixed canonical message body retained so an accepted provider outcome can be materialized without another provider submission.';


--
-- Name: COLUMN message_send_attempts.requested_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_send_attempts.requested_channel IS 'Provider-neutral requested transport channel, such as sms, mms, or rcs.';


--
-- Name: COLUMN message_send_attempts.actual_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_send_attempts.actual_channel IS 'Provider-confirmed channel used for delivery; may differ only under an explicitly approved fallback policy.';


--
-- Name: COLUMN message_send_attempts.channel_fallback_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.message_send_attempts.channel_fallback_reason IS 'Auditable provider-neutral reason actual_channel differs from requested_channel; null when no fallback occurred.';


