--
-- Name: messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    type text NOT NULL,
    body text,
    channel text DEFAULT 'sms'::text,
    status text DEFAULT 'queued'::text NOT NULL,
    twilio_sid text,
    sent_by uuid,
    sender_phone text,
    sender_contact_id uuid,
    media_urls jsonb,
    rcs_content_sid text,
    read_at timestamp with time zone,
    clicked_at timestamp with time zone,
    error_code text,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    direction text,
    email_message_id text,
    in_reply_to text,
    email_references text,
    email_from text,
    email_to text,
    subject text,
    email_html text,
    sender_email text,
    num_segments integer,
    price numeric,
    provider text,
    provider_message_id text,
    provider_conversation_id text,
    client_request_id uuid,
    sender_address text,
    recipient_address text,
    CONSTRAINT messages_channel_check CHECK (((channel IS NULL) OR (channel = ANY (ARRAY['sms'::text, 'mms'::text, 'rcs'::text, 'email'::text])))),
    CONSTRAINT messages_direction_check CHECK (((direction IS NULL) OR (direction = ANY (ARRAY['inbound'::text, 'outbound'::text, 'note'::text])))),
    CONSTRAINT messages_provider_check CHECK (((provider IS NULL) OR (provider = ANY (ARRAY['twilio'::text, 'callrail'::text])))),
    CONSTRAINT messages_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'failed'::text, 'undelivered'::text, 'received'::text]))),
    CONSTRAINT messages_type_check CHECK ((type = ANY (ARRAY['sms_inbound'::text, 'sms_outbound'::text, 'internal_note'::text, 'email_inbound'::text, 'email_outbound'::text])))
);


--
-- Name: COLUMN messages.num_segments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.messages.num_segments IS 'Twilio SMS segment count for this message (from the status callback / message resource). Nullable; null on legacy + inbound rows.';


--
-- Name: COLUMN messages.price; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.messages.price IS 'Twilio-reported price for this message (negative string in Twilio; stored as numeric). Nullable; null until Twilio reports it.';


--
-- Name: COLUMN messages.provider; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.messages.provider IS 'Outbound/inbound transport that owns this message. Provider facts do not control consent or conversation identity.';


--
