--

COMMENT ON COLUMN public.messages.provider_message_id IS 'Provider message/resource identity when the provider exposes one. Twilio dual-writes twilio_sid during transition.';


--
-- Name: COLUMN messages.provider_conversation_id; Type: COMMENT; Schema: public; Owner: -
