--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid,
    job_id uuid NOT NULL,
    contact_id uuid,
    amount numeric NOT NULL,
    payment_method text,
    payment_date date DEFAULT CURRENT_DATE NOT NULL,
    reference_number text,
    payer_type text DEFAULT 'insurance'::text,
    payer_name text,
    is_deductible boolean DEFAULT false,
    is_depreciation_release boolean DEFAULT false,
    notes text,
    recorded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    qbo_payment_id text,
    qbo_synced_at timestamp with time zone,
    qbo_sync_error text,
    source text DEFAULT 'manual'::text,
    stripe_payment_intent_id text,
    stripe_charge_id text,
    stripe_fee numeric,
    stripe_fee_qbo_purchase_id text,
    refunded_amount numeric DEFAULT 0 NOT NULL,
    refunded_at timestamp with time zone,
    dispute_status text,
    CONSTRAINT payments_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT payments_payer_type_check CHECK ((payer_type = ANY (ARRAY['insurance'::text, 'homeowner'::text, 'mortgage_co'::text, 'property_manager'::text, 'other'::text]))),
    CONSTRAINT payments_payment_method_check CHECK ((payment_method = ANY (ARRAY['check'::text, 'ach'::text, 'credit_card'::text, 'wire'::text, 'cash'::text, 'insurance_direct'::text, 'other'::text])))
);


--
-- Name: qbo_attachments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.qbo_attachments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type text NOT NULL,
    invoice_id uuid,
    estimate_id uuid,
    qbo_attachable_id text NOT NULL,
    file_name text NOT NULL,
    content_type text,
    file_size bigint,
    include_on_send boolean DEFAULT true NOT NULL,
    idempotency_key text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT qbo_attachments_entity_type_check CHECK ((entity_type = ANY (ARRAY['invoice'::text, 'estimate'::text]))),
    CONSTRAINT qbo_attachments_one_parent CHECK ((((entity_type = 'invoice'::text) AND (invoice_id IS NOT NULL) AND (estimate_id IS NULL)) OR ((entity_type = 'estimate'::text) AND (estimate_id IS NOT NULL) AND (invoice_id IS NULL))))
);


