--
-- Name: rv_invoices; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.rv_invoices WITH (security_invoker='true') AS
 SELECT id AS invoice_id,
    job_id,
    contact_id,
    invoice_number,
    invoice_type,
    status,
    subtotal,
    tax,
    total,
    amount_paid,
    balance_due,
    insurance_responsibility,
    homeowner_responsibility,
    insurance_paid,
    homeowner_paid,
    invoice_date,
    due_date,
    sent_at,
    paid_at,
    created_at,
    public.mt_date(created_at) AS created_day,
    carrier_name,
    claim_number,
    (qbo_invoice_id IS NOT NULL) AS is_qbo_synced,
        CASE
            WHEN ((status IS DISTINCT FROM 'paid'::text) AND (COALESCE(balance_due, (0)::numeric) > (0)::numeric) AND (invoice_date IS NOT NULL)) THEN GREATEST((public.mt_today() - invoice_date), 0)
            ELSE NULL::integer
        END AS days_outstanding
   FROM public.invoices i;


--
-- Name: rv_jobs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.rv_jobs WITH (security_invoker='true') AS
 SELECT id AS job_id,
    job_number,
    (division)::text AS division,
    phase,
    status,
    (source)::text AS source,
    lead_source,
    primary_contact_id,
    claim_id,
    project_manager_id,
    lead_tech_id,
    is_real_job,
    created_at,
    public.mt_date(created_at) AS created_day,
    received_date,
    date_of_loss,
    target_completion,
    actual_completion,
    lead_converted_at,
    public.mt_date(lead_converted_at) AS converted_day,
    estimated_value,
    approved_value,
    invoiced_value,
    collected_value,
    deductible,
    total_labor_cost,
    total_material_cost,
    total_equipment_cost,
    total_sub_cost,
    total_other_cost,
    ((((COALESCE(total_labor_cost, (0)::numeric) + COALESCE(total_material_cost, (0)::numeric)) + COALESCE(total_equipment_cost, (0)::numeric)) + COALESCE(total_sub_cost, (0)::numeric)) + COALESCE(total_other_cost, (0)::numeric)) AS total_cost
   FROM public.jobs j;


--
-- Name: rv_leads; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.rv_leads WITH (security_invoker='true') AS
 SELECT id AS lead_id,
    org_id,
    contact_id,
    source_type,
    source,
    medium,
    campaign,
    lead_status,
    value,
    lead_score,
    duration_sec,
    ((source_type = 'call'::text) AND (COALESCE(duration_sec, 0) > 0)) AS is_answered_call,
    ((source_type = 'call'::text) AND (COALESCE(duration_sec, 0) = 0)) AS is_missed_call,
    COALESCE(spam_flag, false) AS spam_flag,
    lost_reason,
    COALESCE(occurred_at, created_at) AS occurred_at,
    public.mt_date(COALESCE(occurred_at, created_at)) AS occurred_day,
    created_at,
    public.mt_date(created_at) AS created_day
   FROM public.inbound_leads il;


--
-- Name: rv_payments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.rv_payments WITH (security_invoker='true') AS
 SELECT id AS payment_id,
    invoice_id,
    job_id,
    contact_id,
    amount,
    payment_method,
    payment_date,
    payer_type,
    payer_name,
    is_deductible,
    is_depreciation_release,
    source,
    stripe_fee,
    refunded_amount,
    created_at,
    public.mt_date(created_at) AS created_day,
    (qbo_payment_id IS NOT NULL) AS is_qbo_synced
   FROM public.payments p;


--
-- Name: rv_time_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.rv_time_entries WITH (security_invoker='true') AS
 SELECT id AS time_entry_id,
    job_id,
    employee_id,
    appointment_id,
    work_date,
    hours,
    travel_minutes,
    total_paused_minutes,
    hourly_rate,
    total_cost,
    (((COALESCE(travel_minutes, (0)::numeric) / 60.0) + COALESCE(hours, (0)::numeric)) * COALESCE(hourly_rate, (0)::numeric)) AS computed_labor_cost,
    work_type,
    approved,
    source,
    clock_in,
    clock_out,
    created_at,
    public.mt_date(created_at) AS created_day
   FROM public.job_time_entries t;


