--
-- Name: service_sms_consent_attestations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_sms_consent_attestations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid NOT NULL,
    phone text NOT NULL,
    consent_scope text NOT NULL,
    consent_method text NOT NULL,
    consent_obtained_on date NOT NULL,
    evidence_note text NOT NULL,
    attestation_version text NOT NULL,
    sender_identity text NOT NULL,
    recorded_by uuid NOT NULL,
    request_ip text,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT service_sms_consent_attestations_evidence_check CHECK (((char_length(btrim(evidence_note)) >= 10) AND (char_length(btrim(evidence_note)) <= 500))),
    CONSTRAINT service_sms_consent_attestations_method_check CHECK ((consent_method = ANY (ARRAY['verbal_permission'::text, 'signed_work_authorization'::text, 'other_written_permission'::text, 'customer_requested_texts'::text, 'other_verified_permission'::text]))),
    CONSTRAINT service_sms_consent_attestations_request_ip_check CHECK (((request_ip IS NULL) OR (((char_length(request_ip) >= 3) AND (char_length(request_ip) <= 64)) AND (request_ip ~ '^[0-9A-Fa-f:.]+$'::text)))),
    CONSTRAINT service_sms_consent_attestations_scope_check CHECK ((consent_scope = 'service_related_customer_project_messages'::text)),
    CONSTRAINT service_sms_consent_attestations_sender_check CHECK ((sender_identity = 'Utah Pros Restoration'::text)),
    CONSTRAINT service_sms_consent_attestations_version_check CHECK ((attestation_version = 'prior_sms_consent_v1'::text))
);

ALTER TABLE ONLY public.service_sms_consent_attestations FORCE ROW LEVEL SECURITY;


