    CONSTRAINT service_sms_consents_method_check CHECK ((consent_method = ANY (ARRAY['verbal_permission'::text, 'signed_work_authorization'::text, 'other_written_permission'::text, 'customer_requested_texts'::text, 'other_verified_permission'::text]))),
    CONSTRAINT service_sms_consents_request_ip_check CHECK (((request_ip IS NULL) OR (((char_length(request_ip) >= 3) AND (char_length(request_ip) <= 64)) AND (request_ip ~ '^[0-9A-Fa-f:.]+$'::text)))),
    CONSTRAINT service_sms_consents_scope_check CHECK ((consent_scope = 'service_related_customer_project_messages'::text)),
    CONSTRAINT service_sms_consents_sender_check CHECK ((sender_identity = 'Utah Pros Restoration'::text)),
    CONSTRAINT service_sms_consents_version_check CHECK ((attestation_version = 'prior_sms_consent_v1'::text))
);

ALTER TABLE ONLY public.service_sms_consents FORCE ROW LEVEL SECURITY;


