CREATE TABLE public.work_authorization_sms_consents (
    sign_request_id uuid NOT NULL,
    contact_id uuid NOT NULL,
    job_id uuid NOT NULL,
    phone text NOT NULL,
    signer_ip text NOT NULL,
    consent_scope text DEFAULT 'service_related_customer_project_messages'::text NOT NULL,
    consent_source text DEFAULT 'upr_signed_work_authorization'::text NOT NULL,
    disclosure_version text NOT NULL,
    disclosure_sha256 text NOT NULL,
    signed_file_path text NOT NULL,
    signed_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_authorization_sms_consents_consent_scope_check CHECK ((consent_scope = 'service_related_customer_project_messages'::text)),
    CONSTRAINT work_authorization_sms_consents_consent_source_check CHECK ((consent_source = 'upr_signed_work_authorization'::text)),
    CONSTRAINT work_authorization_sms_consents_disclosure_sha256_check CHECK ((disclosure_sha256 = '22b2a37dc4094f683da6c0fe1d4955da989733a3a799307129b9fa83cae1265e'::text)),
    CONSTRAINT work_authorization_sms_consents_disclosure_version_check CHECK ((disclosure_version = 'upr_work_auth_sms_v1'::text)),
    CONSTRAINT work_authorization_sms_consents_signed_file_path_check CHECK ((btrim(signed_file_path) <> ''::text)),
    CONSTRAINT work_authorization_sms_consents_signer_ip_check CHECK ((((char_length(signer_ip) >= 3) AND (char_length(signer_ip) <= 64)) AND (signer_ip ~ '^[0-9A-Fa-f:.]+$'::text)))
);

ALTER TABLE ONLY public.work_authorization_sms_consents FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE work_authorization_sms_consents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.work_authorization_sms_consents IS 'Immutable service-SMS evidence derived from a customer-signed UPR Work Authorization; never global/automated consent.';


--
-- Name: COLUMN work_authorization_sms_consents.signer_ip; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_authorization_sms_consents.signer_ip IS 'Trusted Cloudflare connection IP captured by the signing worker; service-role-only evidence and never copied to the broadly readable legacy consent log.';


