--
-- Name: device_tokens Own tokens or admin read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Own tokens or admin read" ON public.device_tokens FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.employees e
  WHERE ((e.auth_user_id = auth.uid()) AND ((e.id = device_tokens.employee_id) OR (e.role = ANY (ARRAY['admin'::public.employee_role, 'project_manager'::public.employee_role])))))));


--
-- Name: account_deletion_requests; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.account_deletion_requests ENABLE ROW LEVEL SECURITY;

--
-- Name: account_deletion_requests account_deletion_requests_admin_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY account_deletion_requests_admin_update ON public.account_deletion_requests FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.employees
  WHERE ((employees.auth_user_id = auth.uid()) AND (employees.role = 'admin'::public.employee_role) AND employees.is_active)))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.employees
  WHERE ((employees.auth_user_id = auth.uid()) AND (employees.role = 'admin'::public.employee_role) AND employees.is_active))));


--
-- Name: account_deletion_requests account_deletion_requests_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY account_deletion_requests_insert ON public.account_deletion_requests FOR INSERT TO authenticated WITH CHECK ((employee_id = ( SELECT employees.id
   FROM public.employees
  WHERE (employees.auth_user_id = auth.uid()))));


--
-- Name: account_deletion_requests account_deletion_requests_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY account_deletion_requests_select ON public.account_deletion_requests FOR SELECT TO authenticated USING (((employee_id = ( SELECT employees.id
   FROM public.employees
  WHERE (employees.auth_user_id = auth.uid()))) OR (EXISTS ( SELECT 1
   FROM public.employees
  WHERE ((employees.auth_user_id = auth.uid()) AND (employees.role = 'admin'::public.employee_role) AND employees.is_active)))));


